// Handle Monthly Subscription - Server ID Input
async function handlePremiumMonthlyServerIdChat(m, conv) {
    const serverId = m.content.trim();
    
    // Validate server ID format
    if (!serverId.match(/^\d{17,19}$/)) {
        await m.channel.send({ 
            content: `<@${m.author.id}> ❌ **آيدي السيرفر غير صحيح!**\n\nيجب أن يكون رقم مكون من 17-19 رقم.\nمثال: \`1234567890123456789\`` 
        });
        return;
    }
    
    // Generate invoice code
    const invoiceCode = `M-${Date.now().toString(36).toUpperCase()}`;
    const price = conv.data.price || 600000;
    const taxAmount = Math.floor(price * (20 / 19) + 1);
    
    // Get transfer bank
    const gConfig = await getGuildConfig(m.guild.id);
    const transferBank = gConfig.transferBank || config.transfer || '1299339997278769223';
    
    // Save ticket data
    await db.set(`premiumTicket_${m.channel.id}`, {
        userId: m.author.id,
        serverId: serverId,
        subscriptionType: 'monthly',
        price: price,
        invoiceCode: invoiceCode,
        createdAt: new Date().toISOString(),
        status: 'pending'
    });
    
    const embed = new EmbedBuilder()
        .setColor('#3B82F6')
        .setTitle('📋 فاتورة الاشتراك الشهري')
        .setDescription(`
**🔹 تفاصيل الطلب:**
• نوع الاشتراك: شهري (30 يوم)
• رقم الفاتورة: \`${invoiceCode}\`
• آيدي السيرفر: \`${serverId}\`

**💰 معلومات الدفع:**
• السعر: \`${price.toLocaleString()}\` كريدت
• بعد الضريبة: \`${taxAmount.toLocaleString()}\` كريدت

**📤 للدفع، انسخ الأمر التالي:**
\`\`\`#credit ${transferBank} ${taxAmount}\`\`\`

⏱️ **لديك 5 دقائق للدفع**
        `)
        .setFooter({ text: invoiceCode });
    
    const row = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(`premium_activate_${m.channel.id}`)
            .setLabel('✅ تفعيل (للمطورين)')
            .setStyle(ButtonStyle.Success)
    );
    
    await m.channel.send({ embeds: [embed], components: [row] });
    endConversation(m.author.id);
    
    // Set up payment verification
    setupPremiumPaymentVerification(m.channel, transferBank, taxAmount, m.author.id);
}

// Handle Lifetime Subscription - Token Input
async function handlePremiumLifetimeTokenChat(m, conv) {
    const token = m.content.trim();
    
    // Delete the message immediately for security
    try { await m.delete(); } catch (e) {}
    
    // Basic token validation
    if (!token.includes('.') || token.length < 50) {
        await m.channel.send({ 
            content: `<@${m.author.id}> ❌ **التوكن غير صحيح!**\n\nتأكد من نسخ التوكن الصحيح من Discord Developer Portal.` 
        });
        return;
    }
    
    // Generate invoice code
    const invoiceCode = `L-${Date.now().toString(36).toUpperCase()}`;
    const price = conv.data.price || 1200000;
    const taxAmount = Math.floor(price * (20 / 19) + 1);
    
    // Get transfer bank
    const gConfig = await getGuildConfig(m.guild.id);
    const transferBank = gConfig.transferBank || config.transfer || '1299339997278769223';
    
    // Encrypt and save token
    const encryptedToken = premiumBotManager.encryptToken(token);
    
    // Save ticket data
    await db.set(`premiumTicket_${m.channel.id}`, {
        userId: m.author.id,
        serverId: m.guild.id,
        subscriptionType: 'lifetime',
        price: price,
        invoiceCode: invoiceCode,
        token: token,  // Will be deleted after activation
        encryptedToken: encryptedToken,
        createdAt: new Date().toISOString(),
        status: 'pending'
    });
    
    const embed = new EmbedBuilder()
        .setColor('#FFD700')
        .setTitle('📋 فاتورة الاشتراك الدائم')
        .setDescription(`
**👑 تفاصيل الطلب:**
• نوع الاشتراك: دائم (Lifetime)
• رقم الفاتورة: \`${invoiceCode}\`
• التوكن: ✅ تم استلامه وتشفيره

**💰 معلومات الدفع:**
• السعر: \`${price.toLocaleString()}\` كريدت
• بعد الضريبة: \`${taxAmount.toLocaleString()}\` كريدت

**📤 للدفع، انسخ الأمر التالي:**
\`\`\`#credit ${transferBank} ${taxAmount}\`\`\`

⏱️ **لديك 5 دقائق للدفع**
        `)
        .setFooter({ text: invoiceCode });
    
    const row = new ActionRowBuilder().addComponents(
        new ButtonBuilder()
            .setCustomId(`premium_activate_${m.channel.id}`)
            .setLabel('✅ تفعيل (للمطورين)')
            .setStyle(ButtonStyle.Success)
    );
    
    await m.channel.send({ 
        content: `<@${m.author.id}> 🔐 **تم استلام التوكن بأمان!**`,
        embeds: [embed], 
        components: [row] 
    });
    endConversation(m.author.id);
    
    // Set up payment verification
    setupPremiumPaymentVerification(m.channel, transferBank, taxAmount, m.author.id);
}

// Setup payment verification for premium subscriptions
function setupPremiumPaymentVerification(channel, transferBank, taxAmount, userId) {
    const filter = ({ content, author: { id } }) => {
        return (
            content.includes('has transferred') &&
            content.includes(`<@!${transferBank}>`) &&
            id === "282859044593598464"  // ProBot ID
        );
    };
    
    const collector = channel.createMessageCollector({
        filter,
        max: 1,
        time: 300000 // 5 minutes
    });
    
    collector.on('collect', async (msg) => {
        const ticketData = await db.get(`premiumTicket_${channel.id}`);
        if (!ticketData) return;
        
        // Update ticket as paid
        await db.set(`premiumTicket_${channel.id}`, {
            ...ticketData,
            paid: true,
            paidAt: new Date().toISOString()
        });
        
        const successEmbed = new EmbedBuilder()
            .setColor('#00FF00')
            .setTitle('✅ تم الدفع بنجاح!')
            .setDescription(`
شكراً لك! تم استلام الدفع.

**الخطوة التالية:**
انتظر حتى يقوم المطور بتفعيل البوت.
            `);
        
        await channel.send({ embeds: [successEmbed] });
        
        // Notify developers
        try {
            const devData = getDevelopers();
            for (const devId of devData.developers) {
                const dev = await client.users.fetch(devId).catch(() => null);
                if (dev) {
                    await dev.send(`🔔 **طلب بريميوم جديد!**\n\nرقم الفاتورة: \`${ticketData.invoiceCode}\`\nالنوع: ${ticketData.subscriptionType}\nالمستخدم: <@${userId}>\n\nالقناة: <#${channel.id}>`).catch(() => {});
                }
            }
        } catch (e) {}
    });
    
    collector.on('end', (collected, reason) => {
        if (reason === 'time' && collected.size === 0) {
            channel.send({ 
                content: `<@${userId}> ⏱️ **انتهى وقت الدفع!**\n\nيرجى البدء من جديد إذا كنت تريد الشراء.` 
            }).catch(() => {});
        }
    });
}
