async function getGuildConfig(guildId) {
    if (!guildId) return { ...defaultGuildConfig };
    const guildConfig = await db.get(`guildConfig_${guildId}`);
    if (!guildConfig) {
        return { ...defaultGuildConfig };
    }
    return { ...defaultGuildConfig, ...guildConfig };
}

async function setGuildConfig(guildId, key, value) {
    if (!guildId) return false;
    await db.set(`guildConfig_${guildId}.${key}`, value);
    return true;
}

async function setFullGuildConfig(guildId, configObj) {
    if (!guildId) return false;
    await db.set(`guildConfig_${guildId}`, configObj);
    return true;
}

async function getGuildValue(guildId, key) {
    if (!guildId) return defaultGuildConfig[key] || "";
    const value = await db.get(`guildConfig_${guildId}.${key}`);
    return value !== undefined ? value : (defaultGuildConfig[key] || "");
}

