// إعدادات البوت
const fs = require('fs');
const crypto = require('crypto');

// Token encryption/decryption functions
const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY || 'endlesbot_default_key_32chars__';
const IV_LENGTH = 16;

function encryptToken(token) {
    try {
        const iv = crypto.randomBytes(IV_LENGTH);
        const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(ENCRYPTION_KEY.padEnd(32).slice(0,32)), iv);
        let encrypted = cipher.update(token);
        encrypted = Buffer.concat([encrypted, cipher.final()]);
        return iv.toString('hex') + ':' + encrypted.toString('hex');
    } catch (e) {
        console.error('Encryption error:', e);
        return token; // Fallback
    }
}

function decryptToken(encryptedToken) {
    try {
        if (!encryptedToken.includes(':')) return encryptedToken; // Not encrypted
        const parts = encryptedToken.split(':');
        const iv = Buffer.from(parts[0], 'hex');
        const encryptedText = Buffer.from(parts[1], 'hex');
        const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(ENCRYPTION_KEY.padEnd(32).slice(0,32)), iv);
        let decrypted = decipher.update(encryptedText);
        decrypted = Buffer.concat([decrypted, decipher.final()]);
        return decrypted.toString();
    } catch (e) {
        console.error('Decryption error:', e);
        return encryptedToken; // Fallback
    }
}
let config = require('./config.json');
config.token = process.env.PREMIUM_BOT_TOKEN || process.env.DISCORD_TOKEN || config.token;
let developersData = require('./developers.json');

// دوال البريميوم
function getDevelopers() {
    try {
        return JSON.parse(fs.readFileSync('./developers.json', 'utf8'));
    } catch {
        return { developers: [], blacklist: { users: [], servers: [] }, premiumBots: [], stats: { totalPremiumSold: 0, totalRevenue: 0, activeBots: 0 } };
    }
}

function saveDevelopers(data) {
    fs.writeFileSync('./developers.json', JSON.stringify(data, null, 2));
    developersData = data;
}

function isDeveloper(userId) {
    const data = getDevelopers();
    return data.developers.includes(userId);
}

function isBlacklisted(userId, serverId) {
    const data = getDevelopers();
    return data.blacklist.users.includes(userId) || data.blacklist.servers.includes(serverId);
}

function addPremiumBot(userId, botToken, serverId, expiryDate, invoiceCode) {
    const data = getDevelopers();
    const premiumBot = {
        id: `PREM-${Date.now()}`,
        userId: userId,
        botToken: botToken,
        serverId: serverId,
        createdAt: new Date().toISOString(),
        expiryDate: expiryDate,
        invoiceCode: invoiceCode,
        status: 'active'
    };
    data.premiumBots.push(premiumBot);
    data.stats.totalPremiumSold++;
    data.stats.activeBots++;
    saveDevelopers(data);
    return premiumBot;
}

function getUserPremiumBots(userId) {
    const data = getDevelopers();
    return data.premiumBots.filter(bot => bot.userId === userId && bot.status === 'active');
}

function generateInvoiceCode() {
    return `INV-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
}


// ============ دوال قاعدة بيانات الميكر ============
function getMakerDB() {
    try {
        return JSON.parse(fs.readFileSync('./makerdb.json', 'utf8'));
    } catch {
        return { premiumBots: [], settings: { premiumPrice: 5000, transferBank: null }, invoices: [], stats: { totalSold: 0, totalRevenue: 0, activeBots: 0 } };
    }
}

function saveMakerDB(data) {
    fs.writeFileSync('./makerdb.json', JSON.stringify(data, null, 2));
}

function getMakerSettings() {
    return getMakerDB().settings;
}

function setMakerSettings(settings) {
    const data = getMakerDB();
    data.settings = { ...data.settings, ...settings };
    saveMakerDB(data);
    return data.settings;
}

function addMakerInvoice(invoice) {
    const data = getMakerDB();
    data.invoices.push(invoice);
    saveMakerDB(data);
    return invoice;
}

function updateMakerInvoice(invoiceCode, updates) {
    const data = getMakerDB();
    const idx = data.invoices.findIndex(i => i.invoiceCode === invoiceCode);
    if (idx !== -1) {
        data.invoices[idx] = { ...data.invoices[idx], ...updates };
        saveMakerDB(data);
        return data.invoices[idx];
    }
    return null;
}

function getMakerStats() {
    const data = getMakerDB();
    return data.stats;
}

function updateMakerStats(stats) {
    const data = getMakerDB();
    data.stats = { ...data.stats, ...stats };
    saveMakerDB(data);
    return data.stats;
}

function checkAndUpdateExpiredPremium() {
    const data = getDevelopers();
    const now = new Date();
    let updated = false;
    
    for (const bot of data.premiumBots) {
        if (bot.status === 'active') {
            const expiry = new Date(bot.expiryDate);
            if (now > expiry) {
                bot.status = 'expired';
                data.stats.activeBots = Math.max(0, data.stats.activeBots - 1);
                updated = true;
                console.log(`⏰ انتهى اشتراك البريميوم: ${bot.id} للمستخدم ${bot.userId}`);
                
                // إرسال فاتورة الانتهاء للمستخدم
                sendPremiumExpiryInvoice(bot);
            }
        }
    }
    
    if (updated) {
        saveDevelopers(data);
    }
}

