// ========================
// Auto Reply & Auto Line Handlers
// ========================
client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;
    
    const guildId = message.guild.id;
    
    // Auto Reply Handler
    try {
        const autoReplies = await db.get(`autoReplies_${guildId}`) || [];
        
        for (const reply of autoReplies) {
            if (!reply.trigger) continue;
            
            // Check if channel is enabled/disabled
            if (reply.disabledChannels && reply.disabledChannels.includes(message.channel.id)) continue;
            if (reply.enabledChannels && reply.enabledChannels.length > 0 && !reply.enabledChannels.includes(message.channel.id)) continue;
            
            // Check if role is enabled/disabled
            if (reply.disabledRoles && reply.disabledRoles.some(r => message.member.roles.cache.has(r))) continue;
            if (reply.enabledRoles && reply.enabledRoles.length > 0 && !reply.enabledRoles.some(r => message.member.roles.cache.has(r))) continue;
            
            // Check trigger match
            let matched = false;
            if (!reply.exactMatch) {
                matched = message.content.toLowerCase().includes(reply.trigger.toLowerCase());
            } else { // exactMatch is true - strict equality
                matched = message.content.toLowerCase() === reply.trigger.toLowerCase();
            }
            
            if (matched) {
                let response = reply.response;
                
                // Pick random response if available
                if (reply.randomReplies && reply.randomReplies.length > 0) {
                    const allResponses = [response, ...reply.randomReplies].filter(r => r);
                    response = allResponses[Math.floor(Math.random() * allResponses.length)];
                }
                
                // Replace variables
                response = response.replace(/\[user\]/g, `<@${message.author.id}>`);
                response = response.replace(/\[userName\]/g, message.author.username);
                response = response.replace(/\[memberCount\]/g, message.guild.memberCount.toString());
                response = response.replace(/\[server\]/g, message.guild.name);
                
                if (reply.asReply) {
                    await message.reply(response);
                } else { // exactMatch is true - strict equality
                    await message.channel.send(response);
                }
                break;
            }
        }
    } catch (error) {
        console.error('Auto reply error:', error);
    }
    
    // Auto Line Handler
    try {
        const autoLineSettings = await db.get(`autoLine_${guildId}`);
        
        if (autoLineSettings && autoLineSettings.enabled) {
            if (autoLineSettings.channels && autoLineSettings.channels.includes(message.channel.id)) {
                const delay = (autoLineSettings.delay || 2) * 1000;
                
                setTimeout(async () => {
                    try {
                        if (autoLineSettings.image) {
                            await message.channel.send(autoLineSettings.image);
                        } else if (autoLineSettings.text) {
                            await message.channel.send(autoLineSettings.text);
                        }
                    } catch (e) {
                        console.error('Auto line send error:', e);
                    }
                }, delay);
            }
        }
    } catch (error) {
        console.error('Auto line error:', error);
    }
});

client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    
    const prefix = '-';
    if (!message.content.startsWith(prefix)) return;
    
    const args = message.content.slice(prefix.length).trim().split(/ +/);
    const command = args.shift().toLowerCase();
    
    // أمر setup بالأزرار - النظام الجديد
    if (command === 'setup') {
        try {
            const guildId = message.guild?.id;
            if (!guildId) return message.reply('❌ **هذا الأمر يعمل فقط داخل سيرفر.**');
            
            const guildConfig = await getGuildConfig(guildId);
            
            // التحقق من الصلاحيات
            if (!message.member.roles.cache.has(guildConfig.admins) && 
                !message.member.permissions.has('Administrator')) {
                return message.reply('❌ **تحتاج إلى صلاحية إدارة السيرفر أو رتبة الأدمن.**');
            }
            
            const embed = new EmbedBuilder()
                .setColor(guildConfig.color || '#051678')
                .setTitle('⚙️ نظام إعدادات البوت')
                .setDescription(`**مرحباً بك في لوحة تحكم السيرفر!**\n\nاختر القسم الذي تريد عرض إعداداته:\n\n• **المزاد** - إعدادات المزادات\n• **المتاجر** - إعدادات المتاجر\n• **الطلبات** - إعدادات الطلبات\n• **الدعم** - إعدادات الدعم الفني\n• **التشهير** - إعدادات بلاغات النصب\n• **الإعلانات** - إعدادات الإعلانات`)
                .setFooter({ text: 'dev by : bh.x7 & _wx10' })
                .setTimestamp();
            
            const row1 = new ActionRowBuilder().addComponents(
                new ButtonBuilder().setCustomId('cat_auction').setLabel('⚔️ المزاد').setStyle(ButtonStyle.Primary),
                new ButtonBuilder().setCustomId('cat_shops').setLabel('🏪 المتاجر').setStyle(ButtonStyle.Primary),
                new ButtonBuilder().setCustomId('cat_orders').setLabel('📝 الطلبات').setStyle(ButtonStyle.Primary),
                new ButtonBuilder().setCustomId('cat_support').setLabel('🎫 الدعم').setStyle(ButtonStyle.Primary)
            );
            
            const row2 = new ActionRowBuilder().addComponents(
                new ButtonBuilder().setCustomId('cat_scam').setLabel('🚫 التشهير').setStyle(ButtonStyle.Danger),
                new ButtonBuilder().setCustomId('cat_ads').setLabel('📢 الإعلانات').setStyle(ButtonStyle.Primary),
                new ButtonBuilder().setCustomId('cat_general').setLabel('⚙️ عام').setStyle(ButtonStyle.Secondary),
                new ButtonBuilder().setCustomId('setup_help').setLabel('❓ مساعدة').setStyle(ButtonStyle.Secondary)
            );
            
            return message.reply({ embeds: [embed], components: [row1, row2] });
            
        } catch (error) {
            console.error('❌ خطأ في setup:', error);
            message.reply('❌ **حدث خطأ أثناء تنفيذ الأمر.**');
        }
    }
});

// نظام الردود التلقائية - معالجة الرسائل
client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    if (!message.guild) return;
    
    try {
        const guildId = message.guild.id;
        const content = message.content.toLowerCase().trim();
        
        // جلب جميع مفاتيح الردود التلقائية للسيرفر
        const allData = await db.all();
        const autoReplies = allData.filter(item => 
            item.id.startsWith(`autoreply_${guildId}_`)
        );
        
        for (const item of autoReplies) {
            const keyword = item.id.replace(`autoreply_${guildId}_`, '').toLowerCase();
            if (content === keyword || content.includes(keyword)) {
                await message.reply(item.value);
                break;
            }
        }
    } catch (error) {
        console.error('خطأ في الردود التلقائية:', error);
    }
});

