async function handlePremiumPayment(interaction, channelId) {
    const ticketData = await db.get(`premiumTicket_${channelId}`);
    if (!ticketData) {
        return await interaction.reply({ content: '❌ **لم يتم العثور على بيانات التذكرة.**', ephemeral: true });
    }
    
    const settings = getMakerSettings();
    const gConfig = await getGuildConfig(interaction.guild.id);
    const transferBank = settings.transferBank || gConfig.transferBank || config.transfer || '1299339997278769223';
    const price = settings.premiumPrice || 5000;
    const taxAmount = Math.floor(price * (20 / 19) + 1);
    
    const embed = new EmbedBuilder()
        .setColor('#FFD700')
        .setTitle('💳 دفع البريميوم')
        .setDescription(`
**السعر:** \`${price}\` كردت
**بعد الضريبة:** \`${taxAmount}\` كردت

**لديك 5 دقائق للدفع**

\`\`\`#credit ${transferBank} ${taxAmount}\`\`\`
        `)
        .setFooter({ text: 'dev by : bh.x7 & _wx10' });
    
    await interaction.reply({ embeds: [embed] });
    
    // إرسال أمر التحويل
    await interaction.channel.send({
        content: `#credit <@!${transferBank}> ${taxAmount}`
    });
    
    // فلتر التحقق من التحويل
    const filter = ({ content, author: { id } }) => {
        return (
            content.startsWith(`**:moneybag: | ${interaction.user.username}, has transferred `) &&
            content.includes(`<@!${transferBank}>`) &&
            id === "282859044593598464"
        );
    };
    
    const collector = interaction.channel.createMessageCollector({
        filter,
        max: 1,
        time: 300000 // 5 دقائق
    });
    
    collector.on('collect', async (msg) => {
        // تم الدفع بنجاح
        await db.set(`premiumTicket_${channelId}`, {
            ...ticketData,
            paid: true,
            paidAt: new Date().toISOString()
        });
        
        const successEmbed = new EmbedBuilder()
            .setColor('#00FF00')
            .setTitle('✅ تم الدفع بنجاح!')
            .setDescription(`
شكراً لك! تم استلام الدفع.

**الخطوة التالية:**
اضغط على زر "🔑 إدخال التوكن" لإكمال التفعيل.
            `);
        
        // إضافة زر التفعيل للمطور
        const row = new ActionRowBuilder()
            .addComponents(
                new ButtonBuilder()
                    .setCustomId(`premium_enter_token_${channelId}`)
                    .setLabel('🔑 إدخال التوكن')
                    .setStyle(ButtonStyle.Success),
                new ButtonBuilder()
                    .setCustomId(`premium_activate_${channelId}`)
                    .setLabel('✅ تفعيل البريميوم')
                    .setStyle(ButtonStyle.Primary)
            );
        
        await interaction.channel.send({ embeds: [successEmbed], components: [row] });
    });
    
    collector.on('end', async (collected, reason) => {
        if (reason === 'time' && collected.size === 0) {
            await interaction.channel.send('⏰ **انتهى الوقت! لم يتم الدفع خلال 5 دقائق.**');
        }
    });
}

