async function showServerRoleTypes(interaction, guildId) {
    const gConfig = await getGuildConfig(guildId);
    const roleTypes = await getGuildRoleTypes(guildId);
    
    if (roleTypes.length === 0) {
        const embed = new EmbedBuilder()
            .setColor(gConfig.color || '#051678')
            .setTitle('🎭 الرتب المخصصة')
            .setDescription('❌ **لا توجد رتب مخصصة مضافة.**\n\nاستخدم `-add-role` لإضافة رتبة جديدة.')
            .setFooter({ text: 'dev by : bh.x7 & _wx10' });
        
        const row = new ActionRowBuilder().addComponents(
            new ButtonBuilder().setCustomId('server_back').setLabel('🔙 رجوع').setStyle(ButtonStyle.Danger)
        );
        
        return await interaction.update({ embeds: [embed], components: [row] });
    }
    
    const rolesList = roleTypes.map((r, i) => 
        `**${i+1}.** ${r.name || 'بدون اسم'}\n` +
        `   └ <a:mg_money1:1459220558158893110> السعر: \`${r.price || 0}\` | 🎭 الرتبة: ${r.roleId ? `<@&${r.roleId}>` : 'غير محدد'}`
    ).join('\n\n');
    
    const embed = new EmbedBuilder()
        .setColor(gConfig.color || '#051678')
        .setTitle('🎭 الرتب المخصصة')
        .setDescription(`**إجمالي الرتب:** \`${roleTypes.length}\`\n\n${rolesList}`)
        .setFooter({ text: 'dev by : bh.x7 & _wx10 | اضغط على الزر لعرض التفاصيل' });
    
    const rows = [];
    const rolesChunks = roleTypes.slice(0, 20);
    
    for (let i = 0; i < rolesChunks.length; i += 5) {
        const chunk = rolesChunks.slice(i, i + 5);
        const row = new ActionRowBuilder().addComponents(
            chunk.map((r, idx) => 
                new ButtonBuilder()
                    .setCustomId(`role_type_details_${r.id}`)
                    .setLabel(`${i + idx + 1}. ${(r.name || 'رتبة').substring(0, 15)}`)
                    .setStyle(ButtonStyle.Primary)
            )
        );
        rows.push(row);
    }
    
    rows.push(new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('server_back').setLabel('🔙 رجوع').setStyle(ButtonStyle.Danger)
    ));
    
    await interaction.update({ embeds: [embed], components: rows.slice(0, 5) });
}

