// عرض قائمة اختيار أنواع المتاجر
async function showShopPricesCategory(interaction, guildId) {
    const gConfig = await getGuildConfig(guildId);
    
    // جلب أنواع المتاجر (خاص بالسيرفر فقط)
    let shopTypes = await getGuildShopTypes(guildId);
    
    const embed = new EmbedBuilder()
        .setColor(gConfig.color || '#051678')
        .setTitle('💵 أسعار المتاجر والمنشنات')
        .setDescription('**اختر نوع المتجر أو اضغط على زر لتعيين سعر المنشن:**\n\n' +
            '**💰 أسعار المنشنات الحالية:**\n' +
            `• @everyone بدون ضريبة: \`${gConfig.no_tax_everyone_price || 'غير معين'}\`\n` +
            `• @everyone مع ضريبة: \`${gConfig.tax_everyone_price || 'غير معين'}\`\n` +
            `• @here بدون ضريبة: \`${gConfig.no_tax_here_price || 'غير معين'}\`\n` +
            `• @here مع ضريبة: \`${gConfig.tax_here_price || 'غير معين'}\`\n` +
            `• منشن عادي بدون ضريبة: \`${gConfig.no_tax_nomen_price || 'غير معين'}\`\n` +
            `• منشن عادي مع ضريبة: \`${gConfig.tax_nomen_price || 'غير معين'}\`\n` +
            `• سعر إزالة التحذير: \`${gConfig.priceRemoveWarning || 50}\` كريدت`)
        .setFooter({ text: 'dev by : bh.x7 & _wx10' });
    
    const components = [];
    
    // صف أزرار أسعار المنشنات - @everyone
    const row1 = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('show_price_no_tax_everyone_price').setLabel('💵 @everyone بدون ضريبة').setStyle(ButtonStyle.Success),
        new ButtonBuilder().setCustomId('show_price_tax_everyone_price').setLabel('💵 @everyone مع ضريبة').setStyle(ButtonStyle.Success)
    );
    components.push(row1);
    
    // صف أزرار أسعار المنشنات - @here
    const row2 = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('show_price_no_tax_here_price').setLabel('💵 @here بدون ضريبة').setStyle(ButtonStyle.Primary),
        new ButtonBuilder().setCustomId('show_price_tax_here_price').setLabel('💵 @here مع ضريبة').setStyle(ButtonStyle.Primary)
    );
    components.push(row2);
    
    // صف أزرار أسعار المنشنات العادية + إزالة التحذير
    const row3 = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('show_price_no_tax_nomen_price').setLabel('💵 منشن بدون ضريبة').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('show_price_tax_nomen_price').setLabel('💵 منشن مع ضريبة').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('show_price_priceRemoveWarning').setLabel('⚠️ سعر إزالة التحذير').setStyle(ButtonStyle.Danger)
    );
    components.push(row3);
    
    // إضافة قائمة أنواع المتاجر إذا كانت موجودة
    if (shopTypes.length > 0) {
        const selectMenu = new StringSelectMenuBuilder()
            .setCustomId('select_shop_type_price')
            .setPlaceholder('🏪 اختر نوع المتجر لعرض مواصفاته...')
            .addOptions(shopTypes.map(t => ({
                label: t.name || t.id,
                description: `السعر: ${t.price || 0}$ | الضريبة: ${t.tax || 0}$`,
                value: t.id
            })));
        components.push(new ActionRowBuilder().addComponents(selectMenu));
    }
    
    // صف الرجوع
    const rowBack = new ActionRowBuilder().addComponents(
        new ButtonBuilder().setCustomId('setup_back_shops').setLabel('🔙 رجوع للمتاجر').setStyle(ButtonStyle.Secondary),
        new ButtonBuilder().setCustomId('setup_back').setLabel('🏠 القائمة الرئيسية').setStyle(ButtonStyle.Danger)
    );
    components.push(rowBack);
    
    await interaction.update({ embeds: [embed], components: components });
}

