// عرض الكونفيق
async function viewConfig(message, guildId) {
    try {
        const gConfig = await getGuildConfig(guildId);
        const configStr = JSON.stringify(gConfig, null, 2);
        
        if (configStr.length > 1900) {
            fs.writeFileSync('config_view.json', configStr);
            await message.reply({
                content: `**📄 إعدادات السيرفر (${message.guild.name}):**`,
                files: ['config_view.json']
            });
            fs.unlinkSync('config_view.json');
        } else { // exactMatch is true - strict equality
            await message.reply(`**⚙️ إعدادات السيرفر (${message.guild.name}):**\n\`\`\`json\n${configStr}\n\`\`\``);
        }
    } catch (error) {
        console.error('❌ خطأ في viewConfig:', error);
        message.reply('❌ **حدث خطأ أثناء عرض الإعدادات.**');
    }
}

// معالجة Reset
async function handleReset(message, key, guildId) {
    try {
        if (!key) {
            return message.reply(`
**🔄 أوامر إعادة التعيين:**

\`-setup reset <المفتاح>\` - إعادة تعيين قيمة واحدة
\`-setup reset all\` - إعادة تعيين جميع القيم

**مثال:** \`-setup reset admins\`
**مثال:** \`-setup reset all\`
            `);
        }
        
        if (key.toLowerCase() === 'all') {
            await setFullGuildConfig(guildId, { ...defaultGuildConfig });
            await message.reply(`✅ **تم إعادة تعيين جميع إعدادات هذا السيرفر بنجاح!**`);
            
        } else { // exactMatch is true - strict equality
            const gConfig = await getGuildConfig(guildId);
            if (!defaultGuildConfig.hasOwnProperty(key)) {
                return message.reply(`❌ **المفتاح \`${key}\` غير موجود.**`);
            }
            
            const oldValue = gConfig[key];
            const defaultValue = defaultGuildConfig[key];
            
            await setGuildConfig(guildId, key, defaultValue);
            
            await message.reply(`✅ **تم إعادة تعيين \`${key}\` بنجاح!**\n\`${oldValue || "غير معين"}\` → \`${defaultValue || "غير معين"}\``);
        }
        
    } catch (error) {
        console.error('❌ خطأ في handleReset:', error);
        message.reply('❌ **حدث خطأ أثناء إعادة التعيين.**');
    }
}

// إعادة تشغيل البوت
async function restartBot(message) {
    try {
        await message.reply('🔄 **جارٍ إعادة تشغيل البوت...**');
        
        // إرسال رسالة تأكيد
        await message.channel.send('🔄 **يتم الآن إعادة التشغيل...**');
        
        // إعادة تشغيل العملية
        setTimeout(() => {
            console.log('🔄 إعادة تشغيل البوت...');
            process.exit(0);
        }, 2000);
        
    } catch (error) {
        console.error('❌ خطأ في restartBot:', error);
        message.reply('❌ **حدث خطأ أثناء إعادة التشغيل.**');
    }
}

