// أمر إعداد المتجر
client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    
    const prefix = '-';
    if (!message.content.startsWith(prefix)) return;
    
    const args = message.content.slice(prefix.length).trim().split(/ +/);
    const command = args.shift().toLowerCase();
    
    if (command === 'setup-shop') {
        try {
            // التحقق من الصلاحيات
            const config = require('./config.json');
            if (!message.member.roles.cache.has(config.admins) && 
                !message.member.permissions.has('Administrator')) {
                return message.reply('❌ **تحتاج إلى صلاحية إدارة السيرفر أو رتبة الأدمن.**');
            }
            
            // البحث عن أول متجر فارغ
            let emptyShopIndex = -1;
            for (let i = 0; i < types.length; i++) {
                if (!types[i].id && !types[i].name) {
                    emptyShopIndex = i;
                    break;
                }
            }
            
            if (emptyShopIndex === -1) {
                const fullEmbed = {
                    color: 0xff0000,
                    title: '❌ لا توجد مقاعد شاغرة',
                    description: 'جميع المتاجر الخمسة مملوءة!',
                    fields: [
                        {
                            name: '💡 الحلول المتاحة',
                            value: '1. استخدم `-shop-list` لعرض المتاجر\n2. احذف متجراً لتتمكن من إضافة جديد'
                        }
                    ]
                };
                return message.reply({ embeds: [fullEmbed] });
            }
            
            const shopNumber = emptyShopIndex + 1;
            
            const selectEmbed = {
                color: 0x00ff00,
                title: '🛒 بدء إعداد متجر جديد',
                description: `سيتم إعداد المتجر في الموقع **#${shopNumber}**`,
                fields: [
                    {
                        name: '📋 خطوات الإعداد',
                        value: 'سيطلب منك النظام إدخال **9 معلومات** بالترتيب:\n1️⃣ المعرف\n2️⃣ الاسم\n3️⃣ البادئة\n4️⃣ الرتبة\n5️⃣ عدد EVERY\n6️⃣ عدد HERE\n7️⃣ عدد SHOPS\n8️⃣ الضريبة\n9️⃣ السعر'
                    },
                    {
                        name: '⚠️ ملاحظة مهمة',
                        value: 'جميع الحقول إلزامية، سيتم ملء المتجر بالكامل'
                    }
                ],
                footer: {
                    text: '📝 ابدأ بإرسال المعرف (ID) الآن'
                }
            };
            
            const setupMsg = await message.reply({ embeds: [selectEmbed] });
            
            shopSetupUsers.set(message.author.id, {
                step: 'id',
                messageId: setupMsg.id,
                channelId: message.channel.id,
                timestamp: Date.now(),
                shopIndex: emptyShopIndex,
                data: {}
            });
            
        } catch (error) {
            console.error('❌ خطأ في setup-shop:', error);
            message.reply('❌ **حدث خطأ أثناء بدء الإعداد.**');
        }
    }
});

// استقبال ردود المستخدم للمتاجر
client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    
    const userData = shopSetupUsers.get(message.author.id);
    if (!userData) return;
    
    if (message.channel.id !== userData.channelId) return;
    
    try {
        await message.delete().catch(() => {});
        
        switch (userData.step) {
            case 'id':
                await handleShopId(message, userData);
                break;
            case 'name':
                await handleShopName(message, userData);
                break;
            case 'prefix':
                await handleShopPrefix(message, userData);
                break;
            case 'role':
                await handleShopRole(message, userData);
                break;
            case 'every':
                await handleShopEvery(message, userData);
                break;
            case 'here':
                await handleShopHere(message, userData);
                break;
            case 'shop':
                await handleShopCount(message, userData);
                break;
            case 'tax':
                await handleShopTax(message, userData);
                break;
            case 'price':
                await handleShopPrice(message, userData);
                break;
        }
        
    } catch (error) {
        console.error('❌ خطأ في معالجة الرد:', error);
        const errorMsg = await message.channel.send('❌ **حدث خطأ أثناء الإعداد.**');
        setTimeout(() => errorMsg.delete(), 5000);
        shopSetupUsers.delete(message.author.id);
    }
});

// معالجة معرف المتجر
async function handleShopId(message, userData) {
    const shopId = message.content.trim();
    
    if (!/^\d{17,19}$/.test(shopId)) {
        const errorMsg = await message.channel.send('❌ **يجب إدخال معرف صحيح (17-19 رقم)**');
        setTimeout(() => errorMsg.delete(), 5000);
        return;
    }
    
    userData.data.id = shopId;
    userData.step = 'name';
    
    const nameEmbed = {
        color: 0x0099ff,
        title: '✅ الخطوة 1/9 - المعرف',
        description: `تم حفظ المعرف: \`${shopId}\``,
        fields: [
            {
                name: '📌 الخطوة 2/9',
                value: '**أرسل اسم المتجر**'
            },
            {
                name: '💡 مثال',
                value: '`・◜₊˚ ‹ 🍁・𝑴𝒚𝒕𝒉𝒊𝒄𝒂𝒍 ⭑ ◞`',
                inline: true
            },
            {
                name: '📝 التنسيق',
                value: '2-100 حرف، يمكن استخدام رموز',
                inline: true
            }
        ],
        footer: {
            text: 'متبقي 8 خطوات'
        }
    };
    
    try {
        const originalMessage = await message.channel.messages.fetch(userData.messageId);
        await originalMessage.edit({ embeds: [nameEmbed] });
    } catch {
        await message.channel.send({ embeds: [nameEmbed] });
    }
    
    shopSetupUsers.set(message.author.id, userData);
}

