async function handleShopPrice(message, userData) {
    const price = parseInt(message.content);
    
    if (isNaN(price) || price < 0 || price > 10000000) {
        const errorMsg = await message.channel.send('❌ **يجب إدخال سعر صحيح بين 0 و 10,000,000**');
        setTimeout(() => errorMsg.delete(), 5000);
        return;
    }
    
    userData.data.price = price;
    
    await saveShopData(message, userData);
    shopSetupUsers.delete(message.author.id);
}

// حفظ البيانات في الملف
async function saveShopData(message, userData) {
    try {
        const shopIndex = userData.shopIndex;
        
        // إنشاء كائن متجر كامل بجميع الخصائص
        const newShop = {
            id: userData.data.id,
            name: userData.data.name,
            prefix: userData.data.prefix,
            role: userData.data.role,
            every: userData.data.every,
            here: userData.data.here,
            shop: userData.data.shop,
            tax: userData.data.tax,
            price: userData.data.price
        };
        
        // التحقق من أن جميع الخصائص مملوءة
        const requiredFields = ['id', 'name', 'prefix', 'role', 'every', 'here', 'shop', 'tax', 'price'];
        const missingFields = requiredFields.filter(field => !newShop[field] && newShop[field] !== 0);
        
        if (missingFields.length > 0) {
            const errorEmbed = {
                color: 0xff0000,
                title: '❌ خطأ في البيانات',
                description: 'بعض الحقول مفقودة!',
                fields: [
                    {
                        name: 'الحقول المفقودة',
                        value: missingFields.map(f => `\`${f}\``).join(', ')
                    }
                ]
            };
            return await message.channel.send({ embeds: [errorEmbed] });
        }
        
        // تحديث المصفوفة
        types[shopIndex] = newShop;
        
        // حفظ الملف
        const fileContent = `const types = ${JSON.stringify(types, null, 4)};\n\nmodule.exports = types;`;
        fs.writeFileSync('./types.js', fileContent);
        
        const role = message.guild.roles.cache.get(newShop.role) || { toString: () => 'غير محدد' };
        
        const resultEmbed = {
            color: 0x00ff00,
            title: '🎉 تم إنشاء متجر جديد بنجاح!',
            description: `تم حفظ المتجر في الموقع **#${shopIndex + 1}**`,
            fields: [
                {
                    name: '📊 المعلومات الأساسية',
                    value: `**الاسم:** ${newShop.name}\n**المعرف:** ${newShop.id}\n**البادئة:** ${newShop.prefix}`,
                    inline: false
                },
                {
                    name: '👑 الرتبة',
                    value: `${role}`,
                    inline: true
                },
                {
                    name: '🔢 الإعدادات',
                    value: `**EVERY:** ${newShop.every}\n**HERE:** ${newShop.here}\n**SHOP:** ${newShop.shop}`,
                    inline: true
                },
                {
                    name: '💰 الأسعار',
                    value: `**TAX:** ${newShop.tax}\n**PRICE:** ${newShop.price} 💎`,
                    inline: true
                }
            ],
            timestamp: new Date(),
            footer: {
                text: `تم الإنشاء بواسطة ${message.author.username} | ${new Date().toLocaleString()}`
            }
        };
        
        await message.channel.send({ embeds: [resultEmbed] });
        
        try {
            const originalMessage = await message.channel.messages.fetch(userData.messageId);
            await originalMessage.delete();
        } catch {}
        
        // عرض ملخص بعد الحفظ
        setTimeout(async () => {
            const summaryEmbed = {
                color: 0x0099ff,
                title: '📈 حالة المتاجر الحالية',
                description: `تم ملء ${countFilledShops()} من أصل 5 مقاعد`,
                fields: [
                    {
                        name: 'المتاجر المملوءة',
                        value: types.map((shop, idx) => 
                            shop.id ? `#${idx + 1} ✅ ${shop.name}` : `#${idx + 1} ⭕ فارغ`
                        ).join('\n')
                    }
                ],
                footer: {
                    text: 'يمكنك إضافة متجر آخر باستخدام -setup-shop'
                }
            };
            
            await message.channel.send({ embeds: [summaryEmbed] });
        }, 1000);
        
    } catch (error) {
        console.error('❌ خطأ في حفظ البيانات:', error);
        const errorEmbed = {
            color: 0xff0000,
            title: '❌ خطأ في الحفظ',
            description: 'حدث خطأ أثناء حفظ المتجر',
            fields: [
                {
                    name: 'تفاصيل الخطأ',
                    value: error.message.substring(0, 500)
                }
            ]
        };
        
        await message.channel.send({ embeds: [errorEmbed] });
    }
}

// دالة مساعدة لحساب المتاجر المملوءة
function countFilledShops() {
    return types.filter(shop => shop.id && shop.name).length;
}

// أمر لعرض المتاجر الحالية
client.on('messageCreate', async (message) => {
    if (message.author.bot) return;
    
    const prefix = '-';
    if (!message.content.startsWith(prefix)) return;
    
    const args = message.content.slice(prefix.length).trim().split(/ +/);
    const command = args.shift().toLowerCase();
    
    if (command === 'shop-list') {
        try {
            const filledCount = countFilledShops();
            
            if (filledCount === 0) {
                const emptyEmbed = {
                    color: 0xffa500,
                    title: '📭 جميع المقاعد فارغة',
                    description: 'لم يتم إعداد أي متاجر بعد',
                    fields: [
                        {
                            name: '💡 كيف تضيف متجر؟',
                            value: 'استخدم الأمر `-setup-shop` لبدء إعداد متجر جديد كامل'
                        },
                        {
                            name: 'المقاعد المتاحة',
                            value: '5 مقاعد شاغرة ⭕⭕⭕⭕⭕'
                        }
                    ]
                };
                return await message.reply({ embeds: [emptyEmbed] });
            }
            
            const listEmbed = {
                color: 0x0099ff,
                title: `🛍️ قائمة المتاجر (${filledCount}/5)`,
                description: 'جميع المتاجر المملوءة في النظام',
                fields: [],
                timestamp: new Date(),
                footer: {
                    text: `طلب بواسطة ${message.author.username}`
                }
            };
            
            types.forEach((shop, index) => {
                if (shop.id) {
                    const roleMention = shop.role ? `<@&${shop.role}>` : '❌';
                    listEmbed.fields.push({
                        name: `#${index + 1} ${shop.name}`,
                        value: `**المعرف:** \`${shop.id}\`\n**الرتبة:** ${roleMention}\n**السعر:** ${shop.price} 💎\n**الحالة:** ✅ مكتمل`,
                        inline: false
                    });
                } else { // exactMatch is true - strict equality
                    listEmbed.fields.push({
                        name: `#${index + 1} مقعد شاغر`,
                        value: '⭕ متاح للإعداد\nاستخدم `-setup-shop`',
                        inline: false
                    });
                }
            });
            
            await message.reply({ embeds: [listEmbed] });
            
        } catch (error) {
            console.error('❌ خطأ في shop-list:', error);
            const errorEmbed = {
                color: 0xff0000,
                title: '❌ خطأ في العرض',
                description: 'حدث خطأ أثناء عرض قائمة المتاجر'
            };
            await message.reply({ embeds: [errorEmbed] });
        }
    }
});

