                // 5. إرسال رسالة النجاح في القناة الحالية
                const successEmbed = new EmbedBuilder()
                    .setTitle('تمت عملية الشراء بنجاح')
                    .setDescription(`تم دفع ضريبة المتجر بنجاح\nالمتجر : <#${shopId}>`)
                    .setFooter({ text: 'dev by : bh.x7 & _wx10' })
                    .setImage(config.line || null)
