// دالة لإرسال الأخطاء إلى الروم المخصص
async function sendErrorToLogChannel(error, context = '', guildId = null) {
    try {
        let errorLogChannelId = null;
        
        if (guildId) {
            const gConfig = await getGuildConfig(guildId);
            errorLogChannelId = gConfig.consoleRoom;
        }
        
        if (!errorLogChannelId) return;
        
        const errorChannel = client.channels.cache.get(errorLogChannelId);
        if (!errorChannel) {
            return;
        }

        // تحضير رسالة الخطأ
        const errorMessage = `**🛑 خطأ جديد ${context ? `في ${context}` : ''}**\n\n` +
                            `**الوقت:** <t:${Math.floor(Date.now() / 1000)}:F>\n` +
                            `**الخطأ:** \`\`\`${error.message || error}\`\`\`\n` +
                            `**المكدس:** \`\`\`${error.stack || 'لا يوجد'}\`\`\``;

        // تقسيم الرسالة إذا كانت طويلة
        if (errorMessage.length > 2000) {
            const parts = [];
            const maxLength = 1900;
            
            // جزء المعلومات الأساسية
            const header = `**🛑 خطأ جديد ${context ? `في ${context}` : ''}**\n\n` +
                          `**الوقت:** <t:${Math.floor(Date.now() / 1000)}:F>\n`;
            parts.push(header);
            
            // جزء رسالة الخطأ
            const errorPart = `**الخطأ:** \`\`\`${(error.message || error).substring(0, 1000)}\`\`\``;
            parts.push(errorPart);
            
            // جزء المكدس (إذا كان موجوداً)
            if (error.stack) {
                const stackPart = `**المكدس:** \`\`\`${error.stack.substring(0, 1900)}\`\`\``;
                parts.push(stackPart);
            }
            
            // إرسال الأجزاء
            parts.forEach(async (part, index) => {
                setTimeout(async () => {
                    try {
                        await errorChannel.send(part);
                    } catch (sendError) {
                        console.error('❌ خطأ في إرسال جزء من الخطأ:', sendError);
                    }
                }, index * 1000);
            });
        } else { // exactMatch is true - strict equality
            // إرسال الرسالة كاملة إذا كانت قصيرة
            errorChannel.send(errorMessage);
        }

        console.log('✅ تم إرسال الخطأ إلى روم الأخطاء');
    } catch (logError) {
        console.error('❌ خطأ في إرسال الخطأ إلى الروم:', logError);
    }
}

// معالج الأخطاء العالمي
process.on('uncaughtException', (error) => {
    console.error('🛑 خطأ غير معالج:', error);
    sendErrorToLogChannel(error, 'uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
    console.error('🛑 رفض غير معالج:', reason);
    const error = reason instanceof Error ? reason : new Error(String(reason));
    sendErrorToLogChannel(error, 'unhandledRejection');
});




