// معالجة أخطاء الذاكرة
process.on('warning', (warning) => {
    if (warning.name === 'MaxListenersExceededWarning') {
        console.warn('⚠️ تحذير: تجاوز الحد الأقصى للمستمعين');
        const warningEmbed = new EmbedBuilder()
            .setTitle('⚠️ تحذير ذاكرة')
            .setDescription(`**نوع التحذير:** ${warning.name}\n**الرسالة:** ${warning.message}`)
            .setColor('#ff9900')
            .setTimestamp();
        
        sendErrorToLogChannel(warning, 'Memory Warning');
    }
});

// دالة مساعدة لتسجيل الأخطاء يدوياً
function logErrorManually(error, location = '', additionalInfo = {}) {
    try {
        const errorChannel = client.channels.cache.get(errorLogChannelId);
        if (!errorChannel) {
            console.error('❌ روم الأخطاء غير موجود');
            return;
        }

        const embed = new EmbedBuilder()
            .setTitle('📝 خطأ مسجل يدوياً')
            .setColor('#ff0000')
            .addFields(
                { name: '📍 الموقع', value: location || 'غير محدد', inline: true },
                { name: '⏰ الوقت', value: `<t:${Math.floor(Date.now() / 1000)}:F>`, inline: true },
                { name: '📄 نوع الخطأ', value: error.name || 'Error', inline: true }
            )
            .setTimestamp();

        // إضافة رسالة الخطأ
        if (error.message) {
            embed.addFields({ 
                name: '💬 الرسالة', 
                value: `\`\`\`${error.message.substring(0, 1000)}\`\`\``,
                inline: false 
            });
        }

        // إضافة المكدس إذا كان موجوداً
        if (error.stack) {
            const stackPreview = error.stack.split('\n').slice(0, 5).join('\n');
            embed.addFields({ 
                name: '🔍 جزء من المكدس', 
                value: `\`\`\`${stackPreview.substring(0, 500)}\`\`\``,
                inline: false 
            });
        }

        // إضافة معلومات إضافية
        if (Object.keys(additionalInfo).length > 0) {
            let infoText = '';
            for (const [key, value] of Object.entries(additionalInfo)) {
                infoText += `**${key}:** ${value}\n`;
            }
            embed.addFields({ 
                name: '📋 معلومات إضافية', 
                value: infoText,
                inline: false 
            });
        }

        errorChannel.send({ embeds: [embed] });
        console.log('✅ تم تسجيل الخطأ يدوياً');
    } catch (logError) {
        console.error('❌ خطأ في التسجيل اليدوي:', logError);
    }
}

