// ======================= نظام الحماية من الاستخدام غير المصرح =======================

client.on("messageCreate", async (message) => {
  if (message.author.bot) return;

  const prefix = "متجر";
  if (!message.content.startsWith(prefix)) return;

  const mentionedUser = message.mentions.users.first();
  if (!mentionedUser) {
    return message.reply("**رجاءً قم بمنشن الشخص الذي تريد عرض متاجره.**");
  }

  if (!message.member.permissions.has(PermissionFlagsBits.Administrator)) {
    return;
  }

  try {
    // جلب جميع القنوات النصية
    const textChannels = message.guild.channels.cache.filter(ch => 
      ch.type === ChannelType.GuildText
    );

    const userShops = [];
    
    // البحث في كل قناة
    for (const channel of textChannels.values()) {
      try {
        const data = await db.get(`shop_${channel.id}`);
        
        if (data) {
          // تحقق من أن المستخدم هو المالك
          if (data.ownerId === mentionedUser.id || 
              data.owner === mentionedUser.id || 
              data.userId === mentionedUser.id) {
            
            userShops.push({
              channelId: channel.id,
              channelName: channel.name,
              data: data
            });
          }
        }
      } catch (error) {
        continue;
      }
    }

    if (userShops.length === 0) {
      return message.reply(`**لا يــوجــد مــــتــــاجــــر لـــ ${mentionedUser.username}**`);
    }

    // حساب الإحصائيات
    const totalHelpers = userShops.reduce((sum, shop) => 
      sum + (shop.data.partners ? shop.data.partners.length : 0), 0);
    
    const totalWarnings = userShops.reduce((sum, shop) => 
      sum + (shop.data.warns ? shop.data.warns : 0), 0);

    // إنشاء قائمة المتاجر بالشكل المطلوب
    let shopList = "";
    userShops.forEach((shop, index) => {
      const warns = shop.data.warns || 0;
      const shopType = shop.data.role ? `<@&${shop.data.role}>` : (shop.data.typeName || "غير محدد");
      const date = shop.data.date || shop.data.createdAt || "غير معروف";
      
      // تحويل قائمة IDs الشركاء إلى منشنات
      let partnersMentions = 'لا يوجد مساعدين';
      if (shop.data.partners && shop.data.partners.length > 0) {
        partnersMentions = shop.data.partners.map(partnerId => `<@${partnerId}>`).join(' , ');
      }
      
      // الترقيم العربي
      const arabicNumbers = ['١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩', '١٠'];
      const arabicIndex = index < 10 ? arabicNumbers[index] : `${index + 1}`;
      
      // بناء معلومات المتجر بالشكل المطلوب
      shopList += `**${arabicIndex} - المتجر : <#${shop.channelId}>**\n`;
      shopList += `نوعه : ${shopType}\n`;
      shopList += `عدد تحذيراته : ${warns}\n`;
      shopList += `المساعدين : ${partnersMentions}\n`;
      shopList += `الانشاء : ${date}\n\n`;
    });

    // إنشاء الإمبد
    const embed = new EmbedBuilder()
      .setTitle(`**تقرير متاجر ${mentionedUser.username}**`)
      .setDescription(
        `**المستخدم:** <@${mentionedUser.id}>\n` +
        `**معلومات متاجر المستخدم:**\n` +
        `**عدد المتاجر:** ${userShops.length}\n` +
        `**إجمالي المساعدين:** ${totalHelpers}\n` +
        `**إجمالي التحذيرات:** ${totalWarnings}\n` +
        `\n**قائمة المتاجر:**\n${shopList}`
      )
      .setColor(totalWarnings > 0 ? '#ff9900' : '#00ff00')
      .setThumbnail(mentionedUser.displayAvatarURL())
      .setFooter({
        text: `تم الطلب بواسطة: ${message.author.username}`,
        iconURL: message.author.displayAvatarURL()
      })
      .setTimestamp();

    await message.reply({ 
      content: `<@${mentionedUser.id}>`,
      embeds: [embed] 
    });
    
  } catch (error) {
    console.error("خطأ في أمر المتاجر:", error);
    message.reply(`**حــدث خــطــا: ${error.message}**`);
  }
});
