client.on("messageCreate", async (message) => {
  if(message.content == "تجار") {
    // التحقق من رتبة الإدارة
    if (!message.member.roles.cache.has(config.admins)) return;
    if(message.author.bot) return;
    
    const guildShopTypes = await getGuildShopTypes(message.guild.id);
    if (guildShopTypes.length === 0) {
      return message.reply('❌ **لا توجد أنواع متاجر مضافة.**');
    }
    
    const roleMentions = guildShopTypes.map(t => t.role ? `<@&${t.role}>` : '').filter(Boolean).join('\n');
    message.reply({ 
      content: roleMentions || '❌ **لا توجد رتب متاجر.**'
    });
    return;
  }
});

