client.on('messageCreate', async (message) => {
    if (!message.guild || message.author.bot) return;
    
    if (message.content === '!قوانين') {
        // التحقق من صلاحية Administrator
        if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
            return message.reply({ 
                content: 'يجب أن تكون لديك صلاحية Administrator لاستخدام هذا الأمر!', 
                ephemeral: true 
            });
        }

        // طلب إدخال ايدي الروم
        await message.reply('**يرجى إرسال ايدي الروم الذي تريد إرسال القوانين فيه:**');
        
        const channelFilter = m => m.author.id === message.author.id;
        const channelCollector = message.channel.createMessageCollector({
            filter: channelFilter,
            max: 1,
            time: 30000
        });

        channelCollector.on('collect', async (msg) => {
            const targetChannelId = msg.content.trim();
            
            try {
                const targetChannel = await message.guild.channels.fetch(targetChannelId);
                
                if (!targetChannel || !targetChannel.isTextBased()) {
                    return msg.reply('لم يتم العثور على الروم أو الروم ليس نصي!');
                }

                // حذف رسالة الايدي
                await msg.delete().catch(() => {});

                // إنشاء الإمبد الرئيسي
                const gConfigLaws = await getGuildConfig(message.guild.id);
                const embed = new EmbedBuilder()
                    .setAuthor({ 
                        name: message.guild.name, 
                        iconURL: message.guild.iconURL() 
                    }) 
                    .setFooter({ 
                        text: message.guild.name, 
                        iconURL: message.guild.iconURL() 
                    }) 
                    .setThumbnail(message.guild.iconURL())
                    .setTitle(gConfigLaws.mainLawsTitle || `تنظيم قوانين السيرفر`)
                    .setDescription(gConfigLaws.mainLawsDescription || `**الرجاء اختيار القوانين التي تريدها بالاسفل**`)
                    .setImage(gConfigLaws.mainLawsImage || config.banner || config.Line || config.line)  
                    .setColor(gConfigLaws.lawsColor || gConfigLaws.color || config.color || '#051678');
               
                // إنشاء أزرار القوانين
                const row1 = new ActionRowBuilder()
                    .addComponents(
                        new ButtonBuilder()
                            .setCustomId('laws_stores')
                            .setLabel('قوانين المتاجر')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>'),

                        new ButtonBuilder()
                            .setCustomId('laws_general')
                            .setLabel('قوانين عامة')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>'),

                        new ButtonBuilder()
                            .setCustomId('laws_auction')
                            .setLabel('قوانين المزاد')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>')
                    );
                
                const row2 = new ActionRowBuilder()
                    .addComponents(
                        new ButtonBuilder()
                            .setCustomId('laws_requests')
                            .setLabel('قوانين طلبات')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>'),

                        new ButtonBuilder()
                            .setCustomId('laws_ads')
                            .setLabel('قوانين الإعلان والبارتنر')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>'),

                        new ButtonBuilder()
                            .setCustomId('laws_exchange')
                            .setLabel('قوانين التبادل')
                            .setStyle(ButtonStyle.Secondary)
                            .setEmoji('<a:011:1321162636749967441>')
                    );

                
                    

                // إرسال إلى الروم المحدد
                const lawsMessage = await targetChannel.send({ 
                    embeds: [embed], 
                    components: [row1, row2] 
                });

                // تأكيد الإرسال
                await message.reply(`تم إرسال لوحة القوانين إلى: <#${targetChannel.id}>`);

                // حفظ بيانات الرسالة للتحكم بها
                await db.set(`laws_message_${targetChannel.id}`, {
                    messageId: lawsMessage.id,
                    channelId: targetChannel.id,
                    sentBy: message.author.id,
                    sentAt: Date.now()
                });

            } catch (error) {
                console.error('Error sending laws:', error);
                await message.reply('حدث خطأ أثناء إرسال القوانين!');
            }
        });

        channelCollector.on('end', (collected, reason) => {
            if (reason === 'time' && collected.size === 0) {
                message.reply('انتهى وقت الإدخال!');
            }
        });
    }
});



client.on('interactionCreate', async interaction => {
    if (!interaction.isButton()) return;

    // عند الضغط على زر "إزالة تشهير"
    if (interaction.customId.startsWith('remove-tashheer_')) {
        // استخراج الـ ID من الـ customId
        const suspectUserId = interaction.customId.split('_')[1];
        
        // التحقق من الصلاحيات
        if (!interaction.member.roles.cache.has(`${config.scamadmins}`)) {
            return interaction.reply({ content: 'أنت لا تمتلك الصلاحيات لحذف هذا البلاغ!', ephemeral: true });
        }

        await interaction.deferReply({ ephemeral: true });

        try {
            // 1. محاولة فك الباند
            try {
                const bans = await interaction.guild.bans.fetch();
                const isBanned = bans.has(suspectUserId);
                
                if (isBanned) {
                    await interaction.guild.members.unban(suspectUserId, `إزالة تشهير بواسطة ${interaction.user.tag}`);
                    console.log(`فك الباند عن المستخدم: ${suspectUserId}`);
                }
            } catch (banError) {
                console.log('المستخدم غير مبند أو خطأ في فك الباند:', banError);
            }

            // 2. إزالة رتبة النصاب إذا كانت موجودة
            try {
                if (config.scammerRole) {
                    const member = await interaction.guild.members.fetch(suspectUserId).catch(() => null);
                    if (member) {
                        await member.roles.remove(config.scammerRole, `إزالة تشهير بواسطة ${interaction.user.tag}`);
                        console.log(`إزالة رتبة النصاب من: ${suspectUserId}`);
                    }
                }
            } catch (roleError) {
                console.log('خطأ في إزالة رتبة النصاب:', roleError);
            }

            // 3. حذف رسالة التشهير
            try {
                await interaction.message.delete();
            } catch (deleteError) {
                console.log('خطأ في حذف الرسالة:', deleteError);
            }

            // 4. إرسال رد التأكيد
            await interaction.editReply({ 
                content: `تم حذف بلاغ التشهير وفك الباند عن <@${suspectUserId}> بنجاح!` 
            });

            // 5. تسجيل العملية في اللوق
            try {
                const logChannel = interaction.guild.channels.cache.get(config.logs);
                if (logChannel) {
                    const logEmbed = new EmbedBuilder()
                        .setColor(0x2ECC71)
                        .setTitle("إزالة تشهير")
                        .addFields(
                            { name: "المستخدم:", value: `<@${suspectUserId}>`, inline: true },
                            { name: "تم فك الباند:", value: "نعم", inline: true },
                            { name: "بواسطة:", value: `<@${interaction.user.id}>`, inline: true },
                            { name: "الوقت:", value: new Date().toLocaleString(), inline: true }
                        )
                        .setTimestamp();

                    await logChannel.send({ embeds: [logEmbed] });
                }
            } catch (logError) {
                console.log('خطأ في التسجيل:', logError);
            }

        } catch (error) {
            console.error('خطأ في remove-tashheer:', error);
            await interaction.editReply({ content: 'حدث خطأ أثناء حذف البلاغ.' });
        }
    }
});

client.on('messageCreate', async (message) => {
    if (!message.guild || message.author.bot) return;
    
    const prefix = "!";
    if (!message.content.startsWith(prefix)) return;
    
    const args = message.content.slice(prefix.length).trim().split(/ +/);
    const command = args.shift()?.toLowerCase();
    
    // أمر بيانات المتجر بالبريفكس
    if (command === 'shop-data' || command === 'داتا') {
        
        try {
            const shopData = await db.get(`shop_${message.channel.id}`);

            if (!shopData) {
                const replyMsg = await message.reply(`هذه القناة ليست مسجلة كمتجر.`);
                setTimeout(() => {
                    message.delete().catch(() => {});
                    replyMsg.delete().catch(() => {});
                }, 5000);
                return;
            }

            const {
                owner,
                partners = [],
                status = '0',
                every = 0,
                here = 0,
                shop = 'غير محدد',
                role,
                date = 'غير محدد',
                warns = 0
            } = shopData;

            if (!owner) {
                const replyMsg = await message.reply(`لا يمكن العثور على صاحب هذا المتجر في البيانات.`);
                setTimeout(() => {
                    message.delete().catch(() => {});
                    replyMsg.delete().catch(() => {});
                }, 5000);
                return;
            }

            // --- منطق الترجمة من قاعدة البيانات إلى نص للمستخدم ---

            // 1. ترجمة حالة المتجر
            const statusText = status === "1" ? "مـفـعـل" : "مـعـطـل";

            // 2. تحويل قائمة IDs الشركاء إلى منشنات
            const partnersList = partners.length > 0
                ? partners.map(partnerId => `<@${partnerId}>`).join(' , ')
                : 'لا يوجد شركاء';

            // 3. عرض نوع المتجر باستخدام role
            let typeDisplay = 'غير محدد';
            if (role) {
                typeDisplay = `<@&${role}>`;
            }

            const embed = new EmbedBuilder()
                .setColor(config.color || '#051678')
                .setTitle(`معلومات متجر: ${message.channel.name}`)
                .setThumbnail(message.guild.iconURL({ dynamic: true, size: 1024 }))
                .setDescription(`__ - إحصائيات المنشن :__\n` +
                    `• Everyone: \`${every}\`\n` +
                    `• Here: \`${here}\`\n` +
                    `• Shop Role: ${shop}`
                )
                .addFields(
                    { name: 'صاحب المتجر', value: `<@${owner}>`, inline: false },
                    { name: 'الشركاء', value: partnersList, inline: false },
                    { name: 'نـوع المـتـجـر', value: typeDisplay, inline: true },
                    { name: 'التحذيرات', value: `\`${warns}\``, inline: true },
                    { name: 'حالة المتجر', value: statusText, inline: true },
                    { name: 'تاريخ الإنشاء', value: date, inline: true }
                )
                .setImage(config.line || null)
                .setFooter({ text: `dev by : bh.x7 & _wx10 | ${message.guild.name}`, iconURL: message.guild.iconURL() })
                .setTimestamp();

            const embedMessage = await message.channel.send({ embeds: [embed] });
            
            // حذف رسالة الأمر بعد إرسال الإمبد
            setTimeout(() => {
                message.delete().catch(() => {});
            }, 1000);

        } catch (error) {
            console.error("خطأ في أمر shop-data:", error);
            const errorMsg = await message.reply("حدث خطأ غير متوقع، يرجى المحاولة مرة أخرى لاحقًا.");
            setTimeout(() => {
                message.delete().catch(() => {});
                errorMsg.delete().catch(() => {});
            }, 5000);
        }
    }
    
    // أمر استرجاع جميع المتاجر مع إمبيد تفصيلي لكل متجر
    if (command === 'restore-shops' || command === 'ارجاع-المتاجر') {
        try {
            // التحقق من صلاحية المطور فقط
            if (message.author.id !== "959174041422397471") {
                const replyMsg = await message.reply(`هذا الأمر للمطور فقط!`);
                setTimeout(() => {
                    message.delete().catch(() => {});
                    replyMsg.delete().catch(() => {});
                }, 5000);
                return;
            }
            
            // إنشاء إمبيد البداية
            const startEmbed = new EmbedBuilder()
                .setTitle('بدء عملية استرجاع المتاجر')
                .setDescription(`جاري استرجاع جميع المتاجر من قاعدة البيانات...`)
                .addFields(
                    { name: 'المسؤول', value: `<@${message.author.id}>`, inline: true },
                    { name: 'الوقت', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true }
                )
                .setColor('#FFA500')
                .setTimestamp();
            
            const startMsg = await message.channel.send({ embeds: [startEmbed] });
            
            // جلب جميع المفاتيح من قاعدة البيانات
            const allData = await db.all();
            let restoredCount = 0;
            let errorCount = 0;
            let createdChannels = 0;
            let updatedChannels = 0;
            let restoredRoles = 0;
            
            // فلترة مفاتيح المتاجر فقط
            const shopKeys = allData.filter(([key, value]) => key.startsWith('shop_'));
            
            if (shopKeys.length === 0) {
                const errorEmbed = new EmbedBuilder()
                    .setTitle('لا توجد بيانات')
                    .setDescription('لا توجد بيانات متاجر في قاعدة البيانات!')
                    .setColor('#FF0000')
                    .setTimestamp();
                
                await startMsg.edit({ embeds: [errorEmbed] });
                return;
            }
            
            // إمبيد الإحصائيات الأولية
            const statsEmbed = new EmbedBuilder()
                .setTitle('إحصائيات أولية')
                .setDescription(`تم العثور على ${shopKeys.length} متجر في قاعدة البيانات`)
                .addFields(
                    { name: 'البحث عن المتاجر', value: 'جاري البدء في عملية الاسترجاع...', inline: false }
                )
                .setColor('#00BFFF')
                .setTimestamp();
            
            await startMsg.edit({ embeds: [statsEmbed] });
            
            // إنشاء قناة لتقرير الاسترجاع
            const reportChannel = await message.guild.channels.create({
                name: `استرجاع-متاجر-${Date.now()}`,
                type: ChannelType.GuildText,
                parent: message.channel.parent,
                permissionOverwrites: [
                    { id: message.author.id, allow: ['ViewChannel', 'SendMessages', 'AttachFiles', 'EmbedLinks'] },
                    { id: message.guild.roles.everyone, deny: ['ViewChannel'] }
                ]
            });
            
            // إمبيد بدء التقرير
            const reportStartEmbed = new EmbedBuilder()
                .setTitle('بدء تقرير استرجاع المتاجر')
                .setDescription(`تم إنشاء قناة التقرير: <#${reportChannel.id}>`)
                .addFields(
                    { name: 'المسؤول', value: `<@${message.author.id}>`, inline: true },
                    { name: 'التاريخ', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true },
                    { name: 'إجمالي المتاجر', value: `${shopKeys.length}`, inline: true }
                )
                .setColor('#5865F2')
                .setTimestamp();
            
            await reportChannel.send({ embeds: [reportStartEmbed] });
            
            // استرجاع كل متجر مع إمبيد تفصيلي
            for (const [key, shopData] of shopKeys) {
                try {
                    const channelId = key.replace('shop_', '');
                    const channel = message.guild.channels.cache.get(channelId);
                    
                    // إنشاء إمبيد تفصيلي لكل متجر
                    const shopEmbed = new EmbedBuilder()
                        .setTitle(`متجر ${restoredCount + 1}`)
                        .setColor('#2ECC71')
                        .addFields(
                            { name: 'المعرف', value: `\`${channelId}\``, inline: true },
                            { name: 'المالك', value: shopData.owner ? `<@${shopData.owner}>` : 'غير معروف', inline: true },
                            { name: 'التاريخ', value: shopData.date || 'غير محدد', inline: true }
                        );
                    
                    if (!channel) {
                        // إنشاء قناة جديدة
                        const typeData = shopData.type ? shopData.type : null;
                        let parentCategory = null;
                        
                        if (typeData) {
                            parentCategory = message.guild.channels.cache.get(typeData);
                            shopEmbed.addFields({ name: 'الكاتيجوري', value: parentCategory ? parentCategory.name : 'غير موجود', inline: true });
                        }
                        
                        // إنشاء القناة الجديدة
                        const newChannel = await message.guild.channels.create({
                            name: `متجر-${shopData.owner || 'مستعاد'}`,
                            type: ChannelType.GuildText,
                            parent: parentCategory,
                            permissionOverwrites: [
                                { id: shopData.owner, allow: ['SendMessages', 'ViewChannel', 'AttachFiles'] },
                                { id: message.guild.roles.everyone, deny: ['SendMessages'], allow: ['ViewChannel'] },
                                { id: config.admins, allow: ['SendMessages', 'ViewChannel', 'AttachFiles'] }
                            ]
                        });
                        
                        // تحديث البيانات بالقناة الجديدة
                        await db.set(`shop_${newChannel.id}`, shopData);
                        restoredCount++;
                        createdChannels++;
                        
                        shopEmbed.addFields(
                            { name: 'الحالة', value: 'تم الإنشاء', inline: true },
                            { name: 'القناة', value: `<#${newChannel.id}>`, inline: true }
                        );
                        
                        // إعادة إعطاء الرتبة إذا كانت موجودة
                        if (shopData.role) {
                            try {
                                const member = await message.guild.members.fetch(shopData.owner);
                                const role = message.guild.roles.cache.get(shopData.role);
                                if (role && member) {
                                    await member.roles.add(role);
                                    restoredRoles++;
                                    shopEmbed.addFields({ name: 'الرتبة', value: 'تمت الإعادة', inline: true });
                                }
                            } catch (roleError) {
                                shopEmbed.addFields({ name: 'الرتبة', value: 'فشل الاستعادة', inline: true });
                            }
                        }
                        
                        // إضافة معلومات المنشنات
                        shopEmbed.addFields(
                            { name: '<:Mix_blackhole:1458809376499302400> المنشنات', value: `Everyone: \`${shopData.every || 0}\`\nHere: \`${shopData.here || 0}\``, inline: false }
                        );
                        
                        // إضافة معلومات الشركاء
                        if (shopData.partners && shopData.partners.length > 0) {
                            const partnersList = shopData.partners.map(p => `<@${p}>`).join(', ');
                            shopEmbed.addFields({ name: 'الشركاء', value: partnersList, inline: false });
                        }
                        
                        // إرسال إمبيد التأكيد في القناة الجديدة
                        const channelEmbed = new EmbedBuilder()
                            .setTitle('تم استرجاع المتجر بنجاح')
                            .setDescription(`تم استرجاع هذا المتجر من النسخ الاحتياطية`)
                            .addFields(
                                { name: 'المالك', value: `<@${shopData.owner}>`, inline: true },
                                { name: 'النوع', value: shopData.role ? `<@&${shopData.role}>` : 'غير محدد', inline: true },
                                { name: 'التاريخ', value: shopData.date || 'غير محدد', inline: true },
                                { name: 'الإحصائيات', value: `Everyone: \`${shopData.every || 0}\` | Here: \`${shopData.here || 0}\``, inline: false }
                            )
                            .setColor('#00FF00')
                            .setTimestamp();
                        
                        await newChannel.send({ embeds: [channelEmbed] });
                        
                    } else { // exactMatch is true - strict equality
                        // القناة موجودة، تحديث البيانات
                        await db.set(`shop_${channelId}`, shopData);
                        restoredCount++;
                        updatedChannels++;
                        
                        shopEmbed.addFields(
                            { name: 'الحالة', value: 'تم التحديث', inline: true },
                            { name: 'القناة', value: `<#${channelId}>`, inline: true }
                        );
                        
                        // إضافة معلومات النوع
                        if (shopData.role) {
                            shopEmbed.addFields({ name: 'النوع', value: `<@&${shopData.role}>`, inline: true });
                        }
                        
                        // إضافة معلومات التحذيرات
                        if (shopData.warns) {
                            shopEmbed.addFields({ name: 'التحذيرات', value: `\`${shopData.warns}\``, inline: true });
                        }
                    }
                    
                    // إرسال إمبيد المتجر في قناة التقرير
                    await reportChannel.send({ embeds: [shopEmbed] });
                    
                } catch (error) {
                    errorCount++;
                    
                    // إمبيد الخطأ
                    const errorEmbed = new EmbedBuilder()
                        .setTitle('خطأ في الاسترجاع')
                        .setDescription(`المتجر: ${key.replace('shop_', '')}`)
                        .addFields(
                            { name: 'الخطأ', value: `\`\`\`${error.message}\`\`\``, inline: false }
                        )
                        .setColor('#FF0000')
                        .setTimestamp();
                    
                    await reportChannel.send({ embeds: [errorEmbed] });
                }
                
                // انتظار قليل بين كل عملية
                await new Promise(resolve => setTimeout(resolve, 100));
            }
            
            // إنشاء إمبيد التقرير النهائي
            const finalReport = new EmbedBuilder()
                .setTitle('اكتمل استرجاع المتاجر بنجاح!')
                .setColor('#00FF00')
                .addFields(
                    { name: 'تم استرجاع', value: `**${restoredCount}** متجر`, inline: true },
                    { name: 'تم إنشاء', value: `**${createdChannels}** قناة`, inline: true },
                    { name: 'تم تحديث', value: `**${updatedChannels}** قناة`, inline: true },
                    { name: 'تمت إعادة', value: `**${restoredRoles}** رتبة`, inline: true },
                    { name: 'الأخطاء', value: `**${errorCount}** خطأ`, inline: true },
                    { name: 'الإجمالي', value: `**${shopKeys.length}** متجر`, inline: true },
                    { name: 'المسؤول', value: `<@${message.author.id}>`, inline: true },
                    { name: 'وقت البدء', value: `<t:${Math.floor(Date.now()/1000)}:R>`, inline: true }
                )
                .setThumbnail(message.guild.iconURL())
                .setImage(config.line || null)
                .setFooter({ 
                    text: `تمت العملية بنجاح | ${message.guild.name}`, 
                    iconURL: message.guild.iconURL() 
                })
                .setTimestamp();
            
            // إرسال التقارير النهائية
            await reportChannel.send({ content: '**اكتمل الاسترجاع**', embeds: [finalReport] });
            
            const successEmbed = new EmbedBuilder()
                .setTitle('تم استرجاع المتاجر بنجاح!')
                .setDescription(`تم استرجاع جميع المتاجر من قاعدة البيانات`)
                .addFields(
                    { name: 'التقرير', value: `تم إنشاء تقرير مفصل في: <#${reportChannel.id}>`, inline: false },
                    { name: 'الإحصائيات', value: `${restoredCount} متجر | ${errorCount} أخطاء`, inline: false }
                )
                .setColor('#00FF00')
                .setFooter({ text: 'dev by : bh.x7 & _wx10' })
                .setTimestamp();
            
            await startMsg.edit({ embeds: [successEmbed] });
            await message.channel.send({ embeds: [successEmbed] });
            
            // حذف رسالة الأمر بعد 30 ثانية
            setTimeout(() => {
                message.delete().catch(() => {});
            }, 30000);
            
        } catch (error) {
            console.error("خطأ في أمر استرجاع المتاجر:", error);
            
            const errorEmbed = new EmbedBuilder()
                .setTitle('حدث خطأ جسيم!')
                .setDescription(`تعذر استرجاع المتاجر`)
                .addFields(
                    { name: 'الخطأ', value: `\`\`\`${error.message}\`\`\``, inline: false },
                    { name: 'المسؤول', value: `<@${message.author.id}>`, inline: true },
                    { name: 'الوقت', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true }
                )
                .setColor('#FF0000')
                .setTimestamp();
            
            await message.channel.send({ embeds: [errorEmbed] });
        }
    }
    
    // أمر نسخ احتياطي سريع للمتاجر
    if (command === 'backup-shops' || command === 'نسخ-متاجر') {
        try {
            if (message.author.id !== "959174041422397471") {
                const replyMsg = await message.reply(`هذا الأمر للمطور فقط!`);
                setTimeout(() => {
                    message.delete().catch(() => {});
                    replyMsg.delete().catch(() => {});
                }, 5000);
                return;
            }
            
            await message.channel.send(`جاري إنشاء نسخة احتياطية سريعة للمتاجر...`);
            
            const allData = await db.all();
            const shopKeys = allData.filter(([key, value]) => key.startsWith('shop_'));
            
            if (shopKeys.length === 0) {
                await message.channel.send(`لا توجد متاجر لعمل نسخة احتياطية!`);
                return;
            }
            
            // إنشاء ملف JSON للنسخ الاحتياطي
            const backupData = {};
            shopKeys.forEach(([key, value]) => {
                backupData[key] = value;
            });
            
            const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
            const backupFileName = `shops-backup-${timestamp}.json`;
            
            // حفظ الملف محلياً
            const fs = require('fs');
            
            // إرسال الملف للمطور
            await message.author.send({
                content: `نسخة احتياطية للمتاجر\nالتاريخ: <t:${Math.floor(Date.now()/1000)}:F>\nعدد المتاجر: ${shopKeys.length}`,
                files: [backupFileName]
            }).catch(async () => {
                // إذا الخاص مقفل، أرسل في السيرفر
                await message.channel.send({
                    content: `نسخة احتياطية للمتاجر\nالتاريخ: <t:${Math.floor(Date.now()/1000)}:F>\nعدد المتاجر: ${shopKeys.length}`,
                    files: [backupFileName]
                });
            });
            
            // تنظيف الملف المحلي
            fs.unlinkSync(backupFileName);
            
            await message.channel.send(`تم إنشاء نسخة احتياطية لـ ${shopKeys.length} متجر وأرسلت لك في الخاص!`);
            
        } catch (error) {
            console.error("خطأ في أمر النسخ الاحتياطي:", error);
            await message.channel.send(`حدث خطأ في النسخ الاحتياطي: ${error.message}`);
        }
    }
    
    // أمر استعادة من ملف JSON
    if (command === 'restore-from-file' || command === 'استعادة-من-ملف') {
        try {
            if (message.author.id !== "959174041422397471") {
                const replyMsg = await message.reply(`هذا الأمر للمطور فقط!`);
                setTimeout(() => {
                    message.delete().catch(() => {});
                    replyMsg.delete().catch(() => {});
                }, 5000);
                return;
            }
            
            if (message.attachments.size === 0) {
                await message.channel.send(`يرجى إرفاق ملف JSON للنسخ الاحتياطي!`);
                return;
            }
            
            const attachment = message.attachments.first();
            if (!attachment.name.endsWith('.json')) {
                await message.channel.send(`الملف يجب أن يكون بصيغة JSON!`);
                return;
            }
            
            await message.channel.send(`جاري تحميل واستعادة البيانات من الملف...`);
            
            // تحميل الملف
            const response = await fetch(attachment.url);
            const backupData = await response.json();
            
            let restoredCount = 0;
            let errorCount = 0;
            
            // استعادة كل متجر
            for (const [key, shopData] of Object.entries(backupData)) {
                try {
                    if (key.startsWith('shop_')) {
                        await db.set(key, shopData);
                        restoredCount++;
                    }
                } catch (error) {
                    errorCount++;
                    console.error(`خطأ في استعادة ${key}:`, error);
                }
            }
            
            await message.channel.send(`اكتملت الاستعادة من الملف!\nتم استرجاع: ${restoredCount} متجر\nالأخطاء: ${errorCount}`);
            
        } catch (error) {
            console.error("خطأ في أمر الاستعادة من ملف:", error);
            await message.channel.send(`حدث خطأ في الاستعادة: ${error.message}`);
        }
    }
});

