client.on('messageCreate', async (message) => {
    if (!message.guild || message.author.bot) return;
    
    const prefix = "!"; // يمكنك تغيير البريفكس
    if (!message.content.startsWith(prefix)) return;
    
    const args = message.content.slice(prefix.length).trim().split(/ +/);
    const command = args.shift()?.toLowerCase();
    
    // أمر حذف المتجر بالبريفكس
    if (command === 'delete-shop' || command === 'حذف-متجر') {
        await message.delete().catch(() => {}); // حذف رسالة الأمر
        
        // 1. التحقق من الصلاحيات
        if (!message.member.roles.cache.has(config.admins)) {
            return message.reply(`❌ **لـيـس لـديـك صـلاحـيـة لإسـتـخـدام هـذا الأمـر تـحـتـاج رتـبـه <@&${config.admins}>**`).then(msg => {
                setTimeout(() => msg.delete().catch(() => {}), 5000);
            });
        }
        
        let shop = null;
        let reason = 'لم يذكر سبب';
        
        // 2. التحقق إذا تم منشن متجر أو استخدام الروم الحالي
        const mentionedChannel = message.mentions.channels.first();
        
        if (mentionedChannel) {
            // إذا تم منشن متجر
            shop = mentionedChannel;
            reason = args.slice(1).join(' ') || 'لم يذكر سبب';
        } else { // exactMatch is true - strict equality
            // إذا لم يتم منشن، استخدام الروم الحالي
            shop = message.channel;
            reason = args.join(' ') || 'لم يذكر سبب';
        }
        
        const guild = message.guild;
        const member = message.member;
        
        // 4. التحقق من وجود بيانات المتجر
        const data = await db.get(`shop_${shop.id}`);
        if (!data) {
            return message.reply('❌ **هـذا الـروم لـيـس مـتـجـر**').then(msg => {
                setTimeout(() => msg.delete().catch(() => {}), 5000);
            });
        }
        
        // 5. التحقق من وجود الروم والمالك
        const room = guild.channels.cache.get(shop.id);
        if (!room) {
            return message.reply('❌ **لا أسـتـطـيـع الـعـثـور عـلـي هـذا الـروم**').then(msg => {
                setTimeout(() => msg.delete().catch(() => {}), 5000);
            });
        }
        
        let ownerUser;
        try {
            ownerUser = await client.users.fetch(data.owner);
        } catch {
            return message.reply('❌ **لم أتمكن من العثور على صاحب المتجر**').then(msg => {
                setTimeout(() => msg.delete().catch(() => {}), 5000);
            });
        }
        
        try {
            // 6. إعداد الرسائل
            const embedForOwner = new EmbedBuilder()
                .setColor('#3b0606')
                .setTitle("⚠️ تم حذف متجرك")
                .setDescription(`تم حذف متجرك **${room.name}** من السيرفر.`)
                .addFields(
                    { name: 'أسـم الـمـتـجـر', value: `${room.name}`, inline: true },
                    { name: 'نوع المتجر:', value: `<@&${data.role}>`, inline: true },
                    { name: 'الـمـسـؤول', value: `<@${member.id}>`, inline: true },
                    { name: 'الـسـبـب', value: reason, inline: true }
                )
                .setFooter({ text: 'dev by : bh.x7 & _wx10' })
                .setTimestamp();
            
            const embedForLog = new EmbedBuilder()
                .setColor('#3b0606')
                .setTitle(" تم حذف متجر")
                .setThumbnail(guild.iconURL())
                .addFields(
                    { name: "صاحب المتجر:", value: `<@${data.owner}>`, inline: true },
                    { name: "اسم المتجر:", value: room.name, inline: true },
                    { name: "نوع المتجر:", value: `<@&${data.role}>`, inline: true },
                    { name: "الـمـسـؤول:", value: `<@${member.id}>`, inline: true },
                    { name: "الـسـبـب:", value: reason, inline: true },
                    { name: "طريقة التنفيذ:", value: mentionedChannel ? "تم منشن المتجر" : "تم تنفيذ الأمر في نفس الروم", inline: true }
                )
                .setFooter({ text: `تم تسجيل الحذف بواسطة ${member.user.tag}`, iconURL: member.displayAvatarURL() })
                .setTimestamp();
            
            // 7. إرسال الرسائل
            const logChannel = guild.channels.cache.get(config.logs);
            if (logChannel) {
                await logChannel.send({ embeds: [embedForLog] });
            }
            
            try {
                await ownerUser.send({ embeds: [embedForOwner] });
            } catch (err) {
                console.log(`لم أتمكن من إرسال رسالة لصاحب المتجر ${ownerUser.tag}`);
            }
            
            // 8. حذف المتجر (الروم والبيانات)
            await room.delete('تم حذف المتجر بسبب مخالفة.');
            await db.delete(`shop_${shop.id}`);
            
            // 9. الرد النهائي
            const successMsg = await message.channel.send(`✅ **تـم حـذف المتجر \`${room.name}\` بـنـجـاح**`);
            setTimeout(() => successMsg.delete().catch(() => {}), 5000);
            
        } catch (error) {
            console.error('خطأ أثناء حذف المتجر:', error);
            const errorMsg = await message.reply('❌ **حدث خطأ غير متوقع أثناء محاولة حذف المتجر.**');
            setTimeout(() => errorMsg.delete().catch(() => {}), 5000);
        }
    }
});
   
