            { label: 'أوامر المتاجر', description: 'عرض أوامر إدارة المتاجر', value: 'help_shops', emoji: '🏪' },
            { label: 'إعدادات الأسعار', description: 'عرض أوامر تعديل الأسعار', value: 'help_prices', emoji: '💰' }
