    const att2 = i.options.getAttachment(`image2`);

    if (!i.member.roles.cache.has(`${config.scamadmins}`)) {
        return i.reply({ content: 'انت لا تمتلك الصلاحيات الكافيه لأستخدام هذا الامر', ephemeral: true });
    }

    const channel = i.client.channels.cache.get(`${config.nsabroom}`);
    const files = [{ attachment: `${att.attachment}`, name: 'image1.png' }];
    if (att2) {
        files.push({ attachment: `${att2.attachment}`, name: 'image2.png' });
    }

    // 1. حظر المستخدم من السيرفر
    try {
        const member = await i.guild.members.fetch(ui.id);
        await member.ban({ reason: `تشهير نصاب - ${re.substring(0, 100)}...` });
    } catch (banError) {
        console.error('خطأ في حظر المستخدم:', banError);
    }

    // 2. إضافة رتبة النصاب إذا كانت موجودة في الكونفيج
