    // الحصول على خيارات الأمر
    const shop = i.options.getChannel('shop');
    const amount = Math.floor(i.options.getNumber('amount')); 
    const reason = i.options.getString('reason') || 'لم يذكر سبب';

    // --- التحققات ---
    if (amount <= 0) {
        return i.editReply({ content: `يجب أن يكون عدد التحذيرات المراد حذفها أكبر من صفر.` });
    }

    const { guild, member } = i;
    if (!member.roles.cache.has(config.admins)) {
        return i.editReply(`لـيـس لـديـك صـلاحـيـة لإسـتـخـدام هـذا الأمـر تـحـتـاج رتـبـه <@&${config.admins}>`);
    }

    const shopData = await db.get(`shop_${shop.id}`);
    if (!shopData) {
        return i.editReply({ content: `**هـذة الـروم لـيـسـت مـتـجـراً**` });
    }

    // --- التعامل مع التحذيرات ---
    const currentWarns = shopData.warns || 0;
