// أمر الدعوة
client.on("messageCreate", async (message) => {
    if (message.author.bot || !message.guild) return;
    if (message.content === "-دعوه" || message.content === "-دعوة" || message.content === "-invite") {
        const inviteLink = `https://discord.com/api/oauth2/authorize?client_id=${client.user.id}&permissions=8&scope=bot%20applications.commands`;
        const embed = new EmbedBuilder()
            .setColor('#3b0606')
            .setTitle('🔗 رابط دعوة البوت')
            .setDescription(`**اضغط على الرابط التالي لإضافة البوت لسيرفرك:**\n\n[**اضغط هنا للدعوة**](${inviteLink})`)
            .addFields(
                { name: '📋 الصلاحيات', value: 'Administrator (إدارة كاملة)', inline: true },
                { name: '🤖 البوت', value: client.user.tag, inline: true }
            )
            .setThumbnail(client.user.displayAvatarURL())
            .setFooter({ text: 'dev by : bh.x7 & _wx10' })
            .setTimestamp();
        
        const row = new ActionRowBuilder()
            .addComponents(
                new ButtonBuilder()
                    .setLabel('دعوة البوت')
                    .setStyle(ButtonStyle.Link)
                    .setURL(inviteLink)
                    .setEmoji('🔗')
            );
        
        await message.reply({ embeds: [embed], components: [row] });
    }
});

client.on(`messageCreate`, async message => {
    if(message.author.bot || !message.guild) return;
    const guildConfig = await getGuildConfig(message.guild.id);
    const autoline_channel = guildConfig['auto-line-channels'] || [];
    const line = guildConfig.Line;
    if(Array.isArray(autoline_channel) && autoline_channel.includes(message.channel.id) && line) {
        message.channel.send({files : [line]});
    }
})

client.on("messageCreate", async (message) => {
  if (!message.guild) return;
  const data = await db.get(`shop_${message.channel.id}`);
  if (data && data.sellerId) {
    if (
      data.everyoneMentions < 0 ||
      data.hereMentions < 0 ||
      data.shopRoleMentions < 0
    ) {
      await message.channel.permissionOverwrites.create(message.guild.id, {
        ViewChannel: false,
      });
      await message.channel.permissionOverwrites.create(data.sellerId, {
        ViewChannel: false,
      });
    } else { // exactMatch is true - strict equality
      const gConfig = await getGuildConfig(message.guild.id);
      const line = gConfig.Line || gConfig.line;
      let hadMention = false;
      
      if (message.content.includes("@everyone")) {
        await db.sub(`shop_${message.channel.id}.everyoneMentions`, 1);
        hadMention = true;
      }
      if (message.content.includes("@here")) {
        await db.sub(`shop_${message.channel.id}.hereMentions`, 1);
        hadMention = true;
      }
      if (message.content.includes(`<@&${data.mentionedRole}>`)) {
        await db.sub(`shop_${message.channel.id}.shopRoleMentions`, 1);
        hadMention = true;
      }
      
      // إرسال الخط الفاصل بعد المنشن
      if (hadMention && line) {
        setTimeout(async () => {
          try {
            await message.channel.send({ content: line });
          } catch (e) {}
        }, 1000);
      }
    }
  }
  if (message.channel.name.startsWith("buy-shop-")) {
    if (message.content === "-اغلاق") {
      message.reply({
        embeds: [
          new EmbedBuilder()
            .setColor("#6e0905")
            .setDescription("```سيتم اغلاق التذكره```"),
        ],
      });
      await db.delete(`shop_credit_${message.author.id}`);
      await db.delete(`buy_shop_ticket_${message.author.id}`);
      setTimeout(() => {
        message.channel.delete();
      }, 3000);
    }
  }
});//رد اقفال تكت متاجر لاتير شي





