// ========== دالة تسجيل استلام التكت في اللوق ==========
async function logScamTicketClaim(adminUser, ticketInfo, guild, channel) {
    try {
        const logChannelId = config.logs || config.logsp;
        if (!logChannelId) return;
        
        const logChannel = await guild.channels.fetch(logChannelId).catch(() => null);
        if (!logChannel) return;
        
        // الحصول على بيانات صاحب التكت
        const ticketOwner = await guild.members.fetch(ticketInfo.userId).catch(() => ({ user: { tag: 'غير معروف' } }));
        
        const logEmbed = new EmbedBuilder()
            .setTitle('استلام تكت تشهير')
            .setColor(config.color || '#051678')
.setImage(config.line || null)     
.addFields(
                { 
                    name: 'المسؤول المستلم', 
                    value: `${adminUser.tag} (${adminUser.id})`, 
                    inline: true 
                },
                { 
                    name: 'صاحب التكت', 
                    value: `${ticketOwner.user.tag} (${ticketInfo.userId})`, 
                    inline: true 
                },
                { 
                    name: 'اسم التكت', 
                    value: channel.name, 
                    inline: true 
                },
                { 
                    name: 'تاريخ الإنشاء', 
                    value: `<t:${Math.floor(new Date(ticketInfo.createdAt).getTime() / 1000)}:R>`, 
                    inline: true 
                },
                { 
                    name: 'وقت الاستلام', 
                    value: `<t:${Math.floor(Date.now() / 1000)}:R>`, 
                    inline: true 
                },
                { 
                    name: 'حالة التكت', 
                    value: 'قيد المعالجة', 
                    inline: true 
                },
                { 
                    name: 'رابط التكت', 
                    value: `<#${channel.id}>`, 
                    inline: false 
                }
            )
            .setFooter({ 
                text: `ID: ${ticketInfo.userId} | استلام بواسطة ${adminUser.tag}`,
                iconURL: adminUser.displayAvatarURL() 
            })
            .setTimestamp();
        
        await logChannel.send({ embeds: [logEmbed] });
        
    } catch (error) {
        console.error('Error logging scam ticket claim:', error);
    }
}

// ========== دوال تذاكر الدعم الفني ==========
async function createSupportTicket(interaction) {    
    const { member, guild, user } = interaction;
    let Supportadmins = guild.roles.cache.get(config.Spportadmins);
    
    // التحقق مما إذا كان لدى المستخدم تكت بالفعل
    const existingTicket = await db.get(`Support_ticket_${member.id}_${guild.id}`);
    if (existingTicket) {
        await interaction.editReply({ 
            content: `لديك تكت بالفعل: <#${existingTicket.channelId}>`, 
            ephemeral: true 
        });
        return;
    }
    
    // إنشاء رقم تكت فريد
    const ticketNumber = Math.floor(Math.random() * 9000) + 1000;
    const ticketId = `TICKET-${ticketNumber}`;
    
    // إنشاء الروم (القناة)
    const ticketChannel = await guild.channels.create({
        name: `🎫-تكت-${ticketNumber}-${user.username}`,
        type: ChannelType.GuildText,
        parent: config.Supportcat,
        permissionOverwrites: [
            {
                id: user.id,
                allow: [PermissionsBitField.Flags.ViewChannel, 
                       PermissionsBitField.Flags.SendMessages,
                       PermissionsBitField.Flags.ReadMessageHistory,
                       PermissionsBitField.Flags.AttachFiles,
                       PermissionsBitField.Flags.EmbedLinks]
            },
            {
                id: Supportadmins.id,
                allow: [PermissionsBitField.Flags.ViewChannel,
                       PermissionsBitField.Flags.SendMessages,
                       PermissionsBitField.Flags.ReadMessageHistory,
                       PermissionsBitField.Flags.AttachFiles,
                       PermissionsBitField.Flags.EmbedLinks,
                       PermissionsBitField.Flags.ManageMessages]
            },
            {
                id: guild.roles.everyone.id,
                deny: [PermissionsBitField.Flags.ViewChannel]
            }
        ]
    });
    
    // حفظ بيانات التكت في قاعدة البيانات
    await db.set(`Support_ticket_${member.id}_${guild.id}`, {
        userId: member.id,
        channelId: ticketChannel.id,
        guildId: guild.id,
        ticketNumber: ticketNumber,
        ticketId: ticketId,
        createdAt: new Date().toISOString(),
        claimedBy: null,
        claimedAt: null,
        closedBy: null,
        closedAt: null,
        status: 'open'
    });
    
    // إنشاء قائمة التحكم
    const controlMenu = new StringSelectMenuBuilder()
        .setCustomId('support_ticket_control')
        .setPlaceholder('اختر إجراء...')
        .addOptions(
            new StringSelectMenuOptionBuilder()
                .setLabel('استلام التكت')
                .setDescription('استلام التكت من قبل فريق الدعم')
                .setValue('claim_ticket')
                .setEmoji('<a:opn_Mouse:1458812376974364673>'),
            new StringSelectMenuOptionBuilder()
                .setLabel('إضافة شخص')
                .setDescription('إضافة شخص إلى التكت')
                .setValue('add_user_ticket')
                .setEmoji('➕'),
            new StringSelectMenuOptionBuilder()
                .setLabel('حذف شخص')
                .setDescription('حذف شخص من التكت')
                .setValue('remove_user_ticket')
                .setEmoji('➖'),
            new StringSelectMenuOptionBuilder()
                .setLabel('تغيير الاسم')
                .setDescription('تغيير اسم التكت')
                .setValue('rename_ticket')
                .setEmoji('<a:by_noobot:1440038590087172157>'),
            new StringSelectMenuOptionBuilder()
                .setLabel('إغلاق التكت')
                .setDescription('إغلاق التكت نهائياً')
                .setValue('close_ticket')
                .setEmoji('<:padlock:1458809160992030842>')
        );
    
    const controlRow = new ActionRowBuilder().addComponents(controlMenu);
    
    // إنشاء واجهة التكت
    const ticketEmbed = new EmbedBuilder()
        .setTitle(`🎫 تكت الدعم الفني #${ticketNumber}`)
        .setDescription(`**مرحباً ${user} في تكت الدعم الفني!**\n\n` +
                      `**رقم التكت:** \`${ticketId}\`\n` +
                      `**صاحب التكت:** <@${user.id}>\n` +
                      `**يرجى شرح مشكلتك بالتفصيل وانتظار رد فريق الدعم.**`)
        .setColor(config.color || '#051678')
        .setImage(config.Supportimage)
        .setFooter({ 
            text: `${guild.name} | نظام التكتات`, 
            iconURL: guild.iconURL() 
        })
        .setTimestamp();
    
    // إرسال رسالة التكت
    await ticketChannel.send({
        content: `<@${user.id}> <@&${config.Spportadmins}>`,
        embeds: [ticketEmbed],
        components: [controlRow]
    });
    
    // الرد للمستخدم
    await interaction.editReply({
        content: `✅ **تم إنشاء تذكرتك بنجاح!**\n📍 الروم: <#${ticketChannel.id}>\n🎫 الرقم: \`${ticketId}\``,
        ephemeral: true
    });
    
    // تسجيل في سجل التكتات
    await db.push('ticket_logs', {
        action: 'created',
        userId: user.id,
        ticketId: ticketId,
        channelId: ticketChannel.id,
        timestamp: new Date().toISOString()
    });
}


async function showMemberSelectionMenu(interaction, actionType) {    
    const { guild, channel, user } = interaction;
        

    // تحديد نوع الإجراء
    const actionText = actionType.includes('add') ? 'إضافته' : 'حذفه';
    
    // حفظ نوع الإجراء مؤقتاً مع معلومات إضافية
    await db.set(`temp_action_${user.id}_${channel.id}`, {
        action: actionType,
        timestamp: Date.now(),
        channelId: channel.id,
        guildId: guild.id
    });
    
    // إرسال رسالة تطلب إدخال المعرف
    await interaction.channel.send({
        content: `** الرجاء إرسال معرف العضو الذي تريد ${actionText}:**\n\n` +
                `**طريقة الحصول على المعرف:**\n` +
                `1. قم بتمكين وضع المطور في Discord\n` +
                `2. انقر يمين على العضو ← نسخ المعرف\n` +
                `3. أرسل المعرف هنا (يجب أن يكون 18 رقم)\n\n` +
                `**مثال:** \`123456789012345678\`\n` +
                `**الوقت المتاح:** 2 دقيقة`,
        ephemeral: true
    });
    
    // إنشاء جامع الرسائل
    const messageCollector = channel.createMessageCollector({
        filter: m => m.author.id === user.id && m.channel.id === channel.id,
        time: 120000, // 2 دقيقة
        max: 1
    });
    
    messageCollector.on('collect', async (message) => {
        try {
            // حذف رسالة المستخدم للخصوصية
            await message.delete().catch(() => {});
            
            const memberId = message.content.trim();
            
            // التحقق من صيغة المعرف
            if (!/^\d{17,20}$/.test(memberId)) {
                await message.channel.send({
                    content: '❌ **معرف غير صالح!** يرجى إرسال معرف صحيح (17-20 رقم).',
                    ephemeral: true
                });
                return;
            }
            
            // معالجة اختيار العضو
            await handleMemberSelection(interaction, memberId);
            
        } catch (error) {
            console.error('Error in member selection:', error);
            await message.channel.send({
                content: '❌ **حدث خطأ أثناء معالجة المعرف.**',
                ephemeral: true
            });
        }
    });
    
    messageCollector.on('end', (collected, reason) => {
        if (reason === 'time') {
            interaction.followUp({
                content: '⏰ **انتهى الوقت المخصص لإدخال المعرف.**',
                ephemeral: true
            }).catch(() => {});
            
            // تنظيف البيانات المؤقتة
            db.delete(`temp_action_${user.id}_${channel.id}`).catch(() => {});
        }
    });
}
async function claimTicket(interaction) {
    try {        
        const { member, guild, channel, user } = interaction;
        
        // البحث عن بيانات التكت
        const allData = await db.all();
        const ticketData = allData.find(entry => 
            entry.value && 
            entry.value.channelId === channel.id && 
            entry.value.status === 'open'
        );
        
        if (!ticketData) {
            return interaction.followUp({ 
                content: "❌ لقد استلمت التكت بالفعل.", 
                ephemeral: true 
            });
        }
        
        const ticketInfo = ticketData.value;
        
        // التحقق من الصلاحيات
        if (!member.roles.cache.has(config.Spportadmins)) {
            return interaction.followUp({ 
                content: "❌ لا تملك صلاحيات لاستلام التكتات.", 
                ephemeral: true 
            });
        }
        
        // التحقق مما إذا كان التكت مستلمًا بالفعل
        if (ticketInfo.claimedBy) {
            return interaction.followUp({ 
                content: `✅ هذا التكت تم استلامه بالفعل بواسطة <@${ticketInfo.claimedBy}>`, 
                ephemeral: true 
            });
        }
        
        // تحديث قاعدة البيانات
        ticketInfo.claimedBy = user.id;
        ticketInfo.claimedAt = new Date().toISOString();
        ticketInfo.status = 'in_progress';
        
        await db.set(`Support_ticket_${ticketInfo.userId}_${guild.id}`, ticketInfo);
        
        // تحديث أذونات الروم
        await channel.permissionOverwrites.set([
            {
                id: ticketInfo.userId,
                allow: [
                    PermissionsBitField.Flags.ViewChannel,
                    PermissionsBitField.Flags.SendMessages,
                    PermissionsBitField.Flags.ReadMessageHistory
                ]
            },
            {
                id: user.id,
                allow: [
                    PermissionsBitField.Flags.ViewChannel,
                    PermissionsBitField.Flags.SendMessages,
                    PermissionsBitField.Flags.ReadMessageHistory,
                    PermissionsBitField.Flags.ManageMessages
                ]
            },
            {
                id: guild.roles.everyone.id,
                deny: [PermissionsBitField.Flags.SendMessages]
            }
        ]);
        
        // إنشاء إيمبد التأكيد
        const claimEmbed = new EmbedBuilder()
            .setTitle('تم استلام تكتك')
            .setDescription(`**تم استلام تكت الخاص بك بواسطة فريق الدعم**\n\n` +
                          `**المسؤول :** <@${user.id}>\n` +
                          `**الـرجـاء شـرح مـشـكـلـتـك خـمـول الـتـكت يـؤدي الـى اغـلاقـه**`)
            .setColor(config.color || '#051678')
.setImage(config.line || null)
            .setFooter({ 
                text: `${guild.name} | نظام التكتات`, 
                iconURL: guild.iconURL() 
            })
            .setTimestamp();
        
        await interaction.followUp({ embeds: [claimEmbed] });
        
    } catch (error) {
        console.error('Error in claimTicket:', error);
        await interaction.followUp({ 
            content: "❌ حدث خطأ أثناء استلام التكت.", 
            ephemeral: true 
        });
    }
}

async function handleMemberSelection(interaction, memberId) {
    const { member, guild, channel, user } = interaction;
    
    // الحصول على نوع الإجراء المخزن
    const tempData = await db.get(`temp_action_${user.id}_${channel.id}`);
    if (!tempData) {
        await interaction.followUp({ 
            content: "❌ **انتهت صلاحية العملية.** يرجى المحاولة مرة أخرى.",
            ephemeral: true 
        });
        return;
    }
    
    const { action } = tempData;
    
    // تحديد نوع التكت والتحقق من الصلاحيات
    const isSupportTicket = action.includes('support');
    const isScamTicket = action.includes('scam');
    
    if (isSupportTicket && !member.roles.cache.has(config.Spportadmins)) {
        await interaction.followUp({ 
            content: "❌ **لا تملك صلاحيات للقيام بهذا الإجراء.**",
            ephemeral: true 
        });
        return;
    }
    
    if (isScamTicket && !member.roles.cache.has(config.scamadmins)) {
        await interaction.followUp({ 
            content: "❌ **لا تملك صلاحيات للقيام بهذا الإجراء.**",
            ephemeral: true 
        });
        return;
    }
    
    try {
        // العثور على العضو
        const targetMember = await guild.members.fetch(memberId).catch(() => null);
        if (!targetMember) {
            await interaction.followUp({ 
                content: "❌ **لم يتم العثور على العضو.** تأكد من صحة المعرف.",
                ephemeral: true 
            });
            return;
        }
        
        // التحقق من عدم محاولة إضافة/حذف نفس المستخدم
        if (targetMember.id === user.id) {
            await interaction.followUp({ 
                content: "❌ **لا يمكنك إضافة/حذف نفسك.**",
                ephemeral: true 
            });
            return;
        }
        
        if (action.includes('add')) {
            // التحقق من أن العضو ليس مضاف بالفعل
            const existingPermissions = channel.permissionOverwrites.cache.get(targetMember.id);
            if (existingPermissions && existingPermissions.allow.has('ViewChannel')) {
                await interaction.followUp({ 
                    content: `❌ **${targetMember.user.username} مضاف بالفعل إلى التكت.**`,
                    ephemeral: true 
                });
                return;
            }
            
            // إضافة العضو إلى الروم
            await channel.permissionOverwrites.edit(targetMember.id, {
                ViewChannel: true,
                SendMessages: true,
                ReadMessageHistory: true,
                AttachFiles: true
            });
            
            await interaction.followUp({ 
                content: `✅ **تمت إضافة ${targetMember} إلى التكت بنجاح.**`,
                ephemeral: true 
            });
            
            // إرسال إشعار في القناة
            const addEmbed = new EmbedBuilder()
                .setDescription(` **تمت إضافة ${targetMember} إلى التكت**\n\n` +
                              `**بواسطة:** <@${user.id}>\n` +
                              `**التاريخ:** <t:${Math.floor(Date.now()/1000)}:R>`)
                .setColor(0x00FF00)
                .setTimestamp();
            
            await channel.send({ embeds: [addEmbed] });
            
        } else if (action.includes('remove')) {
            // التحقق من أن العضو مضاف بالفعل
            const existingPermissions = channel.permissionOverwrites.cache.get(targetMember.id);
            if (!existingPermissions) {
                await interaction.followUp({ 
                    content: `❌ **${targetMember.user.username} غير مضاف إلى التكت.**`,
                    ephemeral: true 
                });
                return;
            }
            
            // إزالة العضو من الروم
            await channel.permissionOverwrites.delete(targetMember.id);
            
            await interaction.followUp({ 
                content: `✅ **تمت إزالة ${targetMember} من التكت بنجاح.**`,
                ephemeral: true 
            });
            
            // إرسال إشعار في القناة
            const removeEmbed = new EmbedBuilder()
                .setDescription(`🚫 **تمت إزالة ${targetMember} من التكت**\n\n` +
                              `**بواسطة:** <@${user.id}>\n` +
                              `**التاريخ:** <t:${Math.floor(Date.now()/1000)}:R>`)
                .setColor(0xFF0000)
                .setTimestamp();
            
            await channel.send({ embeds: [removeEmbed] });
        }
        
        // تسجيل العملية في اللوق
        await logMemberAction(interaction, targetMember, action);
        
    } catch (error) {
        console.error('Error handling member action:', error);
        await interaction.followUp({ 
            content: `❌ **حدث خطأ أثناء ${action.includes('add') ? 'إضافة' : 'إزالة'} العضو:** ${error.message}`,
            ephemeral: true 
        });
    } finally {
        // تنظيف البيانات المؤقتة
        await db.delete(`temp_action_${user.id}_${channel.id}`).catch(() => {});
    }
}
async function logMemberAction(interaction, targetMember, action) {
    try {
        const logChannelId = config.logs || config.logsp;
        if (!logChannelId) return;
        
        const logChannel = interaction.guild.channels.cache.get(logChannelId);
        if (!logChannel) return;
        
        const actionText = action.includes('add') ? 'إضافة عضو' : 'إزالة عضو';
        const actionColor = action.includes('add') ? 0x00FF00 : 0xFF0000;
        const actionIcon = action.includes('add') ? '➕' : '➖';
        
        const logEmbed = new EmbedBuilder()
            .setTitle(`${actionIcon} ${actionText}`)
            .setColor(actionColor)
            .addFields(
                { name: 'المسؤول', value: `<@${interaction.user.id}>`, inline: true },
                { name: 'العضو', value: `<@${targetMember.id}>`, inline: true },
                { name: 'التكت', value: interaction.channel.name, inline: true },
                { name: 'نوع التكت', value: action.includes('support') ? 'دعم' : 'تشهير', inline: true },
                { name: 'الوقت', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true }
            )
            .setFooter({ text: `ID: ${interaction.user.id}` })
            .setTimestamp();
        
        await logChannel.send({ embeds: [logEmbed] });
        
    } catch (error) {
        console.error('Error logging member action:', error);
    }
}

async function renameTicket(interaction) {
    
    
    const { member, guild, channel, user } = interaction;
    
    // التحقق من الصلاحيات
    if (!member.roles.cache.has(config.Spportadmins)) {
        await interaction.editReply({ content: "❌ لا تملك صلاحيات لتغيير اسم التكت." });
        return;
    }
    
    await interaction.channel.send({ 
        content: "🔍 **يرجى إرسال الاسم الجديد للتكت:**"
    });
    
    const filter = m => m.author.id === user.id;
    const collector = channel.createMessageCollector({ filter, time: 30000, max: 1 });
    
    collector.on('collect', async (msg) => {
        const newName = msg.content;
        
        if (newName.length > 100) {
            await msg.reply({ content: "❌ الاسم طويل جداً (الحد الأقصى 100 حرف)." });
            return;
        }
        
        // تغيير اسم الروم
        await channel.setName(newName);
        
        await msg.reply({ 
            content: `✅ تم تغيير اسم التكت إلى: **${newName}**`
        });
    });
    
    collector.on('end', (collected) => {
        if (collected.size === 0) {
            interaction.followUp({ 
                content: "⏰ انتهى وقت الانتظار، تم إلغاء العملية.", 
                ephemeral: true 
            });
        }
    });
}

async function closeTicket(interaction) {
    try {                const { member, guild, channel, user } = interaction;

        
        // البحث عن بيانات التكت
        const allData = await db.all();
        const ticketData = allData.find(entry => 
            entry.value && 
            entry.value.channelId === channel.id
        );
        
        if (!ticketData) {
            return interaction.followUp({ 
                content: "❌ لم يتم العثور على بيانات التكت.", 
                ephemeral: true 
            });
        }
        
        const ticketInfo = ticketData.value;
        const ticketKey = ticketData.ID || `Support_ticket_${ticketInfo.userId}_${guild.id}`;
        
        // التحقق من الصلاحيات (فقط صاحب التكت أو فريق الدعم)
        if (user.id !== ticketInfo.userId && !member.roles.cache.has(config.Spportadmins)) {
            return interaction.followUp({ 
                content: "❌ ليس لديك صلاحية لإغلاق هذا التكت.", 
                ephemeral: true 
            });
        }
        
        // تحديث قاعدة البيانات
        ticketInfo.closedBy = user.id;
        ticketInfo.closedAt = new Date().toISOString();
        ticketInfo.status = 'closed';
        await db.set(ticketKey, ticketInfo);
        
        // إنشاء إيمبد الإغلاق
        const closeEmbed = new EmbedBuilder()
            .setTitle(`🔒 تم إغلاق التكت #${ticketInfo.ticketNumber || 'غير معروف'}`)
            .setDescription(`**تم إغلاق التكت بنجاح**\n\n` +
                          `**رقم التكت:** \`${ticketInfo.ticketId || 'غير معروف'}\`\n` +
                          `**صاحب التكت:** <@${ticketInfo.userId}>\n` +
                          `**مغلق التكت:** <@${user.id}>\n` +
                          `**مستلم التكت:** ${ticketInfo.claimedBy ? `<@${ticketInfo.claimedBy}>` : 'لم يتم الاستلام'}\n` +
                          `**وقت الإنشاء:** <t:${Math.floor(new Date(ticketInfo.createdAt).getTime() / 1000)}:R>\n` +
                          `**وقت الإغلاق:** <t:${Math.floor(Date.now() / 1000)}:F>\n\n` +
                          `⏳ **سيتم حذف الروم بعد 5 ثواني...**`)
            .setColor(config.color || '#051678')
.setImage(config.line || null)
            .setFooter({ 
                text: `${guild.name} | نظام التكتات`, 
                iconURL: guild.iconURL() 
            })
            .setTimestamp();
        
        await interaction.followUp({ embeds: [closeEmbed] });
        
        // حذف الروم بعد 5 ثواني
        setTimeout(async () => {
            try {
                await db.delete(ticketKey);
                await channel.delete();
            } catch (error) {
                console.error('خطأ في حذف الروم أو البيانات:', error);
            }
        }, 5000);
        
    } catch (error) {
        console.error('Error in closeTicket:', error);
        await interaction.followUp({ 
            content: "❌ حدث خطأ أثناء إغلاق التكت.", 
            ephemeral: true 
        });
    }
}

