async function cancelScamReport(interaction) {    
    await interaction.editReply({ content: "تم إلغاء عملية التشهير", components: [] });
}

async function closeScamTicket(interaction) {    
    const { member, guild, channel, user } = interaction;
    
    const scamdata = await db.get(`scam_ticket_${member.id}_${guild.id}`);
    if (!scamdata || scamdata.userId !== user.id) {
        return;
    }

    await db.delete(`scam_ticket_${member.id}_${guild.id}`);
    
    const processEmbed = new EmbedBuilder()
        .setDescription("إغلاق التذكرة خلال 5 ثواني")
        .setColor("#3b0606");
        
    await interaction.followUp({ embeds: [processEmbed] });
    
    setTimeout(() => {
        channel.delete().catch(console.error);
    }, 5000);
}

