async function sendToLog(guild, userName, userId, channelId, action) {
    try {
        const logChannel = guild.channels.cache.get(config.logs || config.logsp);
        if (!logChannel) return;

        const channelInfo = channelId ? `<#${channelId}>` : 'غير محدد';
        const timestamp = new Date().toLocaleString('ar-SA');
        
        const logMessage = `
**سجل النظام**
المستخدم: ${userName} (<@${userId}>)
الإجراء: ${action}
القناة: ${channelInfo}
الوقت: ${timestamp}
        `;

        await logChannel.send(logMessage);

    } catch (error) {
        console.error('Error sending to log:', error);
    }
}


