const activeOrders = new Map();

async function sendOrderToChannel(interaction, orderType, orderContent, price = "غير محدد") {
    const orderTypes = {
        'every': { 
            room: config.everyone_room, 
            mention: '@everyone',
            name: '@everyone'
        },
        'here': { 
            room: config.here_room, 
            mention: '@here',
            name: '@here'
        },
        'nomen': { 
            room: config.nomen_room, 
            mention: `<@&${config.role_nomen}>`,
            name: 'منشن الطلبات'
        }
    };

    const typeInfo = orderTypes[orderType];
    const ordersRoom = interaction.guild.channels.cache.get(typeInfo.room);

    if (!ordersRoom) {
        await interaction.channel.send('❌ لم يتم العثور على قناة الطلبات المحددة');
        return;
    }

    // إنشاء Select Menu
    const selectMenu = new StringSelectMenuBuilder()
        .setCustomId(`order_menu_${Date.now()}`)
        .setPlaceholder('اختر إجراءً للطلب...')
        .addOptions(
            new StringSelectMenuOptionBuilder()
                .setLabel(' التواصل مع صاحب الطلب')
                .setValue('contact_requester')
                .setEmoji('<a:by_noobot:1440038585196609596>'),
            new StringSelectMenuOptionBuilder()
                .setLabel(' عرض أسعار الطلب')
                .setValue('requests')
                .setEmoji('<a:by_noobot:1440038585196609596>'),
            new StringSelectMenuOptionBuilder()
                .setLabel(' شراء الطلب')
                .setValue('buy_order_ticket')
                .setEmoji('<a:by_noobot:1440038585196609596>'),
            new StringSelectMenuOptionBuilder()
                .setLabel(' حذف الطلب ')
                .setValue('delete_order')
                .setEmoji('<a:by_noobot:1440038585196609596>')
        );

    const row = new ActionRowBuilder().addComponents(selectMenu);

    // إرسال الطلب كرسالة نصية مع القائمة
    const orderMessage = await ordersRoom.send({ 
        content: `
**__وصف الطلب :__**
${orderContent}

**__صاحب طلب :__**
<@${interaction.user.id}>

**__نوع المنشن :__**
${typeInfo.mention}

        `,
        components: [row]
    });

    // تخزين معلومات الطلب
    activeOrders.set(orderMessage.id, {
        requesterId: interaction.user.id,
        requesterUsername: interaction.user.username,
        orderContent: orderContent,
        price: price,
        typeInfo: typeInfo,
        channelId: ordersRoom.id,
        messageId: orderMessage.id
    });

    // إرسال الخط (الصورة) بعد الرسالة
            await ordersRoom.send({ content: config.line });


    // إرسال تأكيد في قناة اللوج
    const logEmbed = new EmbedBuilder()
        .setImage(config.Line)
        .setTimestamp()
        .setAuthor({ 
            name: interaction.guild.name, 
            iconURL: interaction.guild.iconURL() 
        })
        .setThumbnail(interaction.guild.iconURL())
        .setFooter({ text: 'dev by : bh.x7 & _wx10' })
        .setTitle('تم إضافة طلب جديد')
        .setDescription(`
**صاحب طلب:** <@${interaction.user.id}>
**الطلب:** ${orderContent}
**نوع المنشن:** ${typeInfo.name}
**السعر:** ${price}
        `);

    const dnbuy = await client.channels.fetch(config.logsbuy).catch(() => null);
    if (dnbuy) await dnbuy.send({ embeds: [logEmbed] });

    await interaction.channel.send(`**✅ تم إرسال طلبك في <#${typeInfo.room}>**`);
}

