async function createRoleTicket(interaction) {
    const adminsRole = interaction.guild.roles.cache.get(config.admins);
    const roleTicketCategory = config.role_ticket_category || config.mtagrcat;
    
    const existingTicket = await db.get(`role_ticket_${interaction.user.id}`);
    if (existingTicket) {
        await interaction.editReply({ 
            content: `لديك تذكرة مفتوحة بالفعل!\n<#${existingTicket.channelId}>`, 
            ephemeral: true 
        });
        return;
    }

    const roleConfig = require('./role.json');
    
    try {
        const ticketChannel = await interaction.guild.channels.create({
            name: `role-ticket-${interaction.user.username}`,
            type: ChannelType.GuildText,
            parent: roleTicketCategory,
            permissionOverwrites: [
                {
                    id: interaction.user.id,
                    allow: [
                        PermissionsBitField.Flags.ViewChannel,
                        PermissionsBitField.Flags.SendMessages,
                        PermissionsBitField.Flags.AttachFiles,
                        PermissionsBitField.Flags.ReadMessageHistory
                    ]
                },
                {
                    id: adminsRole.id,
                    allow: [
                        PermissionsBitField.Flags.ViewChannel,
                        PermissionsBitField.Flags.SendMessages,
                        PermissionsBitField.Flags.AttachFiles,
                        PermissionsBitField.Flags.ManageMessages,
                        PermissionsBitField.Flags.ManageChannels
                    ]
                },
                {
                    id: interaction.guild.id,
                    deny: [PermissionsBitField.Flags.ViewChannel]
                }
            ]
        });

        await db.set(`role_ticket_${interaction.user.id}`, {
            userId: interaction.user.id,
            channelId: ticketChannel.id,
            createdAt: Date.now(),
            type: 'رتبة',
            userTag: interaction.user.tag,
            status: 'open'
        });

        // إنشاء قائمة اختيار الرتب
        const roleOptions = Object.keys(roleConfig).map(roleType => {
            const role = roleConfig[roleType];
            return new StringSelectMenuOptionBuilder()
                .setLabel(role.name)
                .setDescription(`السعر: ${role.price}`)
                .setValue(`role_${roleType}`);
        });

        const roleSelectMenu = new StringSelectMenuBuilder()
            .setCustomId('role_ticket_menu')
            .setPlaceholder('اختر الرتبة التي تريد شراءها...')
            .addOptions(roleOptions);

        // إنشاء قائمة التحكم في التكت (بما فيها الإغلاق)
        const controlOptions = [
            new StringSelectMenuOptionBuilder()
                .setLabel('إغلاق التذكرة')
                .setDescription('إغلاق التذكرة وحذفها')
                .setValue('close_role_ticket')
                .setEmoji('🔒'),
            
            new StringSelectMenuOptionBuilder()
                .setLabel('إعادة تحميل القائمة')
                .setDescription('إعادة تحميل قائمة الرتب')
                .setValue('reload_role_menu')
                .setEmoji('🔄')
        ];

        const controlSelectMenu = new StringSelectMenuBuilder()
            .setCustomId('role_ticket_control')
            .setPlaceholder('التحكم في التذكرة...')
            .addOptions(controlOptions);

        const roleRow = new ActionRowBuilder().addComponents(roleSelectMenu);
        const controlRow = new ActionRowBuilder().addComponents(controlSelectMenu);

        const ticketEmbed = new EmbedBuilder()
            .setAuthor({ name: interaction.guild.name, iconURL: interaction.guild.iconURL() })
            .setTitle('تذكرة شراء الرتب')
            .setDescription(`مرحباً ${interaction.user}، هذه تذكرتك لشراء الرتب`)
            .setColor(config.color || '#051678')
            .addFields(
                { 
                    name: 'معلومات التذكرة:', 
                    value: `• المستخدم: <@${interaction.user.id}>\n• التاريخ: <t:${Math.floor(Date.now()/1000)}:F>\n• الحالة: في انتظار الاختيار`, 
                    inline: false 
                },
                { 
                    name: 'أسعار الرتب:', 
                    value: Object.values(roleConfig).map(role => `**${role.name}:** ${role.price} `).join('\n'), 
                    inline: false 
                },
                { 
                    name: 'كيفية الشراء:', 
                    value: '1. اختر الرتبة المطلوبة\n2. أكد العملية\n3. تحويل المبلغ\n4. احصل على الرتبة تلقائياً', 
                    inline: false 
                }
            )
            .setFooter({ text: `طلب بواسطة: ${interaction.user.tag}`, iconURL: interaction.user.displayAvatarURL() })
            .setTimestamp()
            .setImage(config.banner || config.line);

        await ticketChannel.send({
            content: `تم فتح تذكرة شراء الرتب\n<@${interaction.user.id}> ${adminsRole ? `<@&${adminsRole.id}>` : ''}`,
            embeds: [ticketEmbed],
            components: [roleRow, controlRow]
        });

        await interaction.editReply({ 
            content: `تم فتح تذكرة شراء الرتب: <#${ticketChannel.id}>` 
        });

    } catch (error) {
        console.error('Error creating role ticket:', error);
        await interaction.editReply({ 
            content: '❌ حدث خطأ أثناء فتح التذكرة!' 
        });
    }
}
async function processRolePayment(interaction, roleType) {    
    const roleConfig = require('./role.json');
    const role = roleConfig[roleType];
    
    if (!role) {
        await interaction.followUp({ 
            content: '❌ الرتبة غير موجودة!', 
            ephemeral: true 
        });
        return;
    }

    // تحقق من الرتبة في السيرفر
    const guildRole = interaction.guild.roles.cache.get(role.roleId);
    if (!guildRole) {
        await interaction.channel.send(`❌ الرتبة غير موجودة في السيرفر!`);
        return;
    }

    // جلب بنك السيرفر
    const gConfig = await getGuildConfig(interaction.guild.id);
    const transferBank = gConfig.transferBank || config.transfer || '1299339997278769223';

    // حساب المبلغ بعد الضريبة (نفس طريقة المزاد)
    const price = parseInt(role.price);
    const noTaxPrice = Math.floor((price * 20) / 19 + 1);

    await interaction.channel.send({ 
        content: `<@${interaction.user.id}> يرجى تحويل المبلغ ${noTaxPrice}، لديك 3 دقائق للتحويل`,
        embeds: [],
        components: [] 
    });

    // إرسال أمر التحويل
    await interaction.channel.send(`#credit ${transferBank} ${noTaxPrice}`);

    // فلتر التحقق من الدفع (نفس فلتر المزاد)
    const paymentCollector = interaction.channel.createMessageCollector({
        filter: (m) => m.author.id === '282859044593598464' && 
               m.content.includes(`has transferred \`$${price}\` to <@!${transferBank}>`),
        time: 180000, // 3 دقائق
        max: 1
    });

    paymentCollector.on("collect", async (message) => {
        try {
            // تنظيف البيانات المؤقتة
            await db.delete(`role_purchase_${interaction.user.id}`);
            await db.delete(`role_selection_${interaction.user.id}`);
            
            // إعطاء الرتبة للمستخدم
            const member = await interaction.guild.members.fetch(interaction.user.id);
            await member.roles.add(guildRole);
            
            // إرسال رسالة تأكيد
            const successEmbed = new EmbedBuilder()
                .setTitle('✅ تم شراء الرتبة بنجاح')
                .setDescription(`تم إضافة رتبة **${role.name}** إلى <@${interaction.user.id}>`)
                .setColor(config.color || '#051678')
                .addFields(
                    { 
                        name: 'الرتبة', 
                        value: role.name, 
                        inline: true 
                    },
                    { 
                        name: 'السعر', 
                        value: role.price, 
                        inline: true 
                    },
                    { 
                        name: 'المستخدم', 
                        value: `<@${interaction.user.id}>`, 
                        inline: true 
                    },
                    { 
                        name: 'الوقت', 
                        value: `<t:${Math.floor(Date.now()/1000)}:R>`, 
                        inline: true 
                    },
                    { 
                        name: 'الحالة', 
                        value: '✅ تم الدفع والإضافة بنجاح', 
                        inline: true 
                    },
                    { 
                        name: 'نوع العملية', 
                        value: 'شراء رتبة تلقائي', 
                        inline: true 
                    }
                )
                .setFooter({ 
                    text: `طلب بواسطة: ${interaction.user.tag}`, 
                    iconURL: interaction.user.displayAvatarURL() 
                })
                .setTimestamp();

            // إضافة الصورة إذا كانت موجودة
            if (config.banner) {
                successEmbed.setImage(config.banner);
            } else if (config.line && config.line.startsWith('http')) {
                successEmbed.setImage(config.line || null);
            }
            
            await interaction.channel.send({ embeds: [successEmbed] });
            
            // تسجيل العملية في اللوق
            await logRolePurchase(interaction, role);
            
            // إغلاق التذكرة بعد 5 ثواني
            setTimeout(() => {
                interaction.channel.send('سيتم إغلاق التذكرة خلال 5 ثواني...');
                setTimeout(async () => {
                    try {
                        await db.delete(`role_ticket_${interaction.user.id}`);
                        await interaction.channel.delete().catch(() => {});
                    } catch (error) {
                        console.error('خطأ في إغلاق تذكرة الرتب:', error);
                    }
                }, 5000);
            }, 5000);
            
        } catch (error) {
            console.error('خطأ في معالجة شراء الرتبة:', error);
            await interaction.channel.send('❌ حدث خطأ أثناء إضافة الرتبة');
        }
    });

    paymentCollector.on("end", (collected, reason) => {
        if (reason === 'time') {
            db.delete(`role_purchase_${interaction.user.id}`);
            db.delete(`role_selection_${interaction.user.id}`);
            interaction.channel.send("❌ انتهى الوقت المخصص للتحويل. تم إلغاء العملية.");
        }
    });
}
async function closeRoleTicket(interaction) {
    try {
        
        const { channel, user, guild } = interaction;
        
        // التحقق من صحة التذكرة
        const allData = await db.all();
        const ticketData = allData.find(entry => 
            entry.value && 
            entry.value.channelId === channel.id && 
            entry.value.type === 'رتبة'
        );
        
        if (!ticketData) {
            return interaction.followUp({ 
                content: '❌ لم يتم العثور على تذكرة رتبة صالحة!', 
                ephemeral: true 
            });
        }
        
        const ticketInfo = ticketData.value;
        
        // التحقق من الصلاحيات (صاحب التكت أو مسؤول)
        const isOwner = ticketInfo.userId === user.id;
        const isAdmin = interaction.member.roles.cache.has(config.admins);
        
        if (!isOwner && !isAdmin) {
            return interaction.followUp({ 
                content: '❌ ليس لديك صلاحية لإغلاق هذه التذكرة!', 
                ephemeral: true 
            });
        }
        
        // إرسال رسالة تأكيد الإغلاق
        const closeEmbed = new EmbedBuilder()
            .setTitle('🔒 إغلاق تذكرة شراء الرتب')
            .setDescription(`**سيتم إغلاق هذه التذكرة خلال 5 ثواني...**\n\n` +
                          `**سبب الإغلاق:** طلب من المستخدم\n` +
                          `**المستخدم:** <@${user.id}>\n` +
                          `**صاحب التذكرة:** <@${ticketInfo.userId}>\n` +
                          `**تاريخ الإنشاء:** <t:${Math.floor(ticketInfo.createdAt / 1000)}:F>`)
            .setColor('#FF0000')
            .setTimestamp();
        
        await interaction.followUp({ embeds: [closeEmbed] });
        
        // حذف البيانات من قاعدة البيانات
        await db.delete(`role_ticket_${ticketInfo.userId}`);
        await db.delete(`role_selection_${ticketInfo.userId}`);
        await db.delete(`role_purchase_${ticketInfo.userId}`);
        
        // تأخير 5 ثواني ثم حذف القناة
        setTimeout(async () => {
            try {
                await channel.delete();
            } catch (error) {
                console.error('Error deleting role ticket channel:', error);
            }
        }, 5000);
        
    } catch (error) {
        console.error('Error in closeRoleTicket:', error);
        await interaction.followUp({ 
            content: '❌ حدث خطأ أثناء إغلاق التذكرة!', 
            ephemeral: true 
        });
    }
}
async function handleRoleTicketControl(interaction, selectedValue) {
    const roleType = selectedValue.replace('role_', '');
    const roleConfig = require('./role.json');
    const role = roleConfig[roleType];
    
    if (!role) {
        await interaction.reply({ 
            content: '❌ نوع الرتبة غير موجود!', 
            ephemeral: true 
        });
        return;
    }

    const ticketData = await db.get(`role_ticket_${interaction.user.id}`);
    if (!ticketData || interaction.channel.id !== ticketData.channelId) {
        await interaction.reply({ 
            content: '❌ هذه ليست تذكرتك!', 
            ephemeral: true 
        });
        return;
    }

    if (interaction.member.roles.cache.has(role.roleId)) {
        await interaction.reply({ 
            content: `❌ لديك رتبة ${role.name} بالفعل!`, 
            ephemeral: true 
        });
        return;
    }

    const activePurchase = await db.get(`role_purchase_${interaction.user.id}`);
    if (activePurchase) {
        await interaction.reply({ 
            content: '❌ لديك عملية شراء قيد التنفيذ!', 
            ephemeral: true 
        });
        return;
    }

    await interaction.deferReply({ ephemeral: false });

    // إنشاء قائمة تأكيد الشراء
    const confirmMenu = new StringSelectMenuBuilder()
        .setCustomId('role_payment_menu')
        .setPlaceholder('تأكيد شراء الرتبة...')
        .addOptions(
            new StringSelectMenuOptionBuilder()
                .setLabel(`تأكيد شراء ${role.name}`)
                .setDescription(`السعر: ${role.price} - اضغط للتأكيد`)
                .setValue(`confirm_role_${roleType}`)
                .setEmoji('✅'),
            new StringSelectMenuOptionBuilder()
                .setLabel('إلغاء العملية')
                .setDescription('إلغاء عملية الشراء')
                .setValue('cancel_role_purchase')
                .setEmoji('❌')
        );

    const row = new ActionRowBuilder().addComponents(confirmMenu);

    const confirmEmbed = new EmbedBuilder()
        .setTitle(`تأكيد شراء رتبة ${role.name}`)
        .setColor(config.color || 0x2ECC71)
        .setDescription(`**هل أنت متأكد من شراء رتبة ${role.name}؟**

**السعر:** ${role.price} 
**المشتري:** <@${interaction.user.id}>
**الرتبة:** <@&${role.roleId}>
**مهلة الدفع:** 3 دقائق

*استخدم القائمة أدناه للتأكيد أو الإلغاء*`)
        .setTimestamp();

    // حفظ اختيار الرتبة مؤقتاً
    await db.set(`role_selection_${interaction.user.id}`, {
        roleType: roleType,
        role: role,
        channelId: interaction.channel.id,
        selectedAt: Date.now()
    });

    await interaction.editReply({ 
        embeds: [confirmEmbed], 
        components: [row] 
    });
}
async function handleRolePayment(interaction, selectedValue) {
    if (selectedValue.startsWith('confirm_role_')) {
        const roleType = selectedValue.replace('confirm_role_', '');
        await processRolePayment(interaction, roleType);
    } else if (selectedValue === 'cancel_role_purchase') {
        await cancelRolePurchase(interaction);
    }
}
