async function logCleanupActivity(deletedCount, deletedTickets) {
    try {
        const logChannelId = config.logs || config.logsp || config.logsbuy;
        if (!logChannelId) return;

        const logChannel = await client.channels.fetch(logChannelId).catch(() => null);
        if (!logChannel) return;

        if (deletedCount === 0) {
            const noCleanupEmbed = new EmbedBuilder()
                .setTitle('🔧 تنظيف التكتات التلقائي')
                .setDescription('**لم يتم العثور على تكتات منتهية الصلاحية**')
                .setColor(0x00FF00)
                .addFields(
                    { name: 'الوقت', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true },
                    { name: 'الحالة', value: '✅ لا توجد تكتات منتهية', inline: true },
                    { name: 'الحد الأقصى', value: '24 ساعة', inline: true }
                )
                .setFooter({ text: 'نظام التنظيف التلقائي' })
                .setTimestamp();
            
            await logChannel.send({ embeds: [noCleanupEmbed] });
            return;
        }

        // إنشاء قائمة بالتكتات المحذوفة
        const ticketsList = deletedTickets.map((ticket, index) => {
            return `**${index + 1}. ${ticket.name}**
• النوع: ${ticket.type}
• المستخدم: <@${ticket.userId}>
• العمر: ${ticket.ageHours} ساعة
• القناة: ${ticket.channelId ? `\`${ticket.channelId}\`` : 'غير متوفر'}`;
        }).join('\n\n');

        const cleanupEmbed = new EmbedBuilder()
            .setTitle('🧹 تنظيف التكتات التلقائي')
            .setDescription(`**تم تنظيف التكتات القديمة تلقائياً**`)
            .setColor(0xFFA500)
            .addFields(
                { name: 'عدد التكتات المحذوفة', value: `${deletedCount} تذكرة`, inline: true },
                { name: 'الوقت', value: `<t:${Math.floor(Date.now()/1000)}:F>`, inline: true },
                { name: 'الحد الأقصى', value: '24 ساعة', inline: true },
                { name: 'التكتات المحذوفة', value: ticketsList.length > 1000 ? 'عدد كبير من التكتات' : ticketsList, inline: false }
            )
            .setFooter({ text: 'نظام التنظيف التلقائي | يتم التشغيل كل ساعة' })
            .setTimestamp();
        
        await logChannel.send({ embeds: [cleanupEmbed] });

    } catch (error) {
        console.error('❌ خطأ في تسجيل نشاط التنظيف:', error);
    }
}
async function cleanupOldTickets() {
    console.log('🔄 جاري تنظيف التكتات المنتهية...');
    
    const allData = await db.all();
    const now = Date.now();
    const maxAge = 24 * 60 * 60 * 1000; // 24 ساعة
    let deletedCount = 0;
    let deletedTickets = [];

    for (const item of allData) {
        const key = item.ID;
        const value = item.data;

        // تحقق من أن المفتاح هو أحد تكتات الشراء
        if (key && (key.startsWith('buy_shop_ticket_') || 
                    key.startsWith('auction_ticket_') || 
                    key.startsWith('order_ticket_') || 
                    key.startsWith('role_ticket_'))) {
            
            if (value) {
                const createdAt = value.createdAt || value.timestamp || 0;
                const age = now - createdAt;
                
                if (age > maxAge) {
                    try {
                        // تحديد نوع التكت
                        let ticketType = '';
                        let ticketName = '';
                        
                        if (key.startsWith('buy_shop_ticket_')) {
                            ticketType = 'متجر';
                            ticketName = 'تذكرة شراء متجر';
                            const userId = key.replace('buy_shop_ticket_', '');
                            await db.delete(`shop_credit_${userId}`);
                        } else if (key.startsWith('auction_ticket_')) {
                            ticketType = 'مزاد';
                            ticketName = 'تذكرة شراء مزاد';
                            const userId = key.replace('auction_ticket_', '');
                            await db.delete(`auction_credit_${userId}`);
                            await db.delete(`auction_details_${value.channelId}`);
                        } else if (key.startsWith('order_ticket_')) {
                            ticketType = 'طلب';
                            ticketName = 'تذكرة شراء طلب';
                            const userId = key.replace('order_ticket_', '');
                            await db.delete(`order_credit_${userId}`);
                        } else if (key.startsWith('role_ticket_')) {
                            ticketType = 'رتبة';
                            ticketName = 'تذكرة شراء رتبة';
                            const userId = key.replace('role_ticket_', '');
                            await db.delete(`role_purchase_${userId}`);
                            await db.delete(`role_selection_${userId}`);
                        }
                        
                        // حذف القناة إذا كانت موجودة
                        if (value.channelId) {
                            const channel = await client.channels.fetch(value.channelId).catch(() => null);
                            if (channel) {
                                await channel.delete().catch(() => {});
                            }
                        }
                        
                        // حذف التذكرة من قاعدة البيانات
                        await db.delete(key);
                        
                        deletedCount++;
                        
                        // جمع معلومات التكت المحذوف
                        deletedTickets.push({
                            type: ticketType,
                            name: ticketName,
                            userId: value.userId,
                            channelId: value.channelId,
                            ageHours: Math.floor(age / (60 * 60 * 1000))
                        });
                        
                        console.log(`✅ حذف ${ticketType}: ${key} (عمر: ${Math.floor(age / (60 * 60 * 1000))} ساعة)`);
                        
                    } catch (error) {
                        console.error(`❌ خطأ في حذف التكت ${key}:`, error);
                    }
                }
            }
        }
        
        // تنظيف البيانات المؤقتة
        if (key && (key.startsWith('shop_credit_') || 
                    key.startsWith('auction_credit_') || 
                    key.startsWith('order_credit_') || 
                    key.startsWith('role_purchase_') || 
                    key.startsWith('role_selection_') || 
                    key.startsWith('current_order_type_') || 
                    key.startsWith('current_auction_type_') || 
                    key.startsWith('temp_action_'))) {
            
            try {
                if (value && value.timestamp) {
                    const age = now - value.timestamp;
                    if (age > 60 * 60 * 1000) { // ساعة واحدة
                        await db.delete(key);
                    }
                }
            } catch (error) {
                console.error(`❌ خطأ في حذف البيانات المؤقتة:`, error);
            }
        }
    }

    // تسجيل العملية في اللوق
    await logCleanupActivity(deletedCount, deletedTickets);
    
    console.log(`✅ تم الانتهاء من التنظيف. عدد التكتات المحذوفة: ${deletedCount}`);
}


client.on("messageCreate", async (message) => {
    if (message.content === "!تنظيف التكتات") {
        // التحقق من الصلاحيات - الإدارة أو المطور فقط
        if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
            if (message.author.id !== "959174041422397471") return;
        }
        
        try {
            await message.delete();
        } catch {}
        
        const processingMsg = await message.channel.send("🔄 **جاري تنظيف التكتات القديمة...**");
        
        const startTime = Date.now();
        await cleanupOldTickets();
        const endTime = Date.now();
        const duration = endTime - startTime;
        
        await processingMsg.edit(`✅ **تم الانتهاء من التنظيف خلال ${duration}ms**`);
    }
    
    if (message.content === "!احصائيات التكتات") {
        if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
            if (message.author.id !== "959174041422397471") return;
        }
        
        try {
            await message.delete();
        } catch {}
        
        const allData = await db.all();
        let shopTickets = 0;
        let auctionTickets = 0;
        let orderTickets = 0;
        let roleTickets = 0;
        let activeTickets = 0;
        
        for (const item of allData) {
            const key = item.ID;
            if (key) {
                if (key.startsWith('buy_shop_ticket_')) shopTickets++;
                else if (key.startsWith('auction_ticket_')) auctionTickets++;
                else if (key.startsWith('order_ticket_')) orderTickets++;
                else if (key.startsWith('role_ticket_')) roleTickets++;
            }
        }
        
        activeTickets = shopTickets + auctionTickets + orderTickets + roleTickets;
        
        const statsEmbed = new EmbedBuilder()
            .setTitle('📊 إحصائيات التكتات النشطة')
            .setColor(0x3498DB)
            .setDescription('**إحصائيات التكتات الحالية في النظام:**')
            .addFields(
                { name: 'المتاجر', value: `${shopTickets} تذكرة`, inline: true },
                { name: ' المزادات', value: `${auctionTickets} تذكرة`, inline: true },
                { name: ' الطلبات', value: `${orderTickets} تذكرة`, inline: true },
                { name: ' الرتب', value: `${roleTickets} تذكرة`, inline: true },
                { name: ' الإجمالي', value: `${activeTickets} تذكرة`, inline: false },
                { name: ' آخر تنظيف', value: `<t:${Math.floor(Date.now()/1000)}:R>`, inline: false }
            )
            .setFooter({ text: `طلب بواسطة: ${message.author.tag}` })
            .setTimestamp();
        
        await message.channel.send({ embeds: [statsEmbed] });
    }
});



