client.on("messageCreate", async (message) => {
    if (message.content.startsWith("!اغلاق")) {
        if (!message.member.permissions.has(PermissionsBitField.Flags.Administrator)) {
            if (message.author.id !== "959174041422397471") return;
        }
        
        // حذف رسالة الأمر
        try {
            await message.delete();
        } catch {}
        
        // الحصول على قناة التكت الحالية
        const currentChannel = message.channel;
        
        // البحث عن تكت في هذه القناة بالتحديد
        let foundTicket = null;
        let ticketType = '';
        
        // البحث في جميع أنواع التكتات
        const allData = await db.all();
        
        for (const entry of allData) {
            const data = entry.value;
            
            if (data && data.channelId === currentChannel.id) {
                // تحديد نوع التكت
                if (data.type === 'رتبة') {
                    foundTicket = data;
                    ticketType = 'role_ticket_';
                    break;
                } else if (data.type === 'تشهير') {
                    foundTicket = data;
                    ticketType = 'scam_ticket_';
                    break;
                } else if (data.status && data.userId) {
                    // محاولة تحديد النوع من المفتاح
                    const key = entry.id;
                    if (key.includes('buy_shop_ticket_')) {
                        foundTicket = data;
                        ticketType = 'buy_shop_ticket_';
                        break;
                    } else if (key.includes('auction_ticket_')) {
                        foundTicket = data;
                        ticketType = 'auction_ticket_';
                        break;
                    } else if (key.includes('order_ticket_')) {
                        foundTicket = data;
                        ticketType = 'order_ticket_';
                        break;
                    } else if (key.includes('Support_ticket_')) {
                        foundTicket = data;
                        ticketType = 'Support_ticket_';
                        break;
                    }
                }
            }
        }
        
        if (!foundTicket) {
            return message.channel.send('❌ **هذه القناة ليست تكتاً أو لا توجد بيانات عنها!**')
                .then(msg => setTimeout(() => msg.delete(), 5000));
        }
        
        const userId = foundTicket.userId;
        const ticketKey = `${ticketType}${userId}`;
        
        // حذف القناة
        try {
            await currentChannel.delete();
        } catch (error) {
            console.error('Error deleting channel:', error);
        }
        
        // حذف التذكرة من قاعدة البيانات
        await db.delete(ticketKey);
        
        // حذف البيانات المرتبطة
        if (ticketType === 'buy_shop_ticket_') {
            await db.delete(`shop_credit_${userId}`);
            await db.delete(`shop_${currentChannel.id}`);
        } else if (ticketType === 'auction_ticket_') {
            await db.delete(`auction_credit_${userId}`);
            await db.delete(`auction_details_${currentChannel.id}`);
        } else if (ticketType === 'order_ticket_') {
            await db.delete(`order_credit_${userId}`);
        } else if (ticketType === 'role_ticket_') {
            await db.delete(`role_purchase_${userId}`);
            await db.delete(`role_selection_${userId}`);
        } else if (ticketType === 'scam_ticket_') {
            await db.delete(`scam_report_${currentChannel.id}`);
        } else if (ticketType === 'Support_ticket_') {
            // لا توجد بيانات مرتبطة إضافية للتذاكر الدعم
        }
        
        // تحديد اسم نوع التكت
        let ticketTypeName = '';
        switch (ticketType) {
            case 'buy_shop_ticket_':
                ticketTypeName = 'متجر';
                break;
            case 'auction_ticket_':
                ticketTypeName = 'مزاد';
                break;
            case 'order_ticket_':
                ticketTypeName = 'طلب';
                break;
            case 'role_ticket_':
                ticketTypeName = 'رتبة';
                break;
            case 'scam_ticket_':
                ticketTypeName = 'تشهير';
                break;
            case 'Support_ticket_':
                ticketTypeName = 'دعم فني';
                break;
            default:
                ticketTypeName = 'غير معروف';
        }
        
        // تسجيل الحذف في اللوق
        const deleteEmbed = new EmbedBuilder()
            .setTitle(' إغلاق تكت يدوي')
            .setDescription(`**تم إغلاق تكت ${ticketTypeName} يدوياً**`)
            .setColor(0xFF0000)
            .addFields([
                {
                    name: ' معلومات التكت',
                    value: `**النوع:** ${ticketTypeName}\n**صاحب التكت:** <@${userId}>\n**القناة:** ${currentChannel.name}`,
                    inline: false
                },
                {
                    name: ' المسؤول',
                    value: `<@${message.author.id}>`,
                    inline: true
                },
                {
                    name: ' الوقت',
                    value: `<t:${Math.floor(Date.now() / 1000)}:F>`,
                    inline: true
                }
            ])
            .setFooter({ text: 'الإغلاق اليدوي' })
            .setTimestamp();
        
        // إرسال إلى سجل التذاكر
        const logChannelId = config.logs || config.logsp;
        if (logChannelId) {
            const logChannel = await client.channels.fetch(logChannelId).catch(() => null);
            if (logChannel) {
                await logChannel.send({ embeds: [deleteEmbed] });
            }
        }
        
        // إرسال إشعار للمسؤول (سريع قبل حذف القناة)
        const noticeEmbed = new EmbedBuilder()
            .setDescription(`✅ **تم إغلاق تكت ${ticketTypeName} بنجاح**`)
            .setColor(0x00FF00)
            .setTimestamp();
        
        try {
            const noticeMsg = await currentChannel.send({ embeds: [noticeEmbed] });
            setTimeout(() => {
                noticeMsg.delete().catch(() => {});
            }, 2000);
        } catch {}
    }
});































client.on("messageCreate", async (message) => {
    if (!message.guild || message.author.bot) return;
    const guildConfig = await getGuildConfig(message.guild.id);
    const autotax = guildConfig['tax-channels'] || [];
    if (!Array.isArray(autotax) || !autotax.includes(message.channel.id)) return;

    const content = message.content.trim();
    
    // التحقق من المدخلات
    if (!content || content.match(/^(m|k|K|M|B|b|مليون|الف|ألف|ك|م|الأف|الاف|ملايين|مليار|بليون)$/)) {
        return await message.reply(`يرجى كتابة عدد لحساب ضريبته`);
    }

    // تحويل المدخلات إلى أرقام
    let args = content;
    const multipliers = {
        'm': 1000000,
        'k': 1000,
        'K': 1000,
        'M': 1000000,
        'B': 1000000000,
        'b': 1000000000,
        'مليون': 1000000,
        'الف': 1000,
        'ألف': 1000,
        'ك': 1000,
        'م': 1000000,
        'آلاف': 1000,
        'ألاف': 1000,
        'الاف': 1000,
        'ملايين': 1000000,
        'مليار': 1000000000,
        'بليون': 1000000000
    };

    for (const [key, value] of Object.entries(multipliers)) {
        if (args.endsWith(key)) {
            args = args.replace(new RegExp(key, 'gi'), '') * value;
            break;
        }
    }

    if (isNaN(args) || args <= 0) {
        return await message.reply("__** لو سمحت الاونر تعب وسوى شي يسمى بشات العام روح اكتب هناك كل شي تبيه بس طبعا بدون ما تخالف القوانين**__");
    }

    args = parseInt(args);

    let tax = Math.floor((args * 20) / 19 + 1);
    let tax2 = Math.floor(args * 0.05);
    let tax3 = Math.floor((tax * 20) / 19 + 1);
    let tax4 = Math.floor(args * 0.95);
    let tax5 = Math.floor(tax / 0.95 + 1);
    let tax6 = Math.floor(args / 0.95 + 1);
    let rate = Math.floor(args * 0.02);

    const evay = new EmbedBuilder()
        .setAuthor({ name: message.guild.name, iconURL: message.guild.iconURL() })
        .setFooter({ text: message.guild.name, iconURL: message.guild.iconURL() })
        .setThumbnail(message.guild.iconURL())
        .setTitle(`ضريبة المبلغ  : ${args}`)
        .setColor('#3b0606')
        .addFields(
            { name: `** الضريبه العاديه : **`, value: `${tax}`, inline: true },
            { name: `** المبلغ بضريبتين : **`, value: `${tax3}`, inline: true },
            { name: ` ** المبلغ كامل مع ضريبه الوسيط :** `, value: `${tax6}`, inline: true },
            { name: ` ** نسبه الوسيط 2% : ** `, value: `${rate}`, inline: true },
            { name: ` ** الضريبه كامله مع نسبه الوسيط : ** `, value: `${tax3 + rate}`, inline: true },
        )
        .setTimestamp()
        .setImage(config.line || null);

    const row = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('copy_tax')
                .setLabel('نسخ الضريبة')
                .setStyle(ButtonStyle.Primary)
        );

    await message.reply({ embeds: [evay], components: [row] }).catch((err) => {
        console.log(err.message);
    });
});



// نظام المنشنات اليدوية
const SHOP_ROLE_ID = "1439645100861947969";

client.on('messageCreate', async m => {
    if (!m.content || m.author.bot) return;
    
    const data = await db.get(`shop_${m.channel.id}`);
    if (!data) return;
    
    const warns = data.warns || 0;
    let hasViolation = false;
    let violationType = '';
    
    // تحقق من @everyone
    if (m.content.includes('@everyone')) {
        if (data.every > 0) {
            // تخفيض عدد المنشنات المتاحة
            await db.sub(`shop_${m.channel.id}.every`, 1);
        } else { // exactMatch is true - strict equality
            hasViolation = true;
            violationType = '@everyone';
        }
    }
    
    // تحقق من @here
    if (m.content.includes('@here')) {
        if (data.here > 0) {
            // تخفيض عدد المنشنات المتاحة
            await db.sub(`shop_${m.channel.id}.here`, 1);
        } else { // exactMatch is true - strict equality
            hasViolation = true;
            violationType = '@here';
        }
    }
    
    // تحقق من منشن رول المتجر
    if (m.content.includes(`<@&${SHOP_ROLE_ID}>`)) {
        if (data.shop > 0) {
            // تخفيض عدد المنشنات المتاحة
            await db.sub(`shop_${m.channel.id}.shop`, 1);
        } else { // exactMatch is true - strict equality
            hasViolation = true;
            violationType = 'Shop Role';
        }
    }
    
    // معالجة المخالفة
    if (hasViolation) {
        const newWarns = warns + 1;
        
        // إرسال رسالة التحذير
        const warningMessage = await m.reply({
            content: `**⚠️ تحذير: لا يوجد منشنات ${violationType} متاحة**\n**عدد تحذيرات المتجر: ${newWarns}/5**`,
            allowedMentions: { repliedUser: false }
        });
        
        
        
        // تحديث عدد التحذيرات
        await db.set(`shop_${m.channel.id}.warns`, newWarns);
        
        // إذا وصلت التحذيرات إلى 5، إيقاف المتجر
        if (newWarns >= 5) {
            // إغلاق القناة
            await m.channel.permissionOverwrites.edit(m.guild.roles.everyone.id, {
                ViewChannel: false,
                SendMessages: false
            });
            
            // تحديث حالة المتجر
            await db.set(`shop_${m.channel.id}.disabled`, true);
            await db.set(`shop_${m.channel.id}.disabledReason`, "تجاوز الحد الأقصى للتحذيرات (5 تحذيرات)");
            
            // إرسال إشعار بالإغلاق
            await warningMessage.edit({
                content: `**🚫 تم إيقاف المتجر بسبب تجاوز الحد الأقصى للتحذيرات (5 تحذيرات)**\n**يرجى التواصل مع الإدارة لإعادة فتح المتجر.**`
            });
            
            // إرسال إشعار إلى قناة اللوق
            const logChannel = m.guild.channels.cache.get(config.logsp);
            if (logChannel) {
                const embed = new EmbedBuilder()
                    .setTitle('🚫 تم إيقاف متجر')
                    .setDescription(`تم إيقاف المتجر <#${m.channel.id}> بسبب تجاوز الحد الأقصى للتحذيرات.`)
                    .addFields(
                        { name: 'المتجر', value: `<#${m.channel.id}>`, inline: true },
                        { name: 'المالك', value: `<@${data.owner}>`, inline: true },
                        { name: 'التحذيرات', value: `${newWarns}/5`, inline: true },
                        { name: 'سبب الإغلاق', value: 'تجاوز الحد الأقصى للتحذيرات', inline: true },
                        { name: 'المنشن المخالف', value: violationType, inline: true }
                    )
                    .setColor('#FF0000')
                    .setTimestamp();
                
                await logChannel.send({ embeds: [embed] });
            }
        }
        
        // إرسال إشعار إلى المالك بعد كل تحذير
        try {
            const owner = await m.client.users.fetch(data.owner);
            if (owner) {
                const dmEmbed = new EmbedBuilder()
                    .setTitle('⚠️ تحذير للمتجر')
                    .setDescription(`تلقى متجرك <#${m.channel.id}> تحذيراً بسبب استخدام منشن ${violationType} بدون رصيد كافٍ.`)
                    .addFields(
                        { name: 'عدد التحذيرات الحالي', value: `${newWarns}/5`, inline: true },
                        { name: 'المنشن المخالف', value: violationType, inline: true }
                    )
                    .setColor('#FF9900')
                    .setFooter({ text: 'يرجى شراء المزيد من المنشنات لتجنب إيقاف المتجر' })
                    .setTimestamp();
                
                await owner.send({ embeds: [dmEmbed] });
            }
        } catch (dmError) {
            console.log('فشل إرسال رسالة خاصة للمالك:', dmError);
        }
    }
});



// التعامل مع التفاعلات (الزر)
client.on('interactionCreate', async interaction => {
    if (!interaction.isButton()) return;
    
    if (interaction.customId === 'copy_tax') {
        const user = interaction.user;

        let args = await calculateTax(interaction.message.embeds[0]); // تأكد من تعديل هذه الوظيفة لتعيد القيم الضريبية
        if (!args) return await interaction.reply({ content: 'لم أتمكن من حساب الضرائب.', ephemeral: true });

        const taxMessage = `
            **تفاصيل الضريبة:**
            - **الضريبة العادية:** ${args.tax}
            - **المبلغ بضريبتين:** ${args.tax3}
            - **المبلغ كامل مع ضريبة الوسيط:** ${args.tax6}
            - **نسبة الوسيط 2%:** ${args.rate}
            - **الضريبة كاملة مع نسبة الوسيط:** ${args.tax3 + args.rate}
        `;

        await user.send(taxMessage).catch(err => console.log(`Could not send message to user: ${err}`));
        await interaction.reply({ content: 'تم إرسال تفاصيل الضرائب لك في الخاص!', ephemeral: true });
    }
});

// وظيفة لحساب الضرائب وإرجاع القيم
async function calculateTax(embed) {
    // يمكنك استخراج المعلومات من الـ embed هنا وإعادتها
    const tax = parseInt(embed.fields[0].value);
    const tax3 = parseInt(embed.fields[1].value);
    const tax6 = parseInt(embed.fields[2].value);
    const rate = parseInt(embed.fields[3].value);
    
    return { tax, tax3, tax6, rate };
}
    
client.on('messageCreate', async message => {
    if (message.author.bot) return;
    
    // التحقق من أن المرسل هو أدمن
    if (!message.member.roles.cache.has(config.Actionadmins)) return;
    
    // التحقق من أن الرسالة في روم المزاد
    if (message.channel.id !== config.auctionroom1) return;
    
    if (message.content === 'ايقاف المزاد') {
        // التحقق من وجود مزاد نشط
        const auctionRunning = await db.get('isAuctionRunning');
        if (!auctionRunning) {
            return message.reply('لا يوجد مزاد نشط حالياً.');
        }

        try {
            // إرسال رسالة تأكيد الإيقاف
            const stopEmbed = new EmbedBuilder()
                .setTitle("إيقاف المزاد")
                .setDescription("جارٍ إيقاف المزاد وحذف جميع البيانات...")
                .setColor("#FF0000")
                .setTimestamp();
            
            const stopMessage = await message.channel.send({ embeds: [stopEmbed] });

            // إعادة تعيين حالة المزاد في قاعدة ا��بيانات
            await db.set('isAuctionRunning', false);
            
            // حذف جميع بيانات المزادات النشطة
            const allKeys = await db.all();
            for (const key of allKeys) {
                if (key.id.startsWith('auction_details_')) {
                    await db.delete(key.id);
                }
            }

            // حذف جميع الرسائل في الروم
            try {
                const messages = await message.channel.messages.fetch({ limit: 100 });
                await message.channel.bulkDelete(messages);
            } catch (error) {
                console.error("خطأ في حذف الرسائل:", error);
            }

            // إغلاق الروم
            await message.channel.permissionOverwrites.edit(message.guild.roles.everyone, { 
                ViewChannel: false, 
                SendMessages: false 
            });

            // إرسال رسالة الأسعار
            const pricesEmbed = new EmbedBuilder()
                .setTitle("أسعار المزادات")
                .setDescription(`تم إيقاف المزاد بنجاح.\n\nيمكنك بدء مزاد جديد الآن من التكت.\n\n- منشن ايفري: ${config.tax_everyone_auction}\n- منشن هير: ${config.tax_here_auction}\n- منشن مزاد: ${config.tax_mzad_auction}`)
                .setColor("#178afc")
                .setTimestamp();

            await message.channel.send({ embeds: [pricesEmbed] });

            // حذف رسالة التأكيد بعد ثانية
            setTimeout(() => {
                stopMessage.delete().catch(console.error);
            }, 1000);

        } catch (error) {
            console.error('خطأ في إيقاف المزاد:', error);
            await message.reply('حدث خطأ أثناء إيقاف المزاد.');
        }
    }
});

