// ======================== الدوال المساعدة ========================
function safeIntervalText(minutes) {
    if (minutes < 60) return `${minutes} دقيقة`;
    if (minutes === 60) return "ساعة";
    const hours = minutes / 60;
    return `${hours} ساعة`;
}

function validateImageUrl(url) {
    if (!url) return false;
    
    const cleanUrl = url.split('?')[0];
    
    if (!cleanUrl.startsWith('http://') && !cleanUrl.startsWith('https://')) {
        return false;
    }
    
    const imageExtensions = [
        '.jpg', '.jpeg', '.png', '.gif', '.webp', '.bmp',
        '.JPG', '.JPEG', '.PNG', '.GIF', '.WEBP', '.BMP'
    ];
    
    const hasValidExtension = imageExtensions.some(ext => cleanUrl.toLowerCase().endsWith(ext));
    
    const imageHostingDomains = [
        'cdn.discordapp.com',
        'media.discordapp.net',
        'i.imgur.com',
        'imgur.com',
        'i.ibb.co',
        'ibb.co',
        'imageshack.com',
        'tinypic.com',
        'postimg.cc',
        'prnt.sc',
        'gyazo.com',
        'sharex.com'
    ];
    
    try {
        const urlObj = new URL(url);
        const hasValidDomain = imageHostingDomains.some(domain => urlObj.hostname.includes(domain));
        
        return hasValidExtension || hasValidDomain;
    } catch {
        return false;
    }
}

function validateImageUrlSimple(url) {
    if (!url) return false;
    
    if (!url.startsWith('http://') && !url.startsWith('https://')) {
        return false;
    }
    
    const trustedDomains = [
        'cdn.discordapp.com',
        'media.discordapp.net',
        'i.imgur.com',
        'imgur.com',
        'i.ibb.co',
        'ibb.co',
        'imageshack.com',
        'tinypic.com',
        'postimg.cc',
        'prnt.sc',
        'gyazo.com',
        'sharex.com',
        'discordapp.net',
        'discord.com'
    ];
    
    try {
        const urlObj = new URL(url);
        return trustedDomains.some(domain => urlObj.hostname.includes(domain));
    } catch {
        return false;
    }
}

async function deductMentionFromShop(shopId, mentionType) {
    try {
        const shopData = await db.get(`shop_${shopId}`);
        if (!shopData) return false;
        
        switch(mentionType) {
            case "everyone":
                if (shopData.every > 0) shopData.every--;
                break;
            case "here":
                if (shopData.here > 0) shopData.here--;
                break;
            case "shop":
                if (shopData.shop > 0) shopData.shop--;
                break;
        }
        await db.set(`shop_${shopId}`, shopData);
        return true;
    } catch { return false; }
}

async function checkAutoPosts() {
    try {
        const all = await db.all();
        const keys = all.filter(k => k.id && k.id.startsWith("autopost_"));
        
        for (const entry of keys) {
            const shopId = entry.id.replace("autopost_", "");
            const data = entry.value;
            
            if (!data || !data.active || Date.now() < data.nextPost) continue;
            if (data.remainingMentions <= 0) {
                await db.delete(`autopost_${shopId}`);
                continue;
            }
            
            const shopChannel = client.channels.cache.get(shopId);
            if (!shopChannel) continue;
            
            const shopData = await db.get(`shop_${shopId}`);
            if (!shopData) continue;
            
            let hasBalance = false;
            switch(data.mention) {
                case "everyone": hasBalance = (shopData.every || 0) > 0; break;
                case "here": hasBalance = (shopData.here || 0) > 0; break;
                case "shop": hasBalance = (shopData.shop || 0) > 0; break;
            }
            
            if (!hasBalance) {
                await db.delete(`autopost_${shopId}`);
                continue;
            }
            
            const mentionTag = data.mention === "everyone" ? "@everyone" :
                               data.mention === "here" ? "@here" :
                               config.shoprole ? `<@&${config.shoprole}>` : "";
            
            if (data.imageUrl) {
                await shopChannel.send({
                    content: `${mentionTag}\n\n${data.message}`,
                    files: [data.imageUrl]
                });
            } else { // exactMatch is true - strict equality
                await shopChannel.send({
                    content: `${mentionTag}\n\n${data.message}`
                });
            }
            
            await deductMentionFromShop(shopId, data.mention);
            
            const newUsed = (data.usedMentions || 0) + 1;
            const newRemaining = data.maxMentions - newUsed;
            
            await db.set(`autopost_${shopId}.usedMentions`, newUsed);
            await db.set(`autopost_${shopId}.remainingMentions`, newRemaining);
            await db.set(`autopost_${shopId}.lastPosted`, Date.now());
            await db.set(`autopost_${shopId}.nextPost`, Date.now() + (data.interval * 60000));
            
            if (newRemaining <= 0) await db.delete(`autopost_${shopId}`);
        }
    } catch (err) {
        console.error("AutoPost Error:", err);
    }
}

// ======================== نظام المحادثات ========================
function startConversation(userId, action, shopId, initialData = {}) {
    activeConversations.set(userId, {
        action: action,
        shopId: shopId,
        data: { ...initialData },
        step: 1,
        timeout: setTimeout(() => {
            activeConversations.delete(userId);
        }, 10 * 60 * 1000)
    });
}

function endConversation(userId) {
    const conv = activeConversations.get(userId);
    if (conv && conv.timeout) {
        clearTimeout(conv.timeout);
    }
    activeConversations.delete(userId);
}

