async function processRenameShop(m, conv) {
    const { newName, tax, price } = conv.data;
    const gConfig = await getGuildConfig(m.guild.id);
    const transferBank = gConfig.transferBank || config.transfer || '1299339997278769223';
    
    await m.channel.send(`#credit ${transferBank} ${tax}`);
    
    const embed = new EmbedBuilder()
        .setTitle('⏳ جاري معالجة طلبك')
        .setDescription(`**الرجاء تحويل المبلغ:** \`${tax}\`\n\nسأنتظر 60 ثانية للتحقق من التحويل...`)
            .setColor(config.color || '#051678')
                        .setImage(config.line || null)

        .setFooter({ text: 'تأكد من تحويل المبلغ المطلوب' });
    
    const processingMsg = await m.channel.send({ 
        content: `<@${m.author.id}>`,
        embeds: [embed]
    });
    
    const filter = ({ content, author: { id } }) => {
        return (
            content.startsWith(`**:moneybag: | ${m.author.username}, has transferred `) &&
            content.includes(`${transferBank}`) &&
            id === "282859044593598464" &&
            (Number(content.slice(content.lastIndexOf("`") - String(tax).length, content.lastIndexOf("`"))) >= price)
        );
    };
    
    const collector = m.channel.createMessageCollector({ 
        filter, 
        max: 1, 
        time: 60000 
    });
    
    let paymentReceived = false;
    
    collector.on('collect', async (collected) => {
        paymentReceived = true;
        
        try {
            const shopChannel = m.guild.channels.cache.get(conv.shopId);
            if (shopChannel) {
                let prefix = "";
                
                for (const type of types) {
                    if (shopChannel.name.startsWith(type.prefix)) {
                        prefix = type.prefix;
                        break;
                    }
                }
                
                const newChannelName = `${prefix} ${newName}`.trim();
                await shopChannel.setName(newChannelName);
            }
            
            const successEmbed = new EmbedBuilder()
                .setTitle('✅ تم تغيير اسم المتجر بنجاح')
                                .setImage(config.line || null)

                .setDescription(`**الاسم الجديد:** \`${newName}\`\n**المبلغ المدفوع:** \`${tax}\``)
            .setColor(config.color || '#051678')
                .setTimestamp();
            
            await processingMsg.edit({ 
                content: `<@${m.author.id}>`,
                embeds: [successEmbed] 
            });
            
        } catch (error) {
            console.error('خطأ في تغيير الاسم:', error);
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **حدث خطأ أثناء تغيير الاسم**`
            });
        }
        
        endConversation(m.author.id);
    });
    
    collector.on('end', async (collected, reason) => {
        if (!paymentReceived && reason === 'time') {
            const timeoutEmbed = new EmbedBuilder()
                .setTitle('❌ انتهى الوقت')
                .setDescription('لم يتم استلام التحويل خلال الوقت المحدد')
                .setColor('#ff0000')
                .setTimestamp();
            
            await processingMsg.edit({ 
                content: `<@${m.author.id}>`,
                embeds: [timeoutEmbed] 
            });
            
            endConversation(m.author.id);
        }
    });
}

