async function handleAutopostChat(m, conv) {
    switch(conv.step) {
        case 1:
            conv.data.message = m.content;
            conv.step = 2;
            activeConversations.set(m.author.id, conv);
            
            const embed1 = new EmbedBuilder()
                .setTitle('نـشـر تـلـقـائـي - الخطوة 2/6')
                .setDescription('**اختر نوع المنشن:**\nاكتب واحد من:\n• **everyone** (@everyone)\n• **here** (@here)\n• **shop** (@رول المتجر)')
                    .setImage(config.line || null)

            .setColor(config.color || '#051678')
                .setFooter({ text: 'اكتب "إلغاء" للإلغاء' });
            
            await m.channel.send({ 
                content: `<@${m.author.id}>`,
                embeds: [embed1]
            });
            break;
            
        case 2:
            const mentionType = m.content.toLowerCase();
            if (!['everyone', 'here', 'shop'].includes(mentionType)) {
                await m.channel.send({ 
                    content: `<@${m.author.id}> ❌ **النوع غير صحيح. اختر من: everyone, here, shop**`
                });
                return;
            }
            
            conv.data.mentionType = mentionType;
            conv.step = 3;
            activeConversations.set(m.author.id, conv);
            
            const embed2 = new EmbedBuilder()
                .setTitle('نـشـر تـلـقـائـي - الخطوة 3/6')
                .setDescription('**أدخل الفترة بالدقائق:**\nمثال: `60` (كل ساعة)')
            .setColor(config.color || '#051678')
            
                    .setImage(config.line || null)

                .setFooter({ text: 'اكتب "إلغاء" للإلغاء' });
            
            await m.channel.send({ 
                content: `<@${m.author.id}>`,
                embeds: [embed2]
            });
            break;
            
        case 3:
            const interval = parseInt(m.content);
            if (isNaN(interval) || interval < 1) {
                await m.channel.send({ 
                    content: `<@${m.author.id}> ❌ **الرجاء إدخال عدد دقائق صحيح أكبر من الصفر**`
                });
                return;
            }
            
            conv.data.interval = interval;
            conv.step = 4;
            activeConversations.set(m.author.id, conv);
            
            const embed3 = new EmbedBuilder()
                .setTitle('نـشـر تـلـقـائـي - الخطوة 4/6')
                .setDescription('**أدخل عدد المنشنات:**\nمثال: `10` (10 منشن)')
            .setColor(config.color || '#051678')
                    .setImage(config.line || null)

                .setFooter({ text: 'اكتب "إلغاء" للإلغاء' });
            
            await m.channel.send({ 
                content: `<@${m.author.id}>`,
                embeds: [embed3]
            });
            break;
            
        case 4:
            const maxMentions = parseInt(m.content);
            if (isNaN(maxMentions) || maxMentions < 1) {
                await m.channel.send({ 
                    content: `<@${m.author.id}> ❌ **الرجاء إدخال عدد صحيح أكبر من الصفر**`
                });
                return;
            }
            
            conv.data.maxMentions = maxMentions;
            conv.step = 5;
            activeConversations.set(m.author.id, conv);
            
            const embed4 = new EmbedBuilder()
                .setTitle('نـشـر تـلـقـائـي - الخطوة 5/6')
                .setDescription('**أدخل رابط الصورة (اختياري):**\nيمكنك تركها فارغة بكتابة `تخطي`')
            .setColor(config.color || '#051678')
                    .setImage(config.line || null)

                .setFooter({ text: 'اكتب "إلغاء" للإلغاء' });
            
            await m.channel.send({ 
                content: `<@${m.author.id}>`,
                embeds: [embed4]
            });
            break;
            
        case 5:
            let imageUrl = m.content.trim();
            
            if (imageUrl.toLowerCase() === 'تخطي') {
                imageUrl = null;
            } else if (imageUrl && !validateImageUrl(imageUrl)) {
                await m.channel.send({ 
                    content: `<@${m.author.id}> ❌ **رابط الصورة غير صالح**`
                });
                return;
            }
            
            conv.data.imageUrl = imageUrl;
            conv.step = 6;
            activeConversations.set(m.author.id, conv);
            
            const mention = conv.data.mentionType;
            const intervalVal = conv.data.interval;
            const maxMentionsVal = conv.data.maxMentions;
            
const priceBase = mention === "everyone" ? 5000 : mention === "here" ? 3000 : mention === "shop" ? 1500 : 10;            const price = priceBase * Math.max(5, Math.ceil(60 / intervalVal));
            const totalPrice = price * maxMentionsVal;
            const tax = Math.floor(totalPrice * (20 / 19) + 1);
            
            conv.data.price = totalPrice;
            conv.data.tax = tax;
            
            const preview = new EmbedBuilder()
                .setTitle('تأكيد النشر التلقائي')
                    .setImage(config.line || null)

                .setDescription(`**التفاصيل:**\n• الرسالة: ${conv.data.message.substring(0, 100)}${conv.data.message.length > 100 ? "..." : ""}\n• الفترة: كل ${safeIntervalText(intervalVal)}\n• المنشن: ${mention}\n• عدد المنشنات: ${maxMentionsVal}\n• السعر الإجمالي: \`${totalPrice}\`\n• بعد الضريبة: \`${tax}\`\n\n**للتأكيد اكتب:** \`تأكيد\`\n**للإلغاء اكتب:** \`إلغاء\``)
            .setColor(config.color || '#051678')
                .setFooter({ text: 'سيتم إرسال طلب الدفع بعد التأكيد' });
            
            await m.channel.send({ 
                content: `<@${m.author.id}>`,
                embeds: [preview]
            });
            break;
            
        case 6:
            if (m.content.toLowerCase() === 'تأكيد') {
                await processAutopost(m, conv);
            } 
            break;
    }
}

async function processAutopost(m, conv) {
    const { message, mentionType, interval, maxMentions, imageUrl, tax, price } = conv.data;
    const gConfig = await getGuildConfig(m.guild.id);
    const transferBank = gConfig.transferBank || config.transfer || '1299339997278769223';
    
    await m.channel.send(`#credit ${transferBank} ${tax}`);
    
    const embed = new EmbedBuilder()
        .setTitle('⏳ جاري معالجة طلبك')
        .setDescription(`**الرجاء تحويل المبلغ:** \`${tax}\`\n\nسأنتظر 60 ثانية للتحقق من التحويل...`)
            .setColor(config.color || '#051678')
            .setImage(config.line || null)

        .setFooter({ text: 'تأكد من تحويل المبلغ المطلوب' });
    
    const processingMsg = await m.channel.send({ 
        content: `<@${m.author.id}>`,
        embeds: [embed]
    });
    
    const filter = ({ content, author: { id } }) => {
        return (
            content.startsWith(`**:moneybag: | ${m.author.username}, has transferred `) &&
            content.includes(`${transferBank}`) &&
            id === "282859044593598464" &&
            (Number(content.slice(content.lastIndexOf("`") - String(tax).length, content.lastIndexOf("`"))) >= price)
        );
    };
    
    const collector = m.channel.createMessageCollector({ 
        filter, 
        max: 1, 
        time: 60000 
    });
    
    let paymentReceived = false;
    
    collector.on('collect', async (collected) => {
        paymentReceived = true;
        
        try {
            await db.set(`autopost_${conv.shopId}`, {
                message: message,
                mention: mentionType,
                interval: interval,
                maxMentions: maxMentions,
                usedMentions: 0,
                remainingMentions: maxMentions,
                imageUrl: imageUrl,
                active: true,
                owner: m.author.id,
                lastPosted: Date.now(),
                nextPost: Date.now() + (interval * 60000)
            });
            
            const successEmbed = new EmbedBuilder()
                .setTitle('✅ تم تفعيل النشر التلقائي بنجاح')
                    .setImage(config.line || null)

                .setDescription(`**التفاصيل:**\n• الفترة: كل ${safeIntervalText(interval)}\n• المنشن: ${mentionType}\n• عدد المنشنات: ${maxMentions}\n• المبلغ المدفوع: \`${tax}\``)
            .setColor(config.color || '#051678')
                .setTimestamp();
            
            await processingMsg.edit({ 
                content: `<@${m.author.id}>`,
                embeds: [successEmbed] 
            });
            
        } catch (error) {
            console.error('خطأ في تفعيل النشر التلقائي:', error);
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **حدث خطأ أثناء تفعيل النشر التلقائي**`
            });
        }
        
        endConversation(m.author.id);
    });
    
    collector.on('end', async (collected, reason) => {
        if (!paymentReceived && reason === 'time') {
            const timeoutEmbed = new EmbedBuilder()
                .setTitle('❌ انتهى الوقت')
                .setDescription('لم يتم استلام التحويل خلال الوقت المحدد')
                .setColor('#ff0000')
                .setTimestamp();
            
            await processingMsg.edit({ 
                content: `<@${m.author.id}>`,
                embeds: [timeoutEmbed] 
            });
            
            endConversation(m.author.id);
        }
    });
}

async function handleAddPartnerChat(m, conv) {
    if (conv.step === 1) {
        const partnerId = m.content.trim();
        
        if (!/^\d+$/.test(partnerId)) {
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **الرجاء إدخال أيـدي مستخدم صحيح**`
            });
            return;
        }
        
        const partnerMember = m.guild.members.cache.get(partnerId);
        if (!partnerMember) {
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **المستخدم غير موجود في السيرفر**`
            });
            return;
        }
        
        const shopData = await db.get(`shop_${conv.shopId}`);
        const existingPartners = shopData.partners || [];
        if (existingPartners.includes(partnerId)) {
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **هذا المستخدم شريك بالفعل في المتجر**`
            });
            return;
        }
        
        conv.data.partnerId = partnerId;
        conv.step = 2;
        activeConversations.set(m.author.id, conv);
        
        const price = 3000;
        const tax = Math.floor(price * (20 / 19) + 1);
        
        conv.data.price = price;
        conv.data.tax = tax;
        
        const embed = new EmbedBuilder()
            .setTitle('تأكيد إضافة شريك')
            .setDescription(`**التفاصيل:**\n• الشريك: <@${partnerId}>\n• السعر: \`${price}\`\n• بعد الضريبة: \`${tax}\`\n\n**للتأكيد اكتب:** \`تأكيد\`\n**للإلغاء اكتب:** \`إلغاء\``)
            .setColor(config.color || '#051678')
                .setImage(config.line || null)

            .setFooter({ text: 'سيتم إرسال طلب الدفع بعد التأكيد' });
        
        await m.channel.send({ 
            content: `<@${m.author.id}>`,
            embeds: [embed]
        });
        
    } else if (conv.step === 2) {
        if (m.content.toLowerCase() === 'تأكيد') {
            await processAddPartner(m, conv);
        } 
    }
}

