// في دالة handleMessages أو في event messageCreate
// أضف هذا الكود لمعالجة رد المستخدم في الخاص
client.on('messageCreate', async (m) => {
    if (!m.guild || m.author.bot) return;
    
    await handleMessages(m);
});
async function handleMessages(m) {
    if (!m.guild) return;
    if (m.author.bot) return;
    
    const conv = activeConversations.get(m.author.id);
    if (!conv) {
        if (m.content === 'منشن' || m.content === 'منشنات') {
            await handleOriginalMentionCommand(m);
        }
        return;
    }
    
    try {
        await m.delete().catch(() => {});
        
        // التحقق من الإلغاء
        if (m.content.toLowerCase() === 'الغاء' || 
            m.content.toLowerCase() === 'إلغاء' || 
            m.content.toLowerCase() === 'cancel') {
            
            await m.channel.send({ 
                content: `<@${m.author.id}> ❌ **تم إلغاء العملية.**`
            }).catch(() => {});
            endConversation(m.author.id);
            return;
        }
        
        switch(conv.action) {
            case 'buy_mentions':
                await handleBuyMentionsChat(m, conv);
                break;
            case 'remove_warns':
                await handleRemoveWarnsChat(m, conv);
                break;
            case 'transfer_shop':
                await handleTransferShopChat(m, conv);
                break;
            case 'rename_shop':
                await handleRenameShopChat(m, conv);
                break;
            case 'change_type':
                await handleChangeTypeChat(m, conv);
                break;
            case 'change_prefix':
                await handleChangePrefixChat(m, conv);
                break;
            case 'autopost':
                await handleAutopostChat(m, conv);
                break;
            case 'add_partner':
                await handleAddPartnerChat(m, conv);
                break;
            case 'remove_partner':
                await handleRemovePartnerChat(m, conv);
                break;
            case 'tashfeer':
                // التشفير يتم عبر الـ modal - هذه الحالة لم تعد مستخدمة
                await m.channel.send({ content: `<@${m.author.id}> ❌ **الرجاء استخدام زر التشفير من القائمة**` });
                endConversation(m.author.id);
                break;
            default:
            case 'premium_monthly_serverid':
                await handlePremiumMonthlyServerIdChat(m, conv);
                break;
            case 'premium_lifetime_token':
                await handlePremiumLifetimeTokenChat(m, conv);
                break;
                await m.channel.send({ 
                    content: `<@${m.author.id}> ❌ **عملية غير معروفة**`
                });
                endConversation(m.author.id);
        }
    } catch (error) {
        console.error('خطأ في المحادثة:', error);
        await m.channel.send({ 
            content: `<@${m.author.id}> ❌ **حدث خطأ. الرجاء المحاولة مرة أخرى.**`
        }).catch(() => {});
        endConversation(m.author.id);
    }
}


async function handleOriginalMentionCommand(m) {
    const shopData = await db.get(`shop_${m.channel.id}`);
    const gConfig = await getGuildConfig(m.guild.id);

    if (!shopData) {
        const replyMessage = await m.reply({ content: `❌ **هذا الروم ليس مسجل كمتجر**` });
        setTimeout(() => {
            m.delete().catch(() => {});
            replyMessage.delete().catch(() => {});
        }, 5000);
        return;
    }

    const { owner, role, every = 0, here = 0, shop = 0, warns = 0, date, status } = shopData;
    const everyMentions = shopData.everyoneMentions ?? shopData.everyMentions ?? every;
    const hereMentions = shopData.hereMentions ?? here;
    const shopMentions = shopData.shopRoleMentions ?? shop;
    const statusText = status === "active" || status === "1" ? "مـفـعـل" : "مـعـطـل";
    const lineImg = gConfig.Line || gConfig.line;

    const selectMenu = new StringSelectMenuBuilder()
        .setCustomId('shop_main_menu')
        .setPlaceholder('اختر الخدمة التي تريدها')
        .addOptions([
            {
                label: 'تـنـظـيـم الـمـتـاجـر',
                description: 'فتح قائمة تنظيم المتاجر',
                value: 'tm',
                emoji: '<:091:1458810431589318682>'
            },
            {
                label: 'تـحـديـث',
                description: 'تحديث قـائـمة الـتـنـظـيـم ',
                value: 'refresh',
                emoji: '<a:by_noobot:1459220555591974988>'
            },
            {
                label: 'تشفير',
                description: 'خدمات التشفير',
                value: 'tashfeerk',
                emoji: '🔒'
            }
        ]);

    const row7 = new ActionRowBuilder().addComponents(selectMenu);

    // الإيموجيات المخصصة
    const everyoneEmoji = '<a:011_1367454588252454943:1459220561556144354>';
    const hereEmoji = '<a:003_1367454575254044763:1459220563439648894>';
    const shopEmoji = '<a:009:1458810231545921692>';

    const embedMessage = new EmbedBuilder()
        .setAuthor({ name: m.guild.name, iconURL: m.guild.iconURL() })
        .setFooter({ text: 'dev by : bh.x7 & _wx10', iconURL: m.guild.iconURL() })
        .setThumbnail(m.guild.iconURL())
        .setTitle(`الـمـنـشـنـات`)
        .setDescription(`**${everyoneEmoji}  \`-\` everyone : ${everyMentions}\n${hereEmoji} \`-\` here : ${hereMentions}\n${shopEmoji} \`-\` shop : ${shopMentions}**`)
        .setTimestamp()
        .setColor(gConfig.color || '#051678');
    
    // إضافة الخط الفاصل إذا موجود
    if (lineImg) embedMessage.setImage(lineImg);

    await m.reply({ embeds: [embedMessage], components: [row7] });
}

