// معالج زر تأكيد الإلغاء من الأمر
client.on("interactionCreate", async i => {
    if (!i.isButton()) return;
    
    if (i.customId.startsWith("confirmcancelcmd_")) {
        try {
            await i.deferUpdate();
            const shopId = i.customId.replace("confirmcancelcmd_", "");
            
            const shopData = await db.get(`shop_${shopId}`);
            if (!shopData || (shopData.owner !== i.user.id && !shopData.partners?.includes(i.user.id))) {
                await i.editReply({ content: "❌ ليس لديك صلاحية للإلغاء", components: [] });
                return;
            }
            
            // إلغاء النشر التلقائي
            await db.delete(`autopost_${shopId}`);
            
            await i.editReply({
                content: "✅ **تم إلغاء النشر التلقائي بنجاح**",
                components: [],
                embeds: []
            });
            
            // إرسال تأكيد إضافي
            await i.channel.send({
                embeds: [
                    new EmbedBuilder()
                        .setTitle("✅ تم إلغاء النشر التلقائي")
                        .setDescription(`تم إلغاء النشر التلقائي للمتجر <#${shopId}>`)
                        .setColor("#00FF00")
                        .setTimestamp()
                ]
            });
            
        } catch (error) {
            console.error('Error confirming cancel command:', error);
            await i.editReply({ content: "❌ حدث خطأ أثناء إلغاء النشر", components: [] });
        }
    }
    
    if (i.customId === "cancelcmd") {
        await i.deferUpdate();
        await i.editReply({
            content: "✅ تـم إلـغـاء عـمـلـيـة الإلـغـاء",
            components: [],
            embeds: []
        });
    }
});


// ======================= نظام حذف بيانات مستخدم حسب هيكلك =======================

// دالة لحذف جميع بيانات مستخدم معين (حسب هيكل الداتا الخاص بك)
async function deleteUserDataByStructure(userId, reason = "لم يذكر سبب") {
    try {
        console.log(`🔄 بدأ حذف بيانات المستخدم: ${userId}`);
        
        const keysToDelete = [
            // المتاجر والرصيد
            `shop_credit_${userId}`,
            `auction_credit_${userId}`,
            `order_credit_${userId}`,
            
            // التذاكر
            `buy_shop_ticket_${userId}`,
            `Support_ticket_${userId}`,
            `scam_ticket_${userId}`,
            `auction_ticket_${userId}`,
            `order_ticket_${userId}`,
            
            // بيانات متجرية إضافية
            `shop_owner_${userId}`,
            `shop_member_${userId}`,
            `shop_warnings_${userId}`,
            `shop_banned_${userId}`,
            
            // بيانات المزاد
            `auction_bid_${userId}`,
            `auction_winner_${userId}`,
            
            // بيانات الطلبات
            `order_history_${userId}`,
            `order_active_${userId}`,
            
            // بيانات الدعم
            `support_messages_${userId}`,
            `support_history_${userId}`,
            
            // بيانات عامة
            `user_balance_${userId}`,
            `user_settings_${userId}`,
            `user_stats_${userId}`,
            `user_violations_${userId}`
        ];
        
        let deletedCount = 0;
        let deletedItems = [];
        
        // 1. حذف المفاتيح المحددة
        for (const key of keysToDelete) {
            try {
                const exists = await db.get(key);
                if (exists !== null) {
                    await db.delete(key);
                    deletedCount++;
                    deletedItems.push({
                        key: key,
                        type: getKeyType(key),
                        name: key.split('_').slice(0, -1).join('_')
                    });
                    console.log(`🗑️ تم حذف: ${key}`);
                }
            } catch (error) {
                console.error(`❌ خطأ في حذف ${key}:`, error.message);
            }
        }
        
        // 2. البحث عن المتاجر التي يملكها المستخدم
        const allKeys = await db.all();
        const shopKeys = allKeys.filter(entry => entry.id.startsWith('shop_'));
        
        for (const entry of shopKeys) {
            try {
                const shopData = entry.value;
                if (shopData && typeof shopData === 'object') {
                    let shouldDeleteShop = false;
                    
                    // التحقق إذا كان المستخدم هو المالك
                    if (shopData.owner === userId || 
                        shopData.ownerId === userId ||
                        (shopData.user && shopData.user.id === userId)) {
                        shouldDeleteShop = true;
                    }
                    
                    // إذا كان المستخدم مالك المتجر، احذف المتجر كاملاً
                    if (shouldDeleteShop) {
                        await db.delete(entry.id);
                        deletedCount++;
                        deletedItems.push({
                            key: entry.id,
                            type: 'متجر كامل',
                            name: shopData.name || entry.id
                        });
                        console.log(`🏪 تم حذف متجر: ${entry.id}`);
                        
                        // حذف بيانات المتجر الإضافية
                        const shopExtraKeys = [
                            `${entry.id}_members`,
                            `${entry.id}_partners`,
                            `${entry.id}_settings`,
                            `${entry.id}_history`
                        ];
                        
                        for (const extraKey of shopExtraKeys) {
                            try {
                                await db.delete(extraKey);
                                deletedCount++;
                                console.log(`🗑️ تم حذف بيانات إضافية: ${extraKey}`);
                            } catch (err) {
                                // تجاهل إذا المفتاح غير موجود
                            }
                        }
                    }
                }
            } catch (error) {
                console.error(`❌ خطأ في معالجة المتجر ${entry.id}:`, error.message);
            }
        }
        
        // 3. البحث عن تذاكر المستخدم
        const ticketPatterns = [
            'ticket_',
            '_ticket_',
            '_complaint_',
            '_report_'
        ];
        
        for (const entry of allKeys) {
            try {
                const key = entry.id;
                const value = entry.value;
                
                // تحقق إذا كان المفتاح تذكرة وتحتوي على معرف المستخدم
                const isTicket = ticketPatterns.some(pattern => key.includes(pattern));
                if (isTicket && value && typeof value === 'object') {
                    if (value.userId === userId || 
                        value.user === userId || 
                        value.creator === userId ||
                        (value.creator && value.creator.id === userId)) {
                        
                        await db.delete(key);
                        deletedCount++;
                        deletedItems.push({
                            key: key,
                            type: 'تذكرة',
                            name: value.title || value.type || key
                        });
                        console.log(`🎫 تم حذف تذكرة: ${key}`);
                    }
                }
            } catch (error) {
                console.error(`❌ خطأ في معالجة التذكرة:`, error.message);
            }
        }
        
        return {
            success: true,
            deletedCount: deletedCount,
            deletedItems: deletedItems,
            userId: userId
        };
        
    } catch (error) {
        console.error('❌ خطأ في حذف بيانات المستخدم:', error);
        return {
            success: false,
            error: error.message,
            deletedCount: 0,
            userId: userId
        };
    }
}

// دالة لتصنيف المفاتيح
function getKeyType(key) {
    
    if (key.includes('ticket_')) return 'تذكرة';
    if (key.startsWith('shop_')) {
        if (key.includes('owner_')) return 'ملكية متجر';
        if (key.includes('member_')) return 'عضوية متجر';
        if (key.includes('warnings_')) return 'تحذيرات';
        return 'متجر';
    }
    if (key.includes('auction_')) return 'مزاد';
    if (key.includes('order_')) return 'طلب';
    if (key.includes('support_')) return 'دعم';
    if (key.includes('user_')) return 'بيانات مستخدم';
    return 'بيانات أخرى';
}

// ======================= أمر حذف بيانات مستخدم =======================
client.on('messageCreate', async message => {
    if (message.content.startsWith('حذف-مستخدم')) {
        const ownerId = "959174041422397471";
        
        // التحقق من صلاحيات المطور
        if (message.author.id !== ownerId) {
            await message.reply({ content: "❌ هذا الأمر مخصص للمطور فقط", flags: 64 });
            return;
        }
        
        try {
            // تحليل الأمر
            const args = message.content.split(' ');
            if (args.length < 2) {
                await message.reply("❌ صيغة الأمر غير صحيحة\n**استخدم:** `حذف-مستخدم @المستخدم السبب`");
                return;
            }
            
            // استخراج معرف المستخدم
            let targetUserId;
            if (args[1].startsWith('<@') && args[1].endsWith('>')) {
                targetUserId = args[1].replace(/[<@!>]/g, '');
            } else { // exactMatch is true - strict equality
                targetUserId = args[1];
            }
            
            // استخراج السبب
            const reason = args.slice(2).join(' ') || "لم يذكر سبب";
            
            // التحقق من صحة الـ User ID
            if (!/^\d+$/.test(targetUserId)) {
                await message.reply("❌ معرف المستخدم غير صحيح");
                return;
            }
            
            // حذف الرسالة الأصلية
            try { await message.delete(); } catch {}
            
            // إرسال رسالة التحميل
            const loadingMsg = await message.channel.send(`🔄 جاري حذف جميع بيانات المستخدم <@${targetUserId}>...`);
            
            // البحث عن المستخدم في Discord
            let targetUser;
            try {
                targetUser = await client.users.fetch(targetUserId);
            } catch {
                targetUser = { tag: "مستخدم غير معروف", id: targetUserId };
            }
            
            // تنفيذ الحذف حسب هيكل الداتا
            const result = await deleteUserDataByStructure(targetUserId, reason);
            
            if (result.success) {
                // إنشاء تقرير الحذف
                const embed = new EmbedBuilder()
                    .setTitle("🗑️ تم حذف بيانات المستخدم")
                    .setDescription(`**تم حذف جميع بيانات المستخدم من النظام**`)
                    .setColor("#FF0000")
                    .addFields(
                        { name: "👤 المستخدم", value: `<@${targetUserId}> (${targetUser.tag})`, inline: true },
                        { name: "📊 البيانات المحذوفة", value: `${result.deletedCount} سجل`, inline: true },
                        { name: "📝 السبب", value: reason, inline: true },
                        { name: "👤 المسؤول", value: message.author.tag, inline: true },
                        { name: "🕒 الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
                    )
                    .setFooter({ text: `تم الحذف بواسطة ${message.author.tag}` })
                    .setTimestamp();
                
                // إضافة تفاصيل البيانات المحذوفة
                if (result.deletedItems.length > 0) {
                    const dataTypes = {};
                    result.deletedItems.forEach(item => {
                        dataTypes[item.type] = (dataTypes[item.type] || 0) + 1;
                    });
                    
                    const typeDetails = Object.entries(dataTypes)
                        .map(([type, count]) => `• **${type}:** ${count} سجل`)
                        .join('\n');
                    
                    embed.addFields({ 
                        name: "📋 أنواع البيانات المحذوفة", 
                        value: typeDetails, 
                        inline: false 
                    });
                    
                    // إضافة أمثلة من البيانات المحذوفة
                    if (result.deletedItems.length <= 8) {
                        const examples = result.deletedItems.slice(0, 8)
                            .map(item => `• ${item.type}: \`${item.name}\``)
                            .join('\n');
                        
                        embed.addFields({ 
                            name: "📝 أمثلة من البيانات المحذوفة", 
                            value: examples, 
                            inline: false 
                        });
                    }
                }
                
                await loadingMsg.edit({ content: "", embeds: [embed] });
                
                // إرسال رسالة للمستخدم المحذوفة بياناته
                try {
                    const userEmbed = new EmbedBuilder()
                        .setTitle("⚠️ حذف بياناتك")
                        .setDescription(`**تم حذف جميع بياناتك من نظام المتاجر**`)
                        .setColor("#FF0000")
                        .addFields(
                            { name: "📊 البيانات المحذوفة", value: `${result.deletedCount} سجل`, inline: true },
                            { name: "📝 السبب", value: reason, inline: true },
                            { name: "👤 المسؤول", value: message.author.tag, inline: true },
                            { name: "🕒 الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
                        )
                        .setFooter({ text: "نظام إدارة المتاجر" })
                        .setTimestamp();
                    
                    await targetUser.send({ embeds: [userEmbed] });
                } catch (dmError) {
                    console.log(`⚠️ لم أتمكن من إرسال رسالة للمستخدم ${targetUser.tag}`);
                }
                
                console.log(`✅ تم حذف ${result.deletedCount} بيانات للمستخدم ${targetUser.tag}`);
                
            } else { // exactMatch is true - strict equality
                await loadingMsg.edit(`❌ فشل حذف البيانات: ${result.error}`);
            }
            
        } catch (error) {
            console.error('❌ خطأ في أمر حذف المستخدم:', error);
            await message.channel.send(`❌ حدث خطأ: ${error.message}`);
        }
    }
});

