// ======================= أمر البحث عن بيانات مستخدم =======================
client.on('messageCreate', async message => {
    if (message.content.startsWith('عرض')) {
        
        try {
            const args = message.content.split(' ');
            if (args.length < 2) {
                await message.reply("❌ صيغة الأمر غير صحيحة\n**استخدم:** `عر- @المستخدم`");
                return;
            }
            
            // استخراج معرف المستخدم
            let targetUserId = args[1].replace(/[<@!>]/g, '');
            
            // التحقق من صحة الـ User ID
            if (!/^\d+$/.test(targetUserId)) {
                await message.reply("❌ معرف المستخدم غير صحيح");
                return;
            }
            
            // إرسال رسالة التحميل
            const loadingMsg = await message.channel.send(`🔍 جاري البحث عن بيانات المستخدم <@${targetUserId}>...`);
            
            const allKeys = await db.all();
            const userData = [];
            
            // البحث عن جميع بيانات المستخدم
            for (const entry of allKeys) {
                const key = entry.id;
                
                // تحقق إذا كان المفتاح يحتوي على معرف المستخدم
                if (key.includes(targetUserId)) {
                    userData.push({
                        key: key,
                        type: getKeyType(key),
                        exists: true
                    });
                }
                
                // تحقق في قيمة الـ JSON
                else if (entry.value && typeof entry.value === 'object') {
                    const value = entry.value;
                    let foundInValue = false;
                    
                    if (value.owner === targetUserId || 
                        value.ownerId === targetUserId || 
                        value.userId === targetUserId ||
                        value.user === targetUserId ||
                        value.creatorId === targetUserId) {
                        foundInValue = true;
                    }
                    
                    // تحقق في المصفوفات
                    if (value.partners && Array.isArray(value.partners)) {
                        const hasPartner = value.partners.some(p => 
                            p.id === targetUserId || 
                            p.userId === targetUserId || 
                            p === targetUserId
                        );
                        if (hasPartner) foundInValue = true;
                    }
                    
                    if (value.members && Array.isArray(value.members)) {
                        const hasMember = value.members.some(m => 
                            m.id === targetUserId || 
                            m.userId === targetUserId || 
                            m === targetUserId
                        );
                        if (hasMember) foundInValue = true;
                    }
                    
                    if (foundInValue) {
                        userData.push({
                            key: key,
                            type: getKeyType(key),
                            exists: true,
                            inValue: true
                        });
                    }
                }
            }
            
            if (userData.length === 0) {
                await loadingMsg.edit(`📭 **لا توجد بيانات للمستخدم <@${targetUserId}>**`);
                return;
            }
            
            // تجميع البيانات حسب النوع
            const dataByType = {};
            userData.forEach(item => {
                if (!dataByType[item.type]) {
                    dataByType[item.type] = [];
                }
                dataByType[item.type].push(item.key);
            });
            
            // إنشاء Embed لعرض البيانات
            const embed = new EmbedBuilder()
                .setTitle(`📊 بيانات المستخدم: <@${targetUserId}>`)
                .setDescription(`**تم العثور على ${userData.length} سجل**`)
                .setColor("#3498db")
                .setFooter({ text: `طلب من قبل: ${message.author.tag}` })
                .setTimestamp();
            
            // إضافة البيانات حسب النوع
            Object.entries(dataByType).forEach(([type, keys]) => {
                const count = keys.length;
                const examples = keys.slice(0, 3).map(k => `\`${k}\``).join(', ');
                const more = count > 3 ? ` + ${count - 3} أخرى` : '';
                
                embed.addFields({
                    name: `${type} (${count})`,
                    value: `${examples}${more}`,
                    inline: false
                });
            });
            
            // إضافة أزرار للتحكم
            const row = new ActionRowBuilder()
                .addComponents(
                    new ButtonBuilder()
                        .setCustomId(`delete_user_${targetUserId}`)
                        .setLabel('🗑️ حذف جميع البيانات')
                        .setStyle(ButtonStyle.Danger),
                    new ButtonBuilder()
                        .setCustomId(`fix_user_${targetUserId}`)
                        .setLabel('🔧 إصلاح المشاكل')
                        .setStyle(ButtonStyle.Primary),
                    new ButtonBuilder()
                        .setCustomId(`cancel_${Date.now()}`)
                        .setLabel('❌ إلغاء')
                        .setStyle(ButtonStyle.Secondary)
                );
            
            await loadingMsg.edit({ 
                content: "", 
                embeds: [embed], 
                components: [row] 
            });
            
        } catch (error) {
            console.error('❌ خطأ في أمر عرض البيانات:', error);
            await message.channel.send(`❌ حدث خطأ: ${error.message}`);
        }
    }
});

// ======================= معالجة الأزرار =======================
client.on('interactionCreate', async interaction => {
    if (!interaction.isButton()) return;
    
    
    const customId = interaction.customId;
    
    // زر حذف جميع البيانات
    if (customId.startsWith('delete_user_')) {
        const userId = customId.replace('delete_user_', '');
        
        await interaction.deferUpdate();
        
        const result = await deleteUserDataByStructure(userId, "حذف بواسطة زر");
        
        if (result.success) {
            await interaction.editReply({
                content: `✅ تم حذف ${result.deletedCount} بيانات للمستخدم <@${userId}>`,
                embeds: [],
                components: []
            });
        } else { // exactMatch is true - strict equality
            await interaction.editReply({
                content: `❌ فشل الحذف: ${result.error}`,
                embeds: [],
                components: []
            });
        }
    }
    
    // زر إصلاح المشاكل
    else if (customId.startsWith('fix_user_')) {
        const userId = customId.replace('fix_user_', '');
        
        await interaction.deferUpdate();
        
        const keysToFix = [
            `shop_credit_${userId}`,
            `buy_shop_ticket_${userId}`,
            `Support_ticket_${userId}`,
            `scam_ticket_${userId}`,
            `auction_credit_${userId}`,
            `auction_ticket_${userId}`,
            `order_credit_${userId}`,
            `order_ticket_${userId}`
        ];
        
        let fixedCount = 0;
        for (const key of keysToFix) {
            try {
                await db.delete(key);
                fixedCount++;
            } catch (error) {
                // تجاهل
            }
        }
        
        await interaction.editReply({
            content: `🔧 تم إصلاح ${fixedCount} مشكلة للمستخدم <@${userId}>`,
            embeds: [],
            components: []
        });
    }
});

