// دالة للانضمام التلقائي إلى القناة الصوتية
function joinVoiceAutomatically(client) {
  const guildId = '1455986892645601342'; // ضع هنا معرف (ID) السيرفر الخاص بك
  const voiceChannelId = '1455994984615645194'; // ضع هنا معرف (ID) القناة الصوتية

  const guild = client.guilds.cache.get(guildId);
  if (!guild) {
    console.error('لم يتم العثور على السيرفر!');
    return null;
  }

  const voiceChannel = guild.channels.cache.get(voiceChannelId);
  if (!voiceChannel) {
    console.error('لم يتم العثور على القناة الصوتية!');
    return null;
  }

  try {
    // انضمام البوت إلى القناة الصوتية
    const connection = joinVoiceChannel({
      channelId: voiceChannelId,
      guildId: guildId,
      adapterCreator: guild.voiceAdapterCreator,
    });
    
    console.log(`تم الانضمام إلى القناة الصوتية: ${voiceChannel.name}`);
    return connection;
    
  } catch (err) {
    console.error('حدث خطأ أثناء الانضمام إلى القناة الصوتية:', err);
    return null;
  }
}

