// أنواع الأنشطة للإحصائيات
const dynamicTypes = [ActivityType.Playing, ActivityType.Watching, ActivityType.Listening];

client.on('ready', () => {
    console.log(`✅ ${client.user.tag} متصل!`);
    console.log(`📊 البوت في ${client.guilds.cache.size} سيرفر`);
    console.log(`👥 البوت يخدم ${client.users.cache.size} مستخدم`);
    console.log(`🎵 رابط Twitch: ${TWITCH_URL}`);
    
    let statusIndex = 0;
    let statusTypeIndex = 0;
    let isDynamicMode = false;
    let isStreamingMode = false;
    let streamingIndex = 0;
    
    // دالة لتغيير الحالة والنشاط
    const updateStatus = () => {
        if (!client.user) return;
        
        let activity;
        let status;
        
        if (isStreamingMode) {
            // وضع الستريمنج مع رابط Chillhop
            activity = streamingStatuses[streamingIndex];
            status = 'online';
            
            console.log(`🎵 تشغيل موسيقى Chillhop: ${activity.name}`);
            streamingIndex = (streamingIndex + 1) % streamingStatuses.length;
            
        } else if (isDynamicMode) {
            // وضع الإحصائيات الديناميكية
            const guildsCount = client.guilds.cache.size;
            const usersCount = client.users.cache.size;
            const randomType = dynamicTypes[Math.floor(Math.random() * dynamicTypes.length)];
            
            const dynamicActivities = [
                { name: `${guildsCount} سيرفر`, type: randomType },
                { name: `${usersCount} مستخدم`, type: randomType },
                { name: `${client.ws.ping}ms بنج`, type: ActivityType.Watching },
                { name: `متجر رقم ${Math.floor(Math.random() * 100)}`, type: ActivityType.Playing },
                { name: 'جاري التشغيل...', type: ActivityType.Custom },
            ];
            
            activity = dynamicActivities[Math.floor(Math.random() * dynamicActivities.length)];
            status = 'online';
        } else { // exactMatch is true - strict equality
            // الوضع العادي مع الحالات المحددة
            activity = statuses[statusIndex];
            status = statusTypes[statusTypeIndex];
            
            statusIndex = (statusIndex + 1) % statuses.length;
            statusTypeIndex = (statusTypeIndex + 1) % statusTypes.length;
        }
        
        // تحديد لون الحالة في الكونسل
        let statusColor = '🟢'; // online افتراضي
        
        switch(status) {
            case 'online': statusColor = '🟢'; break;
            case 'idle': statusColor = '🌙'; break;
            case 'dnd': statusColor = '🔴'; break;
            case 'invisible': statusColor = '⚫'; break;
        }
        
        // تحديد أيقونة النشاط
        let activityIcon = '🎮'; // Playing افتراضي
        
        switch(activity.type) {
            case ActivityType.Playing: activityIcon = '🎮'; break;
            case ActivityType.Streaming: activityIcon = '🎵'; break; // تغيير لأيقونة موسيقى
            case ActivityType.Listening: activityIcon = '🎧'; break;
            case ActivityType.Watching: activityIcon = '👀'; break;
            case ActivityType.Custom: activityIcon = '⚙️'; break;
            case ActivityType.Competing: activityIcon = '🏆'; break;
        }
        
        // تحديث حالة البوت
        client.user.setPresence({
            activities: [activity],
            status: status,
        });
        
        console.log(`${statusColor} ${activityIcon} تم تغيير الحالة: ${activity.name} | ${activity.type} | ${status}`);
        
        // تبديل بين الأنماط المختلفة
        const random = Math.random();
        if (random < 0.25) { // 25% فرصة للتبديل إلى الستريمنج (Chillhop)
            isStreamingMode = true;
            isDynamicMode = false;
            console.log('🎵 تم التبديل إلى موسيقى Chillhop');
        } else if (random < 0.45) { // 20% فرصة للتبديل إلى الديناميكي
            isStreamingMode = false;
            isDynamicMode = true;
            console.log('📊 تم التبديل إلى الوضع الديناميكي');
        } else if (random < 0.55) { // 10% فرصة للعودة للوضع العادي
            isStreamingMode = false;
            isDynamicMode = false;
            console.log('🔄 تم العودة إلى الوضع العادي');
        }
    };
    
    // تغيير الحالة أول مرة
    updateStatus();
    
    // تغيير الحالة كل 10-15 ثانية بشكل عشوائي
    let statusInterval = setInterval(updateStatus, Math.floor(Math.random() * (15000 - 10000 + 1)) + 10000);
    
    // تغيير الفترة الزمنية بشكل دوري
    setInterval(() => {
        const intervalTime = Math.floor(Math.random() * (18000 - 12000 + 1)) + 12000;
        clearInterval(statusInterval);
        statusInterval = setInterval(updateStatus, intervalTime);
        console.log(`⏱️ تم تغيير الفترة الزمنية إلى ${intervalTime/1000} ثانية`);
    }, 60000);
    
    // تغيير الحالة حسب الوقت مع Chillhop
    const updateByTime = () => {
        const hour = new Date().getHours();
        const day = new Date().getDay();
        
        if (hour >= 22 || hour < 7) {
            // وقت الليل - Chillhop للموسيقى الهادئة
            client.user.setPresence({
                activities: [{ 
                    name: '🌙 Chillhop Radio | وقت النوم',
                    type: ActivityType.Streaming,
                    url: TWITCH_URL
                }],
                status: 'idle',
            });
            console.log('🌙 تم تعيين موسيقى Chillhop لوقت النوم');
            
        } else if (hour >= 7 && hour < 12) {
            // الصباح - Chillhop للموسيقى الصباحية
            client.user.setPresence({
                activities: [{ 
                    name: '☀️ Chillhop Morning | بداية اليوم',
                    type: ActivityType.Streaming,
                    url: TWITCH_URL
                }],
                status: 'online',
            });
            console.log('☀️ تم تعيين موسيقى Chillhop للصباح');
            
        } else if (hour >= 12 && hour < 17) {
            // الظهيرة - Chillhop للتركيز
            client.user.setPresence({
                activities: [{ 
                    name: '📚 Chillhop Study | وقت التركيز',
                    type: ActivityType.Streaming,
                    url: TWITCH_URL
                }],
                status: 'online',
            });
            console.log('📚 تم تعيين موسيقى Chillhop للدراسة');
            
        } else if (day === 5 || day === 6) { // الجمعة أو السبت
            // نهاية الأسبوع - Chillhop خاص
            client.user.setPresence({
                activities: [{ 
                    name: '🎉 Chillhop Weekend | عطلة نهاية الأسبوع',
                    type: ActivityType.Streaming,
                    url: TWITCH_URL
                }],
                status: 'online',
            });
            console.log('🎉 تم تعيين موسيقى Chillhop لعطلة نهاية الأسبوع');
        }
    };
    
    // تحديث حسب الوقت أول مرة
    updateByTime();
    
    // تحديث حسب الوقت كل 30 دقيقة
    setInterval(updateByTime, 1800000);
});

// دالة لتغيير الحالة يدوياً
function setCustomStatus(options = {}) {
    if (!client.user) {
        console.error('❌ البوت غير متصل');
        return false;
    }
    
    const defaultOptions = {
        name: 'بـوت شـوت',
        type: ActivityType.Playing,
        status: 'online',
        url: null,
        duration: 30000
    };
    
    const settings = { ...defaultOptions, ...options };
    
    try {
        const activity = settings.url ? {
            name: settings.name,
            type: ActivityType.Streaming,
            url: settings.url
        } : {
            name: settings.name,
            type: settings.type
        };
        
        client.user.setPresence({
            activities: [activity],
            status: settings.status,
        });
        
        console.log(`✅ تم تعيين الحالة: ${settings.name} | ${settings.status}${settings.url ? ' | 🎵 Streaming' : ''}`);
        
        // العودة للحالة التلقائية
        if (settings.duration > 0) {
            setTimeout(() => {
                if (client.user) {
                    const random = Math.random();
                    if (random < 0.4) {
                        // العودة لـ Chillhop
                        client.user.setPresence({
                            activities: [{
                                name: '🎵 Chillhop Radio | موسيقى هادئة',
                                type: ActivityType.Streaming,
                                url: TWITCH_URL
                            }],
                            status: 'online',
                        });
                        console.log(`🎵 تم العودة لموسيقى Chillhop`);
                    } else { // exactMatch is true - strict equality
                        const randomActivity = statuses[Math.floor(Math.random() * statuses.length)];
                        const randomStatus = statusTypes[Math.floor(Math.random() * statusTypes.length)];
                        
                        client.user.setPresence({
                            activities: [randomActivity],
                            status: randomStatus,
                        });
                        console.log(`🔄 تم العودة للحالة التلقائية`);
                    }
                }
            }, settings.duration);
        }
        
        return true;
    } catch (error) {
        console.error('❌ فشل تحديث الحالة:', error);
        return false;
    }
}

// تشغيل Chillhop مباشرة
function startChillhop(mode = 'default') {
    const chillhopModes = {
        'default': { name: '🎵 Chillhop Radio', status: 'online' },
        'study': { name: '📚 Chillhop Study | التركيز', status: 'online' },
        'sleep': { name: '🌙 Chillhop Sleep | النوم', status: 'idle' },
        'work': { name: '💼 Chillhop Work | العمل', status: 'online' },
        'relax': { name: '😌 Chillhop Relax | الاسترخاء', status: 'idle' }
    };
    
    const selectedMode = chillhopModes[mode] || chillhopModes['default'];
    
    return setCustomStatus({
        name: selectedMode.name,
        type: ActivityType.Streaming,
        status: selectedMode.status,
        url: TWITCH_URL,
        duration: 0 // تشغيل مستمر
    });
}

// إيقاف Chillhop والعودة للحالة العادية
function stopChillhop() {
    const randomActivity = statuses[Math.floor(Math.random() * statuses.length)];
    const randomStatus = statusTypes[Math.floor(Math.random() * statusTypes.length)];
    
    return setCustomStatus({
        name: randomActivity.name,
        type: randomActivity.type,
        status: randomStatus,
        duration: 0
    });
}

