// ======================= أوامر إدارة البوت (بدون سلاش) =======================

// مستمع لرسائل أوامر البوت
client.on("messageCreate", async message => {
    if (message.author.bot) return;
    
    const content = message.content.trim().toLowerCase();
    
    // 1. أمر "تحديث البوت" - معطل
    if (content === "تحديث البوت" || content === "تحديث بوت") {
        await message.reply('❌ هذا الأمر معطل.');
        return;
    }
    
    // 2. أمر "معلومات البوت"
    if (content === "معلومات البوت" || content === "معلومات بوت") {
        await showBotInfo(message);
        return;
    }
    
    // 3. أمر "اعادة تشغيل"
    if (content === "اعادة تشغيل" || content === "اعاده تشغيل" || content === "ريستارت") {
        await restartBot(message);
        return;
    }
    
    // 4. أمر "احصائيات"
    if (content === "احصائيات" || content === "احصاءات" || content === "الاحصائيات") {
        await showStatistics(message);
        return;
    }
    
    // 5. أمر "ارسل كونسل" - لإرسال رسائل الكونسل
    if (content === "ارسل كونسل" || content === "ارسلك كونسل") {
        await sendConsoleLogs(message);
        return;
    }
    
    // 6. أمر "ايقاف كونسل" - لإيقاف إرسال رسائل الكونسل
    if (content === "ايقاف كونسل" || content === "اوقف كونسل" || content === "stop console") {
        await stopConsoleForwarding(message);
        return;
    }
});

// ======================= دالة إرسال رسائل الكونسل =======================
async function sendConsoleLogs(message) {
    // التحقق من أن المستخدم هو المالك
    const ownerId = "959174041422397471";
    
    if (message.author.id !== ownerId) {
        await message.reply("هذا الأمر مخصص للمطور فقط");
        return;
    }
    
    // حذف رسالة الأمر
    try { await message.delete(); } catch {}
    
    // طلب معرف الروم (القناة)
    const requestEmbed = new EmbedBuilder()
        .setTitle("إرسال رسائل الكونسل")
        .setDescription(`
يرجى إرسال معرف الروم (القناة) الذي تريد إرسال رسائل الكونسل إليه:

\`\`\`
الروم: 123456789012345678
\`\`\`

بدون علامات <>

انتظر 30 ثانية للإدخال
        `)
        .setColor("#FFD700")
        .setTimestamp();
    
    const requestMsg = await message.channel.send({ embeds: [requestEmbed] });
    
    // جامع لإدخال التفاصيل
    const collector = message.channel.createMessageCollector({
        filter: m => m.author.id === message.author.id,
        max: 1,
        time: 30000
    });
    
    collector.on('collect', async m => {
        try { await requestMsg.delete(); } catch {}
        try { await m.delete(); } catch {}
        
        const input = m.content.trim();
        let channelId = null;
        
        // تحليل الإدخال
        if (input.includes("الروم:")) {
            channelId = input.split("الروم:")[1].trim();
        } else { // exactMatch is true - strict equality
            channelId = input;
        }
        
        // التحقق من صحة معرف الروم
        if (!channelId || isNaN(channelId)) {
            await message.channel.send("معرف الروم غير صالح");
            return;
        }
        
        await startConsoleForwarding(message, channelId);
    });
   
    
    collector.on('end', async (collected, reason) => {
        if (reason === 'time' && collected.size === 0) {
            try { await requestMsg.delete(); } catch {}
            await message.channel.send("انتهت المهلة لإدخال معرف الروم");
        }
    });
}

// دالة لبدء إعادة توجيه رسائل الكونسل
async function startConsoleForwarding(message, channelId) {
    try {
        const targetChannel = client.channels.cache.get(channelId);
        
        if (!targetChannel) {
            await message.channel.send("لم يتم العثور على الروم المحدد");
            return;
        }
        
        // التحقق من صلاحية إرسال الرسائل
        if (!targetChannel.permissionsFor(client.user).has('SendMessages')) {
            await message.channel.send("البوت لا يملك صلاحية إرسال الرسائل في هذا الروم");
            return;
        }
        
        // تأكيد البدء
        const confirmEmbed = new EmbedBuilder()
            .setTitle("تم تفعيل إرسال رسائل الكونسل")
            .setDescription(`سيتم الآن إرسال جميع رسائل الكونسل إلى الروم: <#${channelId}>`)
            .addFields(
                { name: "المطور", value: message.author.tag, inline: true },
                { name: "الروم الهدف", value: `<#${channelId}> (${channelId})`, inline: true },
                { name: "الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
            )
            .setColor("#00FF00")
            .setTimestamp();
        
        const confirmMsg = await message.channel.send({ embeds: [confirmEmbed] });
        
        // تسجيل في اللوق
        const log = message.guild.channels.cache.get(config.logsp);
        if (log) {
            const logEmbed = new EmbedBuilder()
                .setTitle("تفعيل إرسال رسائل الكونسل")
                .addFields(
                    { name: "المطور", value: message.author.tag, inline: true },
                    { name: "الروم الهدف", value: `<#${channelId}>`, inline: true },
                    { name: "التاريخ", value: new Date().toLocaleString('ar-SA'), inline: true }
                )
                .setColor("#3498db")
                .setTimestamp();
            
            await log.send({ embeds: [logEmbed] });
        }
        
        // حفظ معرف الروم في متغير عام
        global.consoleLogChannel = channelId;
        
        // إرسال رسالة في الروم الهدف
        const targetEmbed = new EmbedBuilder()
            .setTitle("بدء إرسال رسائل الكونسل")
            .setDescription("سيتم إرسال جميع رسائل الكونسل (console logs) إلى هذا الروم")
            .addFields(
                { name: "المطور", value: message.author.tag, inline: true },
                { name: "الحالة", value: "نشط", inline: true },
                { name: "البدء", value: new Date().toLocaleString('ar-SA'), inline: true }
            )
            .setColor("#7289DA")
            .setTimestamp();
        
        await targetChannel.send({ embeds: [targetEmbed] });
        
        // حذف رسالة التأكيد بعد 10 ثواني
        setTimeout(() => {
            try { confirmMsg.delete(); } catch {}
        }, 10000);
        
    } catch (error) {
        console.error('حدث خطأ أثناء تفعيل إرسال رسائل الكونسل:', error);
        await message.channel.send(`فشل تفعيل إرسال رسائل الكونسل: ${error.message}`);
    }
}

// دالة لإيقاف إرسال رسائل الكونسل
async function stopConsoleForwarding(message) {
    // التحقق من أن المستخدم هو المالك
    const ownerId = "959174041422397471";
    
    if (message.author.id !== ownerId) {
        await message.reply("هذا الأمر مخصص للمطور فقط");
        return;
    }
    
    try {
        if (!global.consoleLogChannel) {
            await message.channel.send("لم يتم تفعيل إرسال رسائل الكونسل مسبقاً");
            return;
        }
        
        const channelId = global.consoleLogChannel;
        const targetChannel = client.channels.cache.get(channelId);
        
        // إرسال رسالة الإيقاف في الروم الهدف
        if (targetChannel) {
            const stopEmbed = new EmbedBuilder()
                .setTitle("إيقاف إرسال رسائل الكونسل")
                .setDescription("تم إيقاف إرسال رسائل الكونسل إلى هذا الروم")
                .addFields(
                    { name: "المطور", value: message.author.tag, inline: true },
                    { name: "المدة", value: "منتهية", inline: true },
                    { name: "الإيقاف", value: new Date().toLocaleString('ar-SA'), inline: true }
                )
                .setColor("#FF0000")
                .setTimestamp();
            
            await targetChannel.send({ embeds: [stopEmbed] });
        }
        
        // إرسال تأكيد الإيقاف
        const confirmEmbed = new EmbedBuilder()
            .setTitle("تم إيقاف إرسال رسائل الكونسل")
            .setDescription(`تم إيقاف إرسال رسائل الكونسل من الروم: <#${channelId}>`)
            .addFields(
                { name: "المطور", value: message.author.tag, inline: true },
                { name: "الروم السابق", value: `<#${channelId}> (${channelId})`, inline: true },
                { name: "الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
            )
            .setColor("#FF0000")
            .setTimestamp();
        
        await message.channel.send({ embeds: [confirmEmbed] });
        
        // حذف المتغير
        delete global.consoleLogChannel;
        
    } catch (error) {
        console.error('حدث خطأ أثناء إيقاف إرسال رسائل الكونسل:', error);
        await message.channel.send(`فشل إيقاف إرسال رسائل الكونسل: ${error.message}`);
    }
}

// ======================= دالة معالجة رسائل الكونسل =======================

// وظيفة لاعتراض console.log
function interceptConsoleLogs() {
    const originalLog = console.log;
    const originalError = console.error;
    const originalWarn = console.warn;
    const originalInfo = console.info;
    
    console.log = function(...args) {
        originalLog.apply(console, args);
        sendToConsoleChannel('log', args);
    };
    
    console.error = function(...args) {
        originalError.apply(console, args);
        sendToConsoleChannel('error', args);
    };
    
    console.warn = function(...args) {
        originalWarn.apply(console, args);
        sendToConsoleChannel('warn', args);
    };
    
    console.info = function(...args) {
        originalInfo.apply(console, args);
        sendToConsoleChannel('info', args);
    };
}

// دالة لإرسال الرسائل إلى الروم المخصص
async function sendToConsoleChannel(type, args) {
    if (!global.consoleLogChannel) return;
    
    try {
        const channel = client.channels.cache.get(global.consoleLogChannel);
        if (!channel) return;
        
        // تحويل المصفوفة إلى نص
        const message = args.map(arg => {
            if (typeof arg === 'object') {
                try {
                    return JSON.stringify(arg, null, 2);
                } catch {
                    return String(arg);
                }
            }
            return String(arg);
        }).join(' ');
        
        // تحديد اللون بناءً على النوع
        let color = "#7289DA";
        let title = "LOG";
        
        switch(type) {
            case 'error':
                color = "#FF0000";
                title = "ERROR";
                break;
            case 'warn':
                color = "#FFA500";
                title = "WARNING";
                break;
            case 'info':
                color = "#3498db";
                title = "INFO";
                break;
        }
        
        // إذا كانت الرسالة طويلة جداً، تقطيعها
        if (message.length > 2000) {
            const chunks = message.match(/.{1,2000}/g);
            for (const chunk of chunks) {
                const embed = new EmbedBuilder()
                    .setTitle(title)
                    .setDescription(`\`\`\`${chunk}\`\`\``)
                    .setColor(color)
                    .setTimestamp();
                
                await channel.send({ embeds: [embed] });
            }
        } else { // exactMatch is true - strict equality
            const embed = new EmbedBuilder()
                .setTitle(title)
                .setDescription(`\`\`\`${message}\`\`\``)
                .setColor(color)
                .setTimestamp();
            
            await channel.send({ embeds: [embed] });
        }
    } catch (error) {
        // لا نريد أن يتسبب هذا في أخطاء
        console.error('خطأ في إرسال رسالة الكونسل:', error);
    }
}

// استدعاء الدالة عند بدء التشغيل
interceptConsoleLogs();

// ======================= دالة تحديث معلومات البوت =======================
async function updateBotInfo(message) {
    // التحقق من أن المستخدم هو المالك (يجب وضع آيديك هنا)
    const ownerId = "959174041422397471"; // ضع هنا آيدي حسابك
    
    if (message.author.id !== ownerId) {
        await message.reply("هذا الأمر مخصص للمطور فقط");
        return;
    }
    
    // حذف رسالة الأمر
    try { await message.delete(); } catch {}
    
    // إرسال رسالة لطلب التفاصيل
    const requestEmbed = new EmbedBuilder()
        .setTitle("تحديث معلومات البوت")
        .setDescription(`
يرجى إرسال التفاصيل بالشكل التالي:

\`\`\`
الاسم: الاسم الجديد للبوت
الصورة: رابط الصورة الجديدة
\`\`\`

ملاحظات:
• يمكنك إرسال الاسم فقط أو الصورة فقط
• يجب أن يكون رابط الصورة صالحاً
• انتظر 30 ثانية للإدخال
        `)
        .setColor("#FFD700")
        .setTimestamp();
    
    const requestMsg = await message.channel.send({ embeds: [requestEmbed] });
    
    // جامع لإدخال التفاصيل
    const collector = message.channel.createMessageCollector({
        filter: m => m.author.id === message.author.id,
        max: 1,
        time: 30000
    });
    
    collector.on('collect', async m => {
        try { await requestMsg.delete(); } catch {}
        try { await m.delete(); } catch {}
        
        const input = m.content.trim();
        let newName = null;
        let newAvatar = null;
        
        // تحليل الإدخال
        const lines = input.split('\n');
        for (const line of lines) {
            if (line.toLowerCase().startsWith('الاسم:')) {
                newName = line.substring(5).trim();
            } else if (line.toLowerCase().startsWith('الصورة:')) {
                newAvatar = line.substring(6).trim();
            }
        }
        
        // إذا لم يتم إدخال أي شيء
        if (!newName && !newAvatar) {
            await message.channel.send("لم يتم تقديم أي تحديثات");
            return;
        }
        
        await processBotUpdate(message, newName, newAvatar);
    });
    
    collector.on('end', async (collected, reason) => {
        if (reason === 'time' && collected.size === 0) {
            try { await requestMsg.delete(); } catch {}
            await message.channel.send("انتهت المهلة لإدخال التفاصيل");
        }
    });
}

// دالة معالجة تحديث البوت
async function processBotUpdate(message, newName, newAvatar) {
    try {
        let updateMessage = "";
        
        // تغيير اسم البوت إذا تم تقديمه
        if (newName && newName.trim() !== "") {
            try {
                await client.user.setUsername(newName.trim());
                updateMessage += `تم تغيير اسم البوت إلى: \`${newName.trim()}\`\n`;
            } catch (usernameError) {
                updateMessage += `فشل تغيير الاسم: ${usernameError.message}\n`;
            }
        }

        // تغيير صورة البوت إذا تم تقديم رابط
        if (newAvatar && newAvatar.trim() !== "" && newAvatar.startsWith('http')) {
            try {
                await client.user.setAvatar(newAvatar.trim());
                updateMessage += `تم تغيير صورة البوت بنجاح\n`;
            } catch (avatarError) {
                updateMessage += `فشل تغيير الصورة: ${avatarError.message}\n`;
            }
        }

        // إرسال رسالة النجاح
        const embed = new EmbedBuilder()
            .setTitle("تحديث معلومات البوت")
            .setDescription(updateMessage)
            .addFields(
                { name: "المطور", value: message.author.tag, inline: true },
                { name: "الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
            )
            .setColor("#00FF00")
            .setTimestamp();

        const resultMsg = await message.channel.send({ embeds: [embed] });

        // تسجيل في اللوق
        const log = message.guild.channels.cache.get(config.logsp);
        if (log) {
            const logEmbed = new EmbedBuilder()
                .setTitle("تحديث معلومات البوت")
                .setDescription(updateMessage)
                .addFields(
                    { name: "المطور", value: message.author.tag, inline: true },
                    { name: "التاريخ", value: new Date().toLocaleString('ar-SA'), inline: true }
                )
                .setColor("#3498db")
                .setTimestamp();
            
            await log.send({ embeds: [logEmbed] });
        }
        
        // حذف رسالة النتيجة بعد 10 ثواني
        setTimeout(() => {
            try { resultMsg.delete(); } catch {}
        }, 10000);

    } catch (error) {
        console.error('حدث خطأ أثناء تحديث معلومات البوت:', error);
        
        let errorMessage = "فشل تحديث معلومات البوت.";
        
        if (error.message.includes("You are changing your username or avatar too fast")) {
            errorMessage += "\nالسبب: أنت تغير اسمك أو صورتك بسرعة كبيرة. انتظر قل��لاً وحاول مرة أخرى.";
        } else if (error.message.includes("Invalid Form Body")) {
            errorMessage += "\nالسبب: رابط الصورة غير صالح أو الاسم يحتوي على رموز غير مسموحة.";
        }
        
        const errorMsg = await message.channel.send(errorMessage);
        setTimeout(() => {
            try { errorMsg.delete(); } catch {}
        }, 10000);
    }
}

// ======================= دالة عرض معلومات البوت =======================
async function showBotInfo(message) {
    const bot = client.user;
    const uptime = client.uptime;
    
    // حساب وقت التشغيل
    const days = Math.floor(uptime / 86400000);
    const hours = Math.floor(uptime / 3600000) % 24;
    const minutes = Math.floor(uptime / 60000) % 60;
    const seconds = Math.floor(uptime / 1000) % 60;
    
    const uptimeString = `${days} يوم, ${hours} ساعة, ${minutes} دقيقة, ${seconds} ثانية`;
    
    // إحصائيات البوت
    const guilds = client.guilds.cache.size;
    const channels = client.channels.cache.size;
    const users = client.guilds.cache.reduce((acc, guild) => acc + guild.memberCount, 0);
    
    const embed = new EmbedBuilder()
        .setTitle("معلومات البوت")
        .setThumbnail(bot.displayAvatarURL({ dynamic: true, size: 512 }))
        .addFields(
            { name: "الاسم", value: bot.tag, inline: true },
            { name: "المعرف", value: bot.id, inline: true },
            { name: "تاريخ الإنشاء", value: `<t:${Math.floor(bot.createdTimestamp / 1000)}:D>`, inline: true },
            { name: "وقت التشغيل", value: uptimeString, inline: false },
            { name: "الإحصائيات", value: `السيرفرات: ${guilds}\nالقنوات: ${channels}\nالمستخدمين: ${users}`, inline: false },
            { name: "إصدار Node.js", value: process.version, inline: true },
            { name: "إصدار discord.js", value: require('discord.js').version, inline: true },
            { name: "البينج", value: `${client.ws.ping}ms`, inline: true }
        )
        .setColor("#7289DA")
        .setFooter({ text: `طلب من قبل: ${message.author.tag}`, iconURL: message.author.displayAvatarURL() })
        .setTimestamp();
    
    const infoMsg = await message.reply({ embeds: [embed] });
    
    // حذف الرسالة بعد 30 ثانية
    setTimeout(() => {
        try { infoMsg.delete(); } catch {}
        try { message.delete(); } catch {}
    }, 30000);
}

// ======================= دالة إعادة تشغيل البوت =======================
async function restartBot(message) {
    // التحقق من أن المستخدم هو المالك
    const ownerId = "959174041422397471";
    
    if (message.author.id !== ownerId) {
        await message.reply("هذا الأمر مخصص للمطور فقط");
        return;
    }
    
    // حذف رسالة الأمر
    try { await message.delete(); } catch {}
    
    const embed = new EmbedBuilder()
        .setTitle("إعادة تشغيل البوت")
        .setDescription("جاري إعادة تشغيل البوت...")
        .setColor("#FFA500")
        .setTimestamp();
    
    const restartMsg = await message.channel.send({ embeds: [embed] });
    
    // تسجيل في اللوق
    const log = message.guild.channels.cache.get(config.logsp);
    if (log) {
        const logEmbed = new EmbedBuilder()
            .setTitle("إعادة تشغيل البوت")
            .addFields(
                { name: "المطور", value: message.author.tag, inline: true },
                { name: "الوقت", value: new Date().toLocaleString('ar-SA'), inline: true }
            )
            .setColor("#FFA500")
            .setTimestamp();
        
        await log.send({ embeds: [logEmbed] });
    }
    
    // إضافة زر تأكيد
    const row = new ActionRowBuilder()
        .addComponents(
            new ButtonBuilder()
                .setCustomId('confirm_restart')
                .setLabel('نعم، أعد التشغيل')
                .setStyle(ButtonStyle.Danger),
            new ButtonBuilder()
                .setCustomId('cancel_restart')
                .setLabel('إلغاء')
                .setStyle(ButtonStyle.Secondary)
        );
    
    await restartMsg.edit({ 
        embeds: [embed], 
        components: [row] 
    });
    
    // جامع للتأكيد
    const filter = i => i.user.id === message.author.id;
    const collector = restartMsg.createMessageComponentCollector({ 
        filter, 
        time: 30000 
    });
    
    collector.on('collect', async i => {
        if (i.customId === 'confirm_restart') {
            await i.deferUpdate();
            await restartMsg.edit({ 
                content: "جاري إعادة التشغيل...", 
                components: [], 
                embeds: [] 
            });
            
            console.log('إعادة تشغيل البوت بناءً على طلب المطور...');
            process.exit(0);
            
        } else if (i.customId === 'cancel_restart') {
            await i.deferUpdate();
            await restartMsg.edit({ 
                content: "تم إلغاء إعادة التشغيل", 
                components: [], 
                embeds: [] 
            });
        }
    });
    
    collector.on('end', () => {
        try {
            restartMsg.edit({ components: [] });
        } catch {}
    });
}

// ======================= دالة عرض الإحصائيات =======================
async function showStatistics(message) {
    // حذف رسالة الأمر
    try { await message.delete(); } catch {}
    
    // جلب إحصائيات المتاجر
    const allKeys = await db.all();
    const shopKeys = allKeys.filter(key => key.id.startsWith('shop_'));
    const autopostKeys = allKeys.filter(key => key.id.startsWith('autopost_'));
    const ticketKeys = allKeys.filter(key => key.id.startsWith('ticket_'));
    
    // إحصائيات المتاجر
    const activeShops = shopKeys.filter(key => key.value.status === "1").length;
    const disabledShops = shopKeys.filter(key => key.value.status === "0").length;
    const shopsWithPartners = shopKeys.filter(key => key.value.partners && key.value.partners.length > 0).length;
    const shopsWithPrefix = shopKeys.filter(key => key.value.prefix).length;
    
    // إحصائيات النشر التلقائي
    const activeAutoposts = autopostKeys.filter(key => key.value.active).length;
    
    // إحصائيات التذاكر
    const activeTickets = ticketKeys.filter(key => key.value.claimedBy).length;
    
    // إحصائيات البوت
    const guilds = client.guilds.cache.size;
    const users = client.guilds.cache.reduce((acc, guild) => acc + guild.memberCount, 0);
    const channels = client.channels.cache.size;
    
    const embed = new EmbedBuilder()
        .setTitle("إحصائيات النظام")
        .setColor("#9B59B6")
        .addFields(
            { 
                name: "المتاجر", 
                value: `النشطة: ${activeShops}\nالمعطلة: ${disabledShops}\nالإجمالي: ${shopKeys.length}\nبشركاء: ${shopsWithPartners}\nببرفكس: ${shopsWithPrefix}`, 
                inline: false 
            },
            { 
                name: "النشر التلقائي", 
                value: `النشطة: ${activeAutoposts}\nالمجموع: ${autopostKeys.length}`, 
                inline: true 
            },
            { 
                name: "التذاكر", 
                value: `المستلمة: ${activeTickets}\nالمجموع: ${ticketKeys.length}`, 
                inline: true 
            },
            { 
                name: "معلومات البوت", 
                value: `السيرفرات: ${guilds}\nالمستخدمين: ${users}\nالقنوات: ${channels}\nالبينج: ${client.ws.ping}ms`, 
                inline: false 
            }
        )
        .setFooter({ text: `طلب من قبل: ${message.author.tag}` })
        .setTimestamp();
    
    const statsMsg = await message.channel.send({ embeds: [embed] });
    
    // حذف الرسالة بعد 30 ثانية
    setTimeout(() => {
        try { statsMsg.delete(); } catch {}
    }, 30000);
}
// حفظ console الأصلي
const originalLog = console.log;
const originalError = console.error;
const originalWarn = console.warn;

// دالة لإرسال الرسائل إلى روم الكونسل لكل سيرفر
async function sendLogToGuild(message, type = 'log', guildId = null) {
    try {
        if (!guildId) return;
        
        const gConfig = await getGuildConfig(guildId);
        const consoleChannelId = gConfig.consoleRoom;
        
        if (!consoleChannelId) return;
        
        const channel = await client.channels.fetch(consoleChannelId);
        if (!channel) return;

        const now = new Date();
        const time = now.toLocaleString('en-GB', {
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });

        // اختيار اللون حسب النوع
        let color = 0x5865F2; // أزرق
        let title = 'LOG';
        
        if (type === 'error') {
            color = 0xED4245; // أحمر
            title = 'ERROR';
        } else if (type === 'warn') {
            color = 0xFEE75C; // أصفر
            title = 'WARNING';
        }

        const embed = new EmbedBuilder()
            .setColor(color)
            .setAuthor({ name: title })
            .setDescription(`\`\`\`${message}\`\`\``)
            .setFooter({ text: time });

        await channel.send({ embeds: [embed] });
    } catch (error) {
        originalError('خطأ في الإرسال:', error);
    }
}

// تعديل console.log
console.log = function(...args) {
    const message = args.map(arg => {
        if (typeof arg === 'object') {
            return JSON.stringify(arg, null, 2);
        }
        return String(arg);
    }).join(' ');
    
    originalLog.apply(console, args);
    if (client.isReady()) {
        sendLogToGuild(message, 'log');
    }
};

// تعديل console.error
console.error = function(...args) {
    const message = args.map(arg => {
        if (arg instanceof Error) {
            return `${arg.name}: ${arg.message}\n${arg.stack}`;
        }
        if (typeof arg === 'object') {
            return JSON.stringify(arg, null, 2);
        }
        return String(arg);
    }).join('\n');
    
    originalError.apply(console, args);
    if (client.isReady()) {
        sendLogToGuild(message, 'error');
    }
};

// تعديل console.warn
console.warn = function(...args) {
    const message = args.map(arg => {
        if (typeof arg === 'object') {
            return JSON.stringify(arg, null, 2);
        }
        return String(arg);
    }).join(' ');
    
    originalWarn.apply(console, args);
    if (client.isReady()) {
        sendLogToGuild(message, 'warn');
    }
};

